export default {
    plugins: {
        "@tailwindcss/postcss": {},
    },
};

"use client";

import { useEffect, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import { Button } from "@/components/ui/Button";
import { Input } from "@/components/ui/Input";
import { ArrowLeft, Save, Loader2, Check } from "lucide-react";
import { firestoreService } from "@/services/firestoreService";
import { Bundle, Test } from "@/types/admin";
import Link from "next/link";
import { useAuth } from "@/context/AuthContext";

export default function BundleEditorPage() {
    const params = useParams();
    const router = useRouter();
    const { user } = useAuth();
    const bundleId = params.bundleId as string;
    const isNew = bundleId === 'new';

    const [bundle, setBundle] = useState<Partial<Bundle>>({
        name: "",
        description: "",
        includedTests: [],
        price: 0,
        originalPrice: 0,
        isActive: false
    });

    const [allTests, setAllTests] = useState<Test[]>([]);
    const [loading, setLoading] = useState(!isNew);
    const [saving, setSaving] = useState(false);
    const [searchTerm, setSearchTerm] = useState("");

    useEffect(() => {
        loadData();
    }, [bundleId]);

    async function loadData() {
        setLoading(true);
        // Load all tests for selection
        const tests = await firestoreService.getTests();
        setAllTests(tests);

        if (!isNew) {
            const found = await firestoreService.getBundle(bundleId);
            if (found) {
                setBundle(found);
            } else {
                router.push("/admin/management?tab=bundles");
            }
        }
        setLoading(false);
    }

    async function handleSave() {
        setSaving(true);
        try {
            if (isNew) {
                await firestoreService.createBundle(bundle);
            } else {
                await firestoreService.updateBundle(bundleId, bundle);
            }
            router.push("/admin/management?tab=bundles");
        } catch (error) {
            console.error("Failed to save bundle:", error);
            alert("Failed to save bundle. Please try again.");
        } finally {
            setSaving(false);
        }
    }

    function toggleTestSelection(testId: string) {
        const currentSelected = bundle.includedTests || [];
        const isSelected = currentSelected.includes(testId);

        let newSelected;
        if (isSelected) {
            newSelected = currentSelected.filter(id => id !== testId);
        } else {
            newSelected = [...currentSelected, testId];
        }

        setBundle({ ...bundle, includedTests: newSelected });
    }

    if (loading) return (
        <div className="p-8 flex justify-center items-center">
            <Loader2 className="h-6 w-6 animate-spin text-blue-500 mr-2" /> Loading...
        </div>
    );

    const filteredTests = allTests.filter(t =>
        t.title.toLowerCase().includes(searchTerm.toLowerCase())
    );

    return (
        <div className="space-y-6 animate-in fade-in max-w-4xl mx-auto pb-20">
            <div className="flex items-center justify-between">
                <div className="flex items-center gap-4">
                    <Link href="/admin/management?tab=bundles">
                        <Button variant="ghost" size="sm" className="gap-2 text-slate-500">
                            <ArrowLeft className="h-4 w-4" /> Back
                        </Button>
                    </Link>
                    <h1 className="text-2xl font-bold text-slate-900">
                        {isNew ? "Create New Bundle" : `Edit ${bundle.name}`}
                    </h1>
                </div>
                <div className="flex gap-2">
                    <Button
                        variant={bundle.isActive ? "primary" : "outline"}
                        className={bundle.isActive ? "bg-green-600 hover:bg-green-700" : ""}
                        onClick={() => setBundle({ ...bundle, isActive: !bundle.isActive })}
                    >
                        {bundle.isActive ? 'Active' : 'Inactive'}
                    </Button>
                    <Button onClick={handleSave} disabled={saving} className="gap-2 bg-blue-600 hover:bg-blue-700 text-white">
                        <Save className="h-4 w-4" /> {saving ? "Saving..." : "Save Bundle"}
                    </Button>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                {/* Main Details */}
                <div className="lg:col-span-2 space-y-6">
                    <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 space-y-4">
                        <h3 className="font-semibold text-slate-900 border-b border-slate-100 pb-2">Basic Information</h3>
                        <div className="grid gap-4">
                            <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">Bundle Name</label>
                                <Input
                                    value={bundle.name}
                                    onChange={(e) => setBundle({ ...bundle, name: e.target.value })}
                                    placeholder="e.g., Complete Science Mock Package"
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">Description</label>
                                <textarea
                                    className="w-full px-3 py-2 bg-white border border-slate-300 rounded-lg text-sm outline-none focus:ring-2 focus:ring-blue-500 transition-all min-h-[100px]"
                                    value={bundle.description}
                                    onChange={(e) => setBundle({ ...bundle, description: e.target.value })}
                                    placeholder="What does this bundle include?"
                                />
                            </div>
                        </div>
                    </div>

                    {/* Test Selection */}
                    <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 space-y-4">
                        <div className="flex justify-between items-center border-b border-slate-100 pb-2">
                            <h3 className="font-semibold text-slate-900">Included Tests</h3>
                            <span className="text-sm text-slate-500">{bundle.includedTests?.length || 0} selected</span>
                        </div>

                        <div className="relative">
                            <Input
                                placeholder="Search tests to include..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                className="mb-4"
                            />
                        </div>

                        <div className="max-h-[400px] overflow-y-auto space-y-2 border border-slate-100 rounded-lg p-2">
                            {filteredTests.map(test => {
                                const isSelected = bundle.includedTests?.includes(test.id);
                                return (
                                    <div
                                        key={test.id}
                                        onClick={() => toggleTestSelection(test.id)}
                                        className={`flex items-center justify-between p-3 rounded-lg cursor-pointer transition-colors border ${isSelected
                                            ? 'bg-blue-50 border-blue-200'
                                            : 'hover:bg-slate-50 border-transparent hover:border-slate-200'
                                            }`}
                                    >
                                        <div>
                                            <p className={`font-medium text-sm ${isSelected ? 'text-blue-900' : 'text-slate-900'}`}>{test.title}</p>
                                            <div className="flex gap-2 text-xs text-slate-500 mt-0.5">
                                                <span>{test.questions?.length || 0} Qs</span>
                                                <span>•</span>
                                                <span>{test.category}</span>
                                            </div>
                                        </div>
                                        {isSelected && (
                                            <div className="bg-blue-600 rounded-full p-1 text-white">
                                                <Check className="h-3 w-3" />
                                            </div>
                                        )}
                                    </div>
                                );
                            })}
                            {filteredTests.length === 0 && (
                                <p className="text-center text-slate-500 py-4 text-sm">No tests found matching search.</p>
                            )}
                        </div>
                    </div>
                </div>

                {/* Sidebar Settings */}
                <div className="space-y-6">
                    <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 space-y-4">
                        <h3 className="font-semibold text-slate-900 border-b border-slate-100 pb-2">Pricing</h3>
                        <div className="space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">Price (₹)</label>
                                <Input
                                    type="number"
                                    value={bundle.price}
                                    onChange={(e) => setBundle({ ...bundle, price: parseFloat(e.target.value) })}
                                    min={0}
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">Original Price (₹)</label>
                                <Input
                                    type="number"
                                    value={bundle.originalPrice}
                                    onChange={(e) => setBundle({ ...bundle, originalPrice: parseFloat(e.target.value) })}
                                    min={0}
                                    placeholder="Optional (for strike-through)"
                                />
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import { Button } from "@/components/ui/Button";
import { Input } from "@/components/ui/Input";
import { Save, AlertCircle, Loader2 } from "lucide-react";
import { firestoreService } from "@/services/firestoreService";
import { CMSContent } from "@/types/admin";
import { useAuth } from "@/context/AuthContext";
import { STRUCTURED_EDITORS } from "@/components/admin/cms/CUET2026Editors";

export default function CMSPage() {
    const { userData } = useAuth();
    const [content, setContent] = useState<CMSContent[]>([]);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);

    const isDeveloper = userData?.role === 'developer';

    useEffect(() => {
        async function loadContent() {
            setLoading(true);
            const data = await firestoreService.getCMSContent();
            setContent(data);
            setLoading(false);
        }
        loadContent();
    }, []);

    async function handleUpdate(id: string, value: string) {
        const newContent = content.map(c => c.id === id ? { ...c, value } : c);
        setContent(newContent);
    }

    async function handleSave() {
        setSaving(true);
        let successCount = 0;
        for (const item of content) {
            if (item.editableBy === 'developer' && !isDeveloper) continue;
            const success = await firestoreService.updateCMSContent(item.id, item.value);
            if (success) successCount++;
        }
        setSaving(false);
        if (successCount > 0) {
            alert("Content updated successfully!");
        }
    }

    async function handlePrefillCUET2026() {
        setSaving(true);
        const defaultKeys = [
            { key: 'syllabus_content', value: JSON.stringify([{ id: '1', subject: 'Accountancy', domain: 'Commerce', coreTopics: ['Accounting for Not-for-Profit Organisations', 'Partnership', 'Company Accounts'], difficulty: 'medium' }]) },
            { key: 'exam_strategy_content', value: JSON.stringify([{ id: '1', title: 'Understand the Syllabus', description: 'Start by thoroughly reviewing the official CUET syllabus for your chosen domains.', icon: 'BookOpen' }]) },
            { key: 'important_dates_content', value: JSON.stringify([{ id: '1', date: 'Feb 2026', title: 'Application Form Release', description: 'Online submission of application forms begins.', type: 'registration' }]) },
            { key: 'college_preferences_content', value: JSON.stringify([{ id: '1', tier: 'Tier 1', description: 'Top North Campus Colleges', colleges: ['SRCC', 'Hindu', 'Stephen\'s'] }]) }
        ];

        let added = 0;
        for (const def of defaultKeys) {
            const exists = content.find(c => c.section === 'cuet2026' && c.key === def.key);
            if (!exists) {
                await firestoreService.createCMSContent({
                    section: 'cuet2026',
                    key: def.key,
                    value: def.value,
                    editableBy: 'admin'
                });
                added++;
            }
        }

        if (added > 0) {
            alert(`Successfully prefilled ${added} sections. Reloading...`);
            const data = await firestoreService.getCMSContent();
            setContent(data);
        } else {
            alert("All sections are already present.");
        }
        setSaving(false);
    }

    async function handlePrefillLanding() {
        setSaving(true);
        const defaultKeys = [
            { key: 'student_stories', value: JSON.stringify([{ id: '1', url: 'https://images.unsplash.com/photo-1543269865-cbf427effbad?w=400&h=400&fit=crop', altText: 'Student Success', name: 'Aaditya', college: 'SRCC' }]) }
        ];

        let added = 0;
        for (const def of defaultKeys) {
            const exists = content.find(c => c.section === 'landing' && c.key === def.key);
            if (!exists) {
                await firestoreService.createCMSContent({
                    section: 'landing',
                    key: def.key,
                    value: def.value,
                    editableBy: 'admin'
                });
                added++;
            }
        }

        if (added > 0) {
            alert(`Successfully prefilled ${added} sections. Reloading...`);
            const data = await firestoreService.getCMSContent();
            setContent(data);
        } else {
            alert("All sections are already present.");
        }
        setSaving(false);
    }

    if (loading) return (
        <div className="p-8 flex justify-center items-center">
            <Loader2 className="h-6 w-6 animate-spin text-blue-500 mr-2" /> Loading CMS data...
        </div>
    );

    const heroSection = content.filter(c => c.section === 'hero');
    const pricingSection = content.filter(c => c.section === 'pricing');
    const landingSection = content.filter(c => c.section === 'landing');
    const cuet2026Section = content.filter(c => c.section === 'cuet2026');

    const canEdit = (item: CMSContent) => {
        if (item.editableBy === 'developer') return isDeveloper;
        return true;
    };

    return (
        <div className="space-y-6 animate-in fade-in max-w-4xl">
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-2xl font-bold text-slate-900">Content Management</h1>
                    <p className="text-slate-500 mt-1">Edit website content directly.</p>
                </div>
                <Button onClick={handleSave} disabled={saving} className="gap-2 bg-blue-600 hover:bg-blue-700 text-white">
                    <Save className="h-4 w-4" /> {saving ? "Saving..." : "Save Changes"}
                </Button>
            </div>

            <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 flex gap-3 text-blue-800 text-sm">
                <AlertCircle className="h-5 w-5 shrink-0" />
                <p>Changes made here will be instantly visible on the live website.</p>
            </div>

            {/* Hero Section */}
            {heroSection.length > 0 && (
                <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 space-y-6">
                    <h3 className="font-bold text-slate-900 border-b border-slate-100 pb-2">Hero Section</h3>

                    {heroSection.map(item => (
                        <div key={item.id} className={canEdit(item) ? "" : "opacity-50 pointer-events-none"}>
                            <div className="flex justify-between">
                                <label className="block text-sm font-medium text-slate-700 mb-1 capitalize">
                                    {item.key}
                                </label>
                                {!canEdit(item) && <span className="text-xs text-slate-400">Developer Only</span>}
                            </div>
                            <textarea
                                className="w-full px-3 py-2 bg-white border border-slate-300 rounded-lg text-sm outline-none focus:ring-2 focus:ring-blue-500 transition-all min-h-[80px]"
                                value={item.value}
                                onChange={(e) => handleUpdate(item.id, e.target.value)}
                                disabled={!canEdit(item)}
                            />
                        </div>
                    ))}
                </div>
            )}

            {/* Landing Page Section */}
            <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 space-y-6">
                <div className="flex justify-between items-center border-b border-slate-100 pb-2">
                    <h3 className="font-bold text-slate-900 flex items-center gap-2">
                        Landing Page Interactive Elements
                    </h3>
                    {landingSection.length < 1 && (
                        <Button
                            onClick={handlePrefillLanding}
                            disabled={saving}
                            variant="outline"
                            size="sm"
                            className="bg-purple-50 text-purple-700 border-purple-200 hover:bg-purple-100 transition-colors"
                        >
                            Prefill Data
                        </Button>
                    )}
                </div>
                {landingSection.length > 0 && landingSection.map(item => {
                    const EditorComponent = STRUCTURED_EDITORS[item.key];
                    return (
                        <div key={item.id} className={canEdit(item) ? "" : "opacity-50 pointer-events-none"}>
                            <div className="flex justify-between mb-2">
                                <label className="block text-sm font-bold text-slate-800 capitalize">
                                    {item.key.replace(/_/g, ' ')}
                                </label>
                                {!canEdit(item) && <span className="text-xs text-slate-400">Developer Only</span>}
                            </div>
                            {EditorComponent ? (
                                <EditorComponent
                                    value={item.value}
                                    onChange={(v: string) => handleUpdate(item.id, v)}
                                    disabled={!canEdit(item)}
                                />
                            ) : (
                                <textarea
                                    className="w-full px-3 py-2 bg-white border border-slate-300 rounded-lg text-sm outline-none focus:ring-2 focus:ring-blue-500 transition-all min-h-[150px] font-mono"
                                    value={item.value}
                                    onChange={(e) => handleUpdate(item.id, e.target.value)}
                                    disabled={!canEdit(item)}
                                />
                            )}
                        </div>
                    );
                })}
            </div>

            {/* CUET 2026 Section */}
            <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 space-y-6">
                <div className="flex justify-between items-center border-b border-slate-100 pb-2">
                    <h3 className="font-bold text-slate-900 flex items-center gap-2">
                        CUET 2026 Interactive Content
                    </h3>
                    {cuet2026Section.length < 4 && (
                        <Button
                            onClick={handlePrefillCUET2026}
                            disabled={saving}
                            variant="outline"
                            size="sm"
                            className="bg-purple-50 text-purple-700 border-purple-200 hover:bg-purple-100 transition-colors"
                        >
                            Prefill Missing Data
                        </Button>
                    )}
                </div>

                {cuet2026Section.length > 0 ? (
                    cuet2026Section.map(item => {
                        const EditorComponent = STRUCTURED_EDITORS[item.key];
                        return (
                            <div key={item.id} className={canEdit(item) ? "" : "opacity-50 pointer-events-none"}>
                                <div className="flex justify-between mb-2">
                                    <label className="block text-sm font-bold text-slate-800 capitalize">
                                        {item.key.replace(/_/g, ' ')}
                                    </label>
                                    {!canEdit(item) && <span className="text-xs text-slate-400">Developer Only</span>}
                                </div>
                                {EditorComponent ? (
                                    <EditorComponent
                                        value={item.value}
                                        onChange={(v: string) => handleUpdate(item.id, v)}
                                        disabled={!canEdit(item)}
                                    />
                                ) : (
                                    <textarea
                                        className="w-full px-3 py-2 bg-white border border-slate-300 rounded-lg text-sm outline-none focus:ring-2 focus:ring-blue-500 transition-all min-h-[150px] font-mono"
                                        value={item.value}
                                        onChange={(e) => handleUpdate(item.id, e.target.value)}
                                        disabled={!canEdit(item)}
                                        placeholder="Supports structured data..."
                                    />
                                )}
                            </div>
                        );
                    })
                ) : (
                    <div className="text-center p-6 text-slate-500 text-sm">
                        No content uploaded for CUET 2026 yet. Click "Prefill Missing Data" to initialize.
                    </div>
                )}
            </div>

            {/* Pricing Section */}
            {pricingSection.length > 0 && (
                <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 space-y-6">
                    <h3 className="font-bold text-slate-900 border-b border-slate-100 pb-2">Pricing Section</h3>

                    {pricingSection.map(item => (
                        <div key={item.id} className={canEdit(item) ? "" : "opacity-50 pointer-events-none"}>
                            <div className="flex justify-between">
                                <label className="block text-sm font-medium text-slate-700 mb-1 capitalize">
                                    {item.key}
                                </label>
                                {!canEdit(item) && <span className="text-xs text-slate-400">Developer Only</span>}
                            </div>
                            <Input
                                value={item.value}
                                onChange={(e) => handleUpdate(item.id, e.target.value)}
                                disabled={!canEdit(item)}
                            />
                        </div>
                    ))}
                </div>
            )}

            {content.length === 0 && (
                <div className="text-center p-12 text-slate-500">
                    {/* eslint-disable-next-line react/no-unescaped-entities */}
                    No content found in Firestore 'content' collection. run a seed script or add documents manually.
                </div>
            )}
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import { useParams, useRouter, useSearchParams } from "next/navigation";
import { Button } from "@/components/ui/Button";
import { Input } from "@/components/ui/Input";
import { ArrowLeft, Save, Plus, Trash2, Loader2, Check } from "lucide-react";
import { firestoreService } from "@/services/firestoreService";
import { Question, Passage } from "@/types/admin";
import Link from "next/link";
import { collection, getDocs } from "firebase/firestore";
import { db } from "@/lib/firebase/config";

export default function QuestionEditorPage() {
    const params = useParams();
    const router = useRouter();
    const searchParams = useSearchParams();
    const prefillTestId = searchParams.get('testId');

    const questionId = params.questionId as string; // 'new' or actual ID
    const isNew = questionId === 'new';

    const [question, setQuestion] = useState<Partial<Question>>({
        questionType: "mcq",
        text: "",
        options: ["", "", "", ""],
        correctOption: 0,
        explanation: "",
        testId: prefillTestId || "",
        matchPairs: [{ left: "", right: "" }, { left: "", right: "" }, { left: "", right: "" }, { left: "", right: "" }],
        passageId: ""
    });

    const [loading, setLoading] = useState(!isNew);
    const [saving, setSaving] = useState(false);
    const [tests, setTests] = useState<{ id: string, title: string }[]>([]);
    const [passages, setPassages] = useState<Passage[]>([]);
    const [newPassageText, setNewPassageText] = useState("");
    const [isCreatingPassage, setIsCreatingPassage] = useState(false);

    useEffect(() => {
         
        loadData();
    }, []);

    async function loadData() {
        // Load tests for dropdown
        try {
            const [t, p] = await Promise.all([
                firestoreService.getTests(),
                firestoreService.getPassages()
            ]);
            setTests(t.map(test => ({ id: test.id, title: test.title })));
            setPassages(p);
        } catch (e) {
            console.error("Failed to load tests", e);
        }

        if (!isNew) {
            // Load specific question (inefficiently from list for now)
            const qs = await firestoreService.getQuestions();
            const found = qs.find(q => q.id === questionId);
            if (found) {
                setQuestion({
                    ...found,
                    questionType: found.questionType || "mcq",
                    matchPairs: found.matchPairs || [{ left: "", right: "" }, { left: "", right: "" }, { left: "", right: "" }, { left: "", right: "" }]
                });
            } else {
                router.push("/admin/management?tab=questions");
            }
        }
        setLoading(false);
    }

    async function handleSave() {
        if (!question.text || question.options?.some(o => !o)) {
            alert("Please fill in question text and all options.");
            return;
        }

        if (question.questionType === "match") {
            if (question.matchPairs?.some(p => !p.left || !p.right)) {
                alert("Please fill in all match pairs.");
                return;
            }
        }

        setSaving(true);
        try {
            let finalPassageId = question.passageId;

            if (question.questionType === "passage" && isCreatingPassage && newPassageText.trim() !== "") {
                const newId = await firestoreService.createPassage({ text: newPassageText });
                if (newId) {
                    finalPassageId = newId;
                } else {
                    alert("Failed to create the new passage.");
                    setSaving(false);
                    return;
                }
            } else if (question.questionType === "passage" && !finalPassageId) {
                alert("Please select or create a passage for this question.");
                setSaving(false);
                return;
            }

            const questionDataToSave: any = {
                ...question,
                passageId: question.questionType === "passage" ? finalPassageId : null,
                matchPairs: question.questionType === "match" ? question.matchPairs : null
            };

            if (isNew) {
                await firestoreService.createQuestion(questionDataToSave);
            } else {
                await firestoreService.updateQuestion(questionId, questionDataToSave);
            }
            router.push("/admin/management?tab=questions");
        } catch (e) {
            console.error(e);
            alert("Failed to save the question.");
        } finally {
            setSaving(false);
        }
    }

    function handleOptionChange(index: number, value: string) {
        const newOptions = [...(question.options || [])];
        newOptions[index] = value;
        setQuestion({ ...question, options: newOptions });
    }

    if (loading) return (
        <div className="p-8 flex justify-center items-center">
            <Loader2 className="h-6 w-6 animate-spin text-blue-500 mr-2" /> Loading...
