"use client";

import { useEffect, useState } from "react";
import { Button } from "@/components/ui/Button";
import { Input } from "@/components/ui/Input";
import { Save, AlertTriangle, Shield, Globe, Mail, Clock, Loader2 } from "lucide-react";
import { firestoreService } from "@/services/firestoreService";
import { SiteSettings, AuditLog } from "@/types/admin";
import { useAuth } from "@/context/AuthContext";

export default function SettingsPage() {
    const { userData } = useAuth();
    const [settings, setSettings] = useState<SiteSettings | null>(null);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [auditLogs, setAuditLogs] = useState<AuditLog[]>([]);
    const [logsLoading, setLogsLoading] = useState(false);

    const isDeveloper = userData?.role === 'developer';

    async function loadSettings() {
        const data = await firestoreService.getSettings();
        setSettings(data);
        setLoading(false);
    }

    async function loadAuditLogs() {
        setLogsLoading(true);
        const logs = await firestoreService.getAuditLogs();
        setAuditLogs(logs);
        setLogsLoading(false);
    }

    useEffect(() => {
        // eslint-disable-next-line react-hooks/set-state-in-effect
        loadSettings();
        if (isDeveloper) {
            loadAuditLogs();
        }
    }, [isDeveloper]);

    async function handleSave() {
        if (!settings) return;
        setSaving(true);

        const success = await firestoreService.updateSettings(settings);

        setSaving(false);
        if (success) {
            alert("Settings updated successfully!");
        } else {
            alert("Failed to update settings.");
        }
    }

    if (loading || !settings) return (
        <div className="p-8 flex justify-center items-center">
            <Loader2 className="h-6 w-6 animate-spin text-blue-500 mr-2" /> Loading settings...
        </div>
    );

    return (
        <div className="space-y-6 animate-in fade-in max-w-4xl">
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-2xl font-bold text-slate-900">Settings</h1>
                    <p className="text-slate-500 mt-1">Manage global site configurations.</p>
                </div>
                {/* Only Developers can save global settings? Or Admins too? Assuming both for now unless specific requirement. */}
                <Button onClick={handleSave} disabled={saving} className="gap-2 bg-blue-600 hover:bg-blue-700 text-white">
                    <Save className="h-4 w-4" /> {saving ? "Saving..." : "Save Changes"}
                </Button>
            </div>

            <div className="grid gap-6">
                {/* General Settings */}
                <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
                    <h3 className="font-bold text-slate-900 border-b border-slate-100 pb-4 mb-4 flex items-center gap-2">
                        <Globe className="h-5 w-5 text-blue-500" />
                        General Information
                    </h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div>
                            <label className="block text-sm font-medium text-slate-700 mb-1">Site Name</label>
                            <Input
                                value={settings.siteName}
                                onChange={(e) => setSettings({ ...settings, siteName: e.target.value })}
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-slate-700 mb-1">Support Email</label>
                            <Input
                                value={settings.supportEmail}
                                onChange={(e) => setSettings({ ...settings, supportEmail: e.target.value })}
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-slate-700 mb-1">Currency</label>
                            <select
                                className="w-full px-3 py-2 bg-white border border-slate-300 rounded-lg text-sm"
                                value={settings.currency}
                                onChange={(e) => setSettings({ ...settings, currency: e.target.value })}
                            >
                                <option value="INR">INR (₹)</option>
                                <option value="USD">USD ($)</option>
                                <option value="EUR">EUR (€)</option>
                            </select>
                        </div>
                    </div>
                </div>

                {/* Security & Access */}
                <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
                    <h3 className="font-bold text-slate-900 border-b border-slate-100 pb-4 mb-4 flex items-center gap-2">
                        <Shield className="h-5 w-5 text-purple-500" />
                        Security & Access
                    </h3>

                    <div className="flex items-center justify-between p-4 bg-slate-50 rounded-lg border border-slate-200">
                        <div>
                            <h4 className="font-medium text-slate-900">Maintenance Mode</h4>
                            <p className="text-sm text-slate-500">Enable to temporarily disable public access.</p>
                        </div>
                        <label className="relative inline-flex items-center cursor-pointer">
                            <input
                                type="checkbox"
                                className="sr-only peer"
                                checked={settings.maintenanceMode}
                                onChange={(e) => setSettings({ ...settings, maintenanceMode: e.target.checked })}
                            />
                            <div className="w-11 h-6 bg-slate-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-blue-300 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-blue-600"></div>
                        </label>
                    </div>

                    {settings.maintenanceMode && (
                        <div className="mt-4 p-3 bg-yellow-50 text-yellow-800 text-sm rounded-lg flex gap-2 items-center">
                            <AlertTriangle className="h-4 w-4" />
                            Warning: Site is currently accessible only to admins.
                        </div>
                    )}
                </div>

                {/* Developer Only: Audit Logs */}
                {isDeveloper && (
                    <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
                        <h3 className="font-bold text-slate-900 border-b border-slate-100 pb-4 mb-4 flex items-center gap-2">
                            <Clock className="h-5 w-5 text-slate-500" />
                            Audit Logs (Developer Only)
                        </h3>

                        <div className="overflow-x-auto max-h-96 overflow-y-auto">
                            {logsLoading ? (
                                <div className="text-center py-8 text-slate-500">Loading logs...</div>
                            ) : auditLogs.length === 0 ? (
                                <div className="text-center py-8 text-slate-500">No logs found.</div>
                            ) : (
                                <table className="w-full text-left text-sm">
                                    <thead className="bg-slate-50 text-slate-500 font-medium sticky top-0">
                                        <tr>
                                            <th className="px-4 py-2">Action</th>
                                            <th className="px-4 py-2">User</th>
                                            <th className="px-4 py-2">Details</th>
                                            <th className="px-4 py-2 text-right">Time</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-slate-100">
                                        {auditLogs.map(log => (
                                            <tr key={log.id} className="hover:bg-slate-50">
                                                <td className="px-4 py-2 font-medium text-slate-900">{log.action}</td>
                                                <td className="px-4 py-2 text-slate-600">
                                                    <div className="flex flex-col">
                                                        <span>{log.userName}</span>
                                                        <span className="text-xs text-slate-400">{log.userId}</span>
                                                    </div>
                                                </td>
                                                <td className="px-4 py-2 text-slate-600 max-w-xs truncate" title={log.details}>
                                                    {log.details}
                                                </td>
                                                <td className="px-4 py-2 text-right text-slate-400 text-xs">
                                                    {log.timestamp}
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            )}
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import { Button } from "@/components/ui/Button";
import { ArrowLeft, Save, Loader2, Plus, Library, Upload } from "lucide-react";
import { firestoreService } from "@/services/firestoreService";
import { Test, Question, Passage } from "@/types/admin";
import Link from "next/link";
import { useAuth } from "@/context/AuthContext";
import { TestMetadata } from "@/components/admin/test-builder/TestMetadata";
import { TestQuestionList } from "@/components/admin/test-builder/TestQuestionList";
import { QuestionBankSidePanel } from "@/components/admin/test-builder/QuestionBankSidePanel";
import { CSVImportModal } from "@/components/admin/questions/CSVImportModal";

export default function TestBuilderPage() {
    const params = useParams();
    const router = useRouter();
    const { user } = useAuth();
    const testId = params.testId as string;
    const isNew = testId === 'new';

    // State
    const [test, setTest] = useState<Partial<Test>>({
        title: "",
        description: "",
        duration: 60,
        totalMarks: 200,
        difficulty: "Medium",
        category: "Subject",
        price: "free",
        status: "draft",
        questions: [],
        questionIds: [],
        streams: ["General"]
    });

    const [questions, setQuestions] = useState<Question[]>([]);
    const [passages, setPassages] = useState<Passage[]>([]);
    const [loading, setLoading] = useState(!isNew);
    const [saving, setSaving] = useState(false);
    const [isBankOpen, setIsBankOpen] = useState(false);
    const [isCSVModalOpen, setIsCSVModalOpen] = useState(false);

    useEffect(() => {
        firestoreService.getPassages().then(setPassages).catch(console.error);
        if (!isNew) {
            loadTest();
        } else {
            setLoading(false);
        }
    }, [testId, isNew]);

    async function loadTest() {
        try {
            const found = await firestoreService.getTest(testId);
            if (found) {
                setTest(found);
                // Load questions
                if (found.questionIds && found.questionIds.length > 0) {
                    // Fetch questions maintaining order is tricky with where 'in' query.
                    // We'll fetch and resort.
                    const qs = await firestoreService.getQuestions({ ids: found.questionIds });
                    // Sort qs based on questionIds order
                    const sortedQs = found.questionIds.map(id => qs.find(q => q.id === id)).filter(Boolean) as Question[];
                    setQuestions(sortedQs);
                }
            } else {
                router.push("/admin/management?tab=tests");
            }
        } catch (error) {
            console.error("Failed to load test", error);
        } finally {
            setLoading(false);
        }
    }

    const handleSave = async () => {
        setSaving(true);
        try {
            // 1. Save all questions first (Upsert)
            // We need to ensure new questions (temp IDs) get real IDs
            const finalQuestionIds: string[] = [];
            const savedQuestions: Question[] = [];

            for (const q of questions) {
                let savedQ = { ...q };
                // If it has a temp ID (starts with temp_) or is empty/null, create it as new
                if (!q.id || q.id.startsWith('temp_')) {
                    // Remove the temp ID so firestore generates one
                    const { id, ...qData } = q;
                    // eslint-disable-next-line @typescript-eslint/no-explicit-any
                    const newId = await firestoreService.createQuestion(qData as any);
                    if (newId) {
                        savedQ = { ...q, id: newId };
                    } else {
                        throw new Error("Failed to create question");
                    }
                } else {
                    // Update existing
                    await firestoreService.updateQuestion(q.id, q);
                }
                finalQuestionIds.push(savedQ.id);
                savedQuestions.push(savedQ);
            }

            // 2. Save Test with ordered IDs
            const payload = {
                ...test,
                questionIds: finalQuestionIds,
                questions: [] // Clear legacy embedded if any
            };

            if (isNew) {
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                await firestoreService.createTest(payload as any);
            } else {
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                await firestoreService.updateTest(testId, payload as any);
            }

            // Update local state with real IDs to prevent dupe creation on next save
            setQuestions(savedQuestions);

            // Redirect or Notify
            router.push("/admin/management?tab=tests");

        } catch (error) {
            console.error("Failed to save", error);
            alert("Failed to save test. Check console.");
        } finally {
            setSaving(false);
        }
    };

    const addNewQuestion = () => {
        const newQ: Question = {
            id: `temp_${Date.now()}`,
            text: "",
            options: ["", "", "", ""],
            correctOption: 0,
            difficulty: "Medium",
            stream: "General",
            subject: ""
        };
        setQuestions([...questions, newQ]);
    };

    const addQuestionsFromBank = (selected: Question[]) => {
        setQuestions(prev => [...prev, ...selected]);
    };

    const addQuestionsFromCSV = (imported: Partial<Question>[]) => {
        const prepared = imported.map((q) => ({
            ...q,
            id: `temp_${Date.now()}_${Math.random()}`, // Assign temp IDs
        })) as Question[];
        setQuestions(prev => [...prev, ...prepared]);
    };

    if (loading) return (
        <div className="flex h-screen items-center justify-center">
            <Loader2 className="h-8 w-8 animate-spin text-blue-600" />
            <span className="ml-2 text-slate-600">Loading Test Builder...</span>
        </div>
    );

    return (
        <div className="min-h-screen bg-slate-50/50 pb-20">
            {/* Top Bar */}
            <div className="sticky top-0 z-10 bg-white border-b border-slate-200 px-4 md:px-8 py-4 shadow-sm">
                <div className="max-w-5xl mx-auto flex items-center justify-between">
                    <div className="flex items-center gap-4">
                        <Link href="/admin/management?tab=tests">
                            <Button variant="outline" size="sm" className="gap-2 text-slate-600 hover:text-slate-900 hover:bg-slate-100 border-slate-300">
                                <ArrowLeft className="h-4 w-4" /> Back to Tests
                            </Button>
                        </Link>
                        <h1 className="text-xl font-bold text-slate-900 truncate max-w-[200px] md:max-w-md">
                            {test.title || "Untitled Test"}
                        </h1>
                        <span className={`px-2.5 py-0.5 rounded-full text-xs font-medium ${test.status === 'published' ? 'bg-green-100 text-green-700' : 'bg-slate-100 text-slate-600'
                            }`}>
                            {test.status === 'published' ? 'Published' : 'Draft'}
                        </span>
                    </div>
                    <div className="flex gap-2">
                        <div className="flex items-center gap-2">
                            <span className="text-sm font-medium text-slate-600">Status:</span>
                            <select
                                className={`px-3 py-2 rounded-md text-sm border focus:ring-2 focus:ring-blue-500 outline-none transition-colors ${test.status === 'published'
                                    ? 'bg-green-50 text-green-700 border-green-200'
                                    : 'bg-slate-50 text-slate-600 border-slate-200'
                                    }`}
                                value={test.status as any}
                                onChange={(e) => setTest({ ...test, status: e.target.value as 'draft' | 'published' })}
                            >
                                <option value="draft">Draft</option>
                                <option value="published">Published</option>
                            </select>
                        </div>
                        {/* <Button variant="outline" className="gap-2 hidden sm:flex">
                            <Eye className="h-4 w-4" /> Preview
                        </Button> */}
                        <Button onClick={handleSave} disabled={saving} className="gap-2 bg-blue-600 hover:bg-blue-700 text-white shadow-sm">
                            <Save className="h-4 w-4" /> {saving ? "Saving..." : "Save Test"}
                        </Button>
                    </div>
                </div>
            </div>

            <div className="max-w-5xl mx-auto px-4 md:px-8 py-8 space-y-8">
                {/* 1. Metadata Section */}
                <section>
                    <TestMetadata test={test} onChange={setTest} />
                </section>

                {/* 2. Questions Builder Section */}
                <section className="space-y-4">
                    <div className="flex items-center justify-between">
                        <h2 className="text-xl font-semibold text-slate-800">Questions ({questions.length})</h2>
                        <div className="flex gap-2">
                            <Button
                                variant="outline"
                                onClick={() => setIsCSVModalOpen(true)}
                                className="gap-2 bg-white"
                            >
                                <Upload className="h-4 w-4 text-blue-600" />
                                Import CSV
                            </Button>
                            <Button
                                variant="outline"
                                onClick={() => setIsBankOpen(true)}
                                className="gap-2 bg-white"
                            >
                                <Library className="h-4 w-4 text-blue-600" />
                                Add from Bank
                            </Button>
                        </div>
                    </div>

                    <TestQuestionList
                        questions={questions}
                        setQuestions={setQuestions}
                        passages={passages}
                    />

                    {/* Floating Add Button logic or bottom block */}
                    <div
                        onClick={addNewQuestion}
                        className="group flex flex-col items-center justify-center p-8 border-2 border-dashed border-slate-300 rounded-xl cursor-pointer hover:border-blue-500 hover:bg-blue-50/30 transition-all"
                    >
                        <div className="h-10 w-10 rounded-full bg-blue-100 flex items-center justify-center group-hover:bg-blue-600 transition-colors">
                            <Plus className="h-6 w-6 text-blue-600 group-hover:text-white" />
                        </div>
                        <p className="mt-2 text-sm font-medium text-slate-600 group-hover:text-blue-700">Add New Question</p>
                    </div>
                </section>
            </div>

            <QuestionBankSidePanel
                open={isBankOpen}
                onClose={() => setIsBankOpen(false)}
                onAddQuestions={addQuestionsFromBank}
                existingIds={questions.map(q => q.id)}
            />

            <CSVImportModal
                isOpen={isCSVModalOpen}
                onClose={() => setIsCSVModalOpen(false)}
                onSuccess={() => setIsCSVModalOpen(false)} // Won't be called if prepopulating
                onPrepopulateFromCSV={addQuestionsFromCSV}
            />
        </div>
    );
}

