"use client";

import { useEffect, useState } from 'react';
import { useParams, useRouter } from "next/navigation";
import { useAuth } from "@/context/AuthContext";
import { firestoreService } from '@/services/firestoreService';
import { Test, Question, TestAttempt, TestResult } from "@/types/admin";
import { Button } from "@/components/ui/Button";
import Link from "next/link";
import {
  Trophy,
  Target,
  BarChart2,
  CheckCircle2,
  XCircle,
  AlertCircle,
  ArrowRight,
  ChevronDown,
  ChevronUp,
  Loader2,
  TrendingUp,
  TrendingDown,
  Minus
} from "lucide-react";

export default function AnalysisPage() {
  const params = useParams();
  const testId = params.testId as string;
  const { user, loading: authLoading } = useAuth();
  const router = useRouter();

  const [loading, setLoading] = useState(true);
  const [test, setTest] = useState<Test | null>(null);
  const [attempt, setAttempt] = useState<TestAttempt | null>(null);
  const [questions, setQuestions] = useState<Question[]>([]);
  const [result, setResult] = useState<Partial<TestResult> | null>(null);

  // UI State
  const [expandedQuestion, setExpandedQuestion] = useState<string | null>(null);

  useEffect(() => {
    if (!authLoading && !user) {
      router.push(`/auth/login?redirect=/analysis/${testId}`);
      return;
    }

    async function fetchData() {
      if (!user || !testId) return;

      try {
        // Parallel fetch
        const [fetchedTest, fetchedQuestions, fetchedAttempt] = await Promise.all([
          firestoreService.getTest(testId),
          firestoreService.getQuestions({ testId }),
          firestoreService.getLastTestAttempt(user.uid, testId)
        ]);

        setTest(fetchedTest);
        setQuestions(fetchedQuestions);
        setAttempt(fetchedAttempt);

        if (fetchedAttempt && fetchedAttempt.resultData) {
          setResult(fetchedAttempt.resultData);
        } else if (fetchedAttempt) {
          // Fallback calculation if resultData is missing (shouldn't happen with new logic)
          // But useful for older attempts or robustness
          let score = 0;
          let correct = 0;
          let incorrect = 0;
          let unanswered = 0;

          fetchedQuestions.forEach(q => {
            const ans = fetchedAttempt.answers[q.id];
            if (ans === undefined) unanswered++;
            else if (ans === q.correctOption) {
              score += 5;
              correct++;
            } else {
              score -= 1;
              incorrect++;
            }
          });

          setResult({
            score,
            correctAnswers: correct,
            incorrectAnswers: incorrect,
            unanswered,
            accuracy: correct / (correct + incorrect) * 100 || 0,
            timeTaken: (fetchedTest?.duration || 0) * 60 - fetchedAttempt.timeRemaining
          });
        }

      } catch (error) {
        console.error("Error loading analysis:", error);
      } finally {
        setLoading(false);
      }
    }

    if (user) fetchData();
  }, [user, testId, authLoading, router]);

  if (loading || authLoading) {
    return (
      <div className="h-screen flex flex-col items-center justify-center bg-slate-50">
        <Loader2 className="h-10 w-10 animate-spin text-blue-600 mb-4" />
        <p className="text-slate-500 font-medium">Analyzing Performance...</p>
      </div>
    );
  }

  if (!attempt || !test) {
    return (
      <div className="h-screen flex flex-col items-center justify-center bg-slate-50 p-4 text-center">
        <AlertCircle className="h-12 w-12 text-slate-400 mb-4" />
        <h2 className="text-xl font-bold text-slate-900 mb-2">No Result Found</h2>
        <p className="text-slate-500 mb-6">We couldn&apos;t find a completed attempt for this test.</p>
        <Link href="/dashboard">
          <Button>Return to Dashboard</Button>
        </Link>
      </div>
    );
  }

  // derived for display
  const accuracy = result?.accuracy ? Math.round(result.accuracy * 100) / 100 : 0;
  const timeDisplay = result?.timeTaken
    ? `${Math.floor(result.timeTaken / 60)}m ${result.timeTaken % 60}s`
    : "N/A";

  // Insights Logic
  const weakAreas = [];
  if (accuracy < 50) weakAreas.push("Overall Accuracy is low. Focus on core concepts.");
  if (result?.incorrectAnswers && result.incorrectAnswers > (result.correctAnswers || 0)) weakAreas.push("High negative marking impact. Avoid guessing.");

  return (
    <div className="min-h-screen bg-slate-50 py-8">
      <div className="container max-w-5xl mx-auto px-4">

        {/* Header */}
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
          <div>
            <h1 className="text-2xl font-bold text-slate-900">Test Analysis</h1>
            <p className="text-slate-500">{test.title} • Attempted on {new Date(attempt.startTime).toLocaleDateString()}</p>
          </div>
          <div className="flex gap-3">
            <Link href="/dashboard">
              <Button variant="outline">Back to Dashboard</Button>
            </Link>
            <Button
              onClick={() => {
                // Clear local session to allow new attempt
                localStorage.removeItem(`test_session_${testId}_${user!.uid}`);
                router.push(`/test/${testId}`);
              }}
              className="bg-blue-600 hover:bg-blue-700"
            >
              Re-attempt Test
            </Button>
          </div>
        </div>

        {/* Score Card */}
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 mb-8 relative overflow-hidden">
          <div className="absolute top-0 right-0 p-4 opacity-5 pointer-events-none">
            <Trophy className="h-40 w-40 text-yellow-500" />
          </div>

          <div className="grid grid-cols-2 lg:grid-cols-4 gap-8 relative z-10">
            {/* Total Score */}
            <div>
              <p className="text-sm font-medium text-slate-500 mb-1">Total Score</p>
              <div className="text-3xl font-bold text-slate-900 flex items-end gap-2">
                {result?.score} <span className="text-lg text-slate-400 font-medium">/ {test.totalMarks}</span>
              </div>
              {result?.improvement && (
                <div className={`text-xs font-medium mt-1 flex items-center gap-1 ${result.improvement.scoreDiff > 0 ? 'text-green-600' : result.improvement.scoreDiff < 0 ? 'text-red-600' : 'text-slate-400'}`}>
                  {result.improvement.scoreDiff > 0 ? <TrendingUp className="h-3 w-3" /> : result.improvement.scoreDiff < 0 ? <TrendingDown className="h-3 w-3" /> : <Minus className="h-3 w-3" />}
                  {result.improvement.scoreDiff > 0 ? '+' : ''}{result.improvement.scoreDiff} vs last attempt
                </div>
              )}
            </div>

            {/* Rank */}
            <div>
              <p className="text-sm font-medium text-slate-500 mb-1">Rank</p>
              <div className="text-3xl font-bold text-slate-900">--</div>
              <div className="text-sm text-slate-400 font-medium">Coming Soon</div>
            </div>

            {/* Time Taken */}
            <div>
              <p className="text-sm font-medium text-slate-500 mb-1">Time Taken</p>
              <div className="text-3xl font-bold text-indigo-600">{timeDisplay}</div>
              {result?.improvement && (
                <div className={`text-xs font-medium mt-1 flex items-center gap-1 ${result.improvement.timeDiff > 0 ? 'text-green-600' : result.improvement.timeDiff < 0 ? 'text-red-600' : 'text-slate-400'}`}>
                  {result.improvement.timeDiff > 0 ? <TrendingUp className="h-3 w-3" /> : result.improvement.timeDiff < 0 ? <TrendingDown className="h-3 w-3" /> : <Minus className="h-3 w-3" />}
                  {result.improvement.timeDiff > 0 ? 'Faster' : 'Slower'} by {Math.abs(Math.round(result.improvement.timeDiff / 60))}m
                </div>
              )}
            </div>

            {/* Accuracy */}
            <div>
              <p className="text-sm font-medium text-slate-500 mb-1">Accuracy</p>
              <div className={`text-3xl font-bold ${accuracy >= 80 ? 'text-green-600' : accuracy >= 50 ? 'text-yellow-600' : 'text-red-600'}`}>
                {accuracy}%
              </div>
              {result?.improvement && (
                <div className={`text-xs font-medium mt-1 flex items-center gap-1 ${result.improvement.accuracyDiff > 0 ? 'text-green-600' : result.improvement.accuracyDiff < 0 ? 'text-red-600' : 'text-slate-400'}`}>
                  {result.improvement.accuracyDiff > 0 ? <TrendingUp className="h-3 w-3" /> : result.improvement.accuracyDiff < 0 ? <TrendingDown className="h-3 w-3" /> : <Minus className="h-3 w-3" />}
                  {result.improvement.accuracyDiff > 0 ? '+' : ''}{Math.round(result.improvement.accuracyDiff * 100)}% vs last attempt
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Detailed Stats Grid */}
        <div className="grid md:grid-cols-3 gap-6 mb-8">
          {/* Question Breakdown */}
          <div className="bg-white p-6 rounded-xl border border-slate-200">
            <h3 className="font-semibold text-slate-900 mb-4 flex items-center gap-2">
              <Target className="h-5 w-5 text-blue-500" /> Question Breakdown
            </h3>
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2 text-slate-600">
                  <CheckCircle2 className="h-4 w-4 text-green-500" /> Correct
                </div>
                <span className="font-bold text-slate-900">{result?.correctAnswers}</span>
              </div>
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2 text-slate-600">
                  <XCircle className="h-4 w-4 text-red-500" /> Incorrect
                </div>
                <span className="font-bold text-slate-900">{result?.incorrectAnswers}</span>
              </div>
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2 text-slate-600">
                  <AlertCircle className="h-4 w-4 text-slate-400" /> Skipped
                </div>
                <span className="font-bold text-slate-900">{result?.unanswered}</span>
              </div>
            </div>
          </div>

          {/* Improvement Areas */}
          <div className="md:col-span-2 bg-white p-6 rounded-xl border border-slate-200">
            <h3 className="font-semibold text-slate-900 mb-4 flex items-center gap-2">
              <BarChart2 className="h-5 w-5 text-orange-500" /> Improvement Insights
            </h3>
            <div className="space-y-3">
              {weakAreas.length > 0 ? (
                weakAreas.map((area, i) => (
                  <div key={i} className="bg-amber-50 text-amber-800 px-4 py-3 rounded-lg text-sm border border-amber-100 flex items-start gap-2">
                    <AlertCircle className="h-4 w-4 mt-0.5 shrink-0" />
                    {area}
                  </div>
                ))
              ) : (
                <div className="bg-green-50 text-green-800 px-4 py-3 rounded-lg text-sm border border-green-100 flex items-center gap-2">
                  <CheckCircle2 className="h-4 w-4" />
                  Great job! Keep practicing to maintain this performance.
                </div>
              )}
              <div className="text-xs text-slate-400 mt-4">
                * More detailed insights regarding specific topics will appear here as you take more tests.
              </div>
            </div>
          </div>
        </div>

        {/* Detailed Question Review */}
        <div className="space-y-6">
          <h2 className="text-xl font-bold text-slate-900">Detailed Question Review</h2>

          {questions.map((q, index) => {
            const userAnswerIdx = attempt.answers[q.id];
            const isSkipped = userAnswerIdx === undefined;
            const isCorrect = userAnswerIdx === q.correctOption;

            const statusColor = isSkipped
              ? "border-slate-200 bg-white"
              : isCorrect
                ? "border-green-200 bg-green-50/30"
                : "border-red-200 bg-red-50/30";

            const isExpanded = expandedQuestion === q.id;

            return (
              <div key={q.id} className={`rounded-xl border ${statusColor} overflow-hidden transition-all duration-200`}>
                <div
                  className="p-4 md:p-6 flex items-start gap-4 cursor-pointer hover:bg-slate-50/50"
                  onClick={() => setExpandedQuestion(isExpanded ? null : q.id)}
                >
                  <div className={`
                                        shrink-0 w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm
                                        ${isSkipped ? 'bg-slate-100 text-slate-500' : isCorrect ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}
                                    `}>
                    {index + 1}
                  </div>

                  <div className="flex-1">
                    <div className="flex justify-between items-start">
                      <h3 className="font-medium text-slate-900 pr-8">{q.text}</h3>
                      {isExpanded ? <ChevronUp className="h-5 w-5 text-slate-400" /> : <ChevronDown className="h-5 w-5 text-slate-400" />}
                    </div>

                    {!isExpanded && (
                      <div className="mt-2 flex items-center gap-4 text-sm">
                        <span className={`${isCorrect ? 'text-green-600' : isSkipped ? 'text-slate-500' : 'text-red-600'} font-medium`}>
                          {isSkipped ? 'Skipped' : isCorrect ? 'Correct (+5)' : 'Incorrect (-1)'}
                        </span>
                      </div>
                    )}
                  </div>
                </div>

                {isExpanded && (
                  <div className="px-4 md:px-6 pb-6 pt-0 border-t border-slate-100/50">
                    <div className="mt-4 space-y-3">
                      {q.options.map((opt, i) => {
                        const isSelected = i === userAnswerIdx;
                        const isCorrectOpt = i === q.correctOption;

                        let optClass = "border-slate-200 text-slate-700 hover:bg-slate-50";
                        if (isCorrectOpt) optClass = "border-green-500 bg-green-50 text-green-900 font-medium";
                        else if (isSelected && !isCorrectOpt) optClass = "border-red-500 bg-red-50 text-red-900";

                        return (
                          <div key={i} className={`p-3 rounded border text-sm flex items-center gap-3 ${optClass}`}>
                            <div className="w-6 h-6 rounded-full border flex items-center justify-center text-xs opacity-70">
                              {String.fromCharCode(65 + i)}
                            </div>
                            {opt}
                            {isCorrectOpt && <CheckCircle2 className="h-4 w-4 text-green-600 ml-auto" />}
                            {isSelected && !isCorrectOpt && <XCircle className="h-4 w-4 text-red-600 ml-auto" />}
                          </div>
                        );
                      })}
                    </div>

                    {q.explanation && (
                      <div className="mt-4 bg-blue-50 p-4 rounded-lg text-sm text-blue-800 border border-blue-100">
                        <span className="font-bold block mb-1">Explanation:</span>
                        {q.explanation}
                      </div>
                    )}
                  </div>
                )}
              </div>
            );
          })}
        </div>

        <div className="mt-8 text-center bg-gradient-to-r from-blue-600 to-indigo-600 rounded-xl p-8 text-white">
          <h2 className="text-2xl font-bold mb-2">Ready for the next challenge?</h2>
          <p className="text-blue-100 mb-6">
            Consistent practice is the key to success. Try another mock test now.
          </p>
          <div className="flex justify-center gap-4">
            <Link href="/dashboard/tests">
              <Button size="lg" variant="outline" className="bg-white/10 text-white hover:bg-white/20 border-white/20">
                Practice Other Tests
              </Button>
            </Link>
            <Button
              size="lg"
              className="bg-white text-blue-600 hover:bg-blue-50 border-none"
              onClick={() => {
                localStorage.removeItem(`test_session_${testId}_${user!.uid}`);
                router.push(`/test/${testId}`);
              }}
            >
              Re-attempt This Test
            </Button>
          </div>
        </div>

      </div>
    </div>
  );
}

"use client";

import Link from "next/link";
import Image from "next/image";
import { PremiumGradient } from "@/components/ui/PremiumGradient";

export default function AuthLayout({
    children,
}: {
    children: React.ReactNode;
}) {
    return (
        <div className="min-h-screen bg-transparent flex flex-col justify-center py-12 sm:px-6 lg:px-8 relative text-text-primary">
            <PremiumGradient variant="transition" className="fixed inset-0" />
            <div className="relative z-10 w-full max-w-md mx-auto">
                {children}
            </div>
        </div>
    );
}

"use client";

import { motion, AnimatePresence } from "framer-motion";
import { X, Loader2 } from "lucide-react";
import { useEffect, useState } from "react";
import { firestoreService } from "@/services/firestoreService";
import { ImportantDatesGuide } from "./ImportantDatesGuide";
import { SyllabusGuide } from "./SyllabusGuide";
import { StrategyGuide } from "./StrategyGuide";
import { CollegePreferencesGuide } from "./CollegePreferencesGuide";

interface GuideWrapperProps {
    isOpen: boolean;
    onClose: () => void;
    title: string;
    icon: React.ReactNode;
    cmsKey: string;
}

export function GuideWrapper({ isOpen, onClose, title, icon, cmsKey }: GuideWrapperProps) {
    const [data, setData] = useState<any>(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (!isOpen) return;
        async function loadContent() {
            setLoading(true);
            const cmsData = await firestoreService.getCMSContent();
            const sectionItem = cmsData.find(c => c.key === cmsKey && c.section === 'cuet2026');

            if (sectionItem) {
                try {
                    setData(JSON.parse(sectionItem.value));
                } catch {
                    setData(null);
                }
            } else {
                setData(null);
            }
            setLoading(false);
        }
        loadContent();
    }, [isOpen, cmsKey]);

    useEffect(() => {
        if (isOpen) {
            document.body.style.overflow = "hidden";
        } else {
            document.body.style.overflow = "unset";
        }
        return () => { document.body.style.overflow = "unset" };
    }, [isOpen]);

    return (
        <AnimatePresence>
            {isOpen && (
                <>
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        onClick={onClose}
                        className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50"
                    />
                    <motion.div
                        initial={{ opacity: 0, scale: 0.95, y: 20 }}
                        animate={{ opacity: 1, scale: 1, y: 0 }}
                        exit={{ opacity: 0, scale: 0.95, y: 20 }}
                        transition={{ type: "spring", bounce: 0, duration: 0.4 }}
                        className="fixed inset-x-4 top-[5%] bottom-[5%] md:inset-x-[10%] lg:inset-x-[15%] z-50 bg-[#0A0A0B] border border-white/10 rounded-3xl shadow-2xl overflow-hidden flex flex-col"
                    >
                        {/* Header */}
                        <div className="flex items-center justify-between p-6 border-b border-white/10 bg-white/5 shrink-0">
                            <div className="flex items-center gap-4">
                                <div className="p-3 bg-white/10 rounded-xl border border-white/10 shrink-0">
                                    {icon}
                                </div>
                                <div>
                                    <h2 className="text-2xl font-bold text-white tracking-tight">{title}</h2>
                                    <div className="text-sm font-medium text-white/50 tracking-wide uppercase mt-1">Interactive Guide</div>
                                </div>
                            </div>
                            <button
                                onClick={onClose}
                                className="p-3 bg-white/5 hover:bg-white/10 rounded-full text-white/70 hover:text-white transition-colors"
                            >
                                <X className="h-5 w-5" />
                            </button>
                        </div>

                        {/* Content Area */}
                        <div className="flex-1 overflow-hidden relative">
                            {loading ? (
                                <div className="absolute inset-0 flex items-center justify-center">
                                    <Loader2 className="h-8 w-8 animate-spin text-white/30" />
                                </div>
                            ) : !data ? (
                                <div className="absolute inset-0 flex items-center justify-center flex-col text-white/50">
                                    <p>No content available for this section yet.</p>
                                    <p className="text-sm mt-2">Admins can add this in the CMS.</p>
                                </div>
                            ) : (
                                <div className="h-full">
                                    {cmsKey === 'important_dates_content' && <ImportantDatesGuide data={data} />}
                                    {cmsKey === 'syllabus_content' && <SyllabusGuide data={data} />}
                                    {cmsKey === 'exam_strategy_content' && <StrategyGuide data={data} />}
                                    {cmsKey === 'college_preferences_content' && <CollegePreferencesGuide data={data} />}
                                    {/* Add other guides here later */}
                                    {cmsKey !== 'important_dates_content' &&
                                        cmsKey !== 'syllabus_content' &&
                                        cmsKey !== 'exam_strategy_content' &&
                                        cmsKey !== 'college_preferences_content' && (
                                            <div className="h-full flex items-center justify-center text-white/50">
                                                Component for {cmsKey} is under construction.
                                            </div>
                                        )}
                                </div>
                            )}
                        </div>
                    </motion.div>
                </>
            )}
        </AnimatePresence>
    );
}

"use client";

import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { ImportantDateItem } from "@/components/admin/cms/CUET2026Editors";
import { Calendar as CalendarIcon, ZoomOut, ZoomIn, Clock, ChevronRight } from "lucide-react";

export function ImportantDatesGuide({ data }: { data: ImportantDateItem[] }) {
    const [view, setView] = useState<'timeline' | 'calendar'>('timeline');

    const getTypeColor = (type: ImportantDateItem['type']) => {
        switch (type) {
            case 'exam': return 'from-rose-500/20 to-rose-500/5 text-rose-400 border-rose-500/20';
            case 'registration': return 'from-blue-500/20 to-blue-500/5 text-blue-400 border-blue-500/20';
            case 'result': return 'from-emerald-500/20 to-emerald-500/5 text-emerald-400 border-emerald-500/20';
            default: return 'from-purple-500/20 to-purple-500/5 text-purple-400 border-purple-500/20';
        }
    };

    const getTypeDotColor = (type: ImportantDateItem['type']) => {
        switch (type) {
            case 'exam': return 'bg-rose-400 shadow-[0_0_15px_rgba(251,113,133,0.5)]';
            case 'registration': return 'bg-blue-400 shadow-[0_0_15px_rgba(96,165,250,0.5)]';
            case 'result': return 'bg-emerald-400 shadow-[0_0_15px_rgba(52,211,153,0.5)]';
            default: return 'bg-purple-400 shadow-[0_0_15px_rgba(192,132,252,0.5)]';
        }
    };

    return (
        <div className="h-full flex flex-col items-center justify-center p-8 bg-[#0A0A0B] relative overflow-hidden">
            {/* Controls */}
            <div className="absolute top-6 right-6 z-20 flex bg-white/5 backdrop-blur-md rounded-full border border-white/10 p-1">
                <button
                    onClick={() => setView('timeline')}
                    className={`px-4 py-2 rounded-full text-sm font-medium transition-all flex items-center gap-2 ${view === 'timeline' ? 'bg-white/10 text-white shadow-lg' : 'text-white/40 hover:text-white/70'
                        }`}
                >
                    <ZoomIn className="h-4 w-4" /> Timeline
                </button>
                <button
                    onClick={() => setView('calendar')}
                    className={`px-4 py-2 rounded-full text-sm font-medium transition-all flex items-center gap-2 ${view === 'calendar' ? 'bg-white/10 text-white shadow-lg' : 'text-white/40 hover:text-white/70'
                        }`}
                >
                    <ZoomOut className="h-4 w-4" /> Calendar
                </button>
            </div>

            {/* Views */}
            <div className="w-full h-full relative perspective-1000">
                <AnimatePresence mode="wait">
                    {view === 'timeline' ? (
                        <motion.div
                            key="timeline"
                            initial={{ opacity: 0, scale: 1.1, filter: 'blur(10px)' }}
                            animate={{ opacity: 1, scale: 1, filter: 'blur(0px)' }}
                            exit={{ opacity: 0, scale: 0.9, filter: 'blur(10px)' }}
                            transition={{ duration: 0.6, ease: [0.16, 1, 0.3, 1] }}
                            className="absolute inset-0 flex items-center overflow-x-auto snap-x snap-mandatory pt-20 pb-10 hide-scrollbar"
                        >
                            <div className="flex gap-20 px-[20vw] min-w-max items-center h-full relative">
                                {/* The continuous line */}
                                <div className="absolute top-1/2 left-0 right-0 h-0.5 bg-gradient-to-r from-transparent via-white/10 to-transparent -translate-y-1/2" />

                                {data.map((item, idx) => (
                                    <motion.div
                                        key={item.id}
                                        initial={{ opacity: 0, y: 20 }}
                                        animate={{ opacity: 1, y: 0 }}
                                        transition={{ delay: idx * 0.1, duration: 0.5 }}
                                        className={`shrink-0 w-80 snap-center relative flex flex-col ${idx % 2 === 0 ? 'justify-end pb-16' : 'justify-start pt-16 mt-32'}`}
                                    >
                                        {/* Connection Line */}
                                        <div className={`absolute left-1/2 -translate-x-1/2 w-px bg-white/20 ${idx % 2 === 0 ? 'bottom-0 top-[calc(100%-4rem)]' : 'top-0 bottom-[calc(100%-4rem)]'}`} />

                                        {/* Point on the number line */}
                                        <div className={`absolute left-1/2 -translate-x-1/2 w-4 h-4 rounded-full border-2 border-[#0A0A0B] z-10 ${getTypeDotColor(item.type)} ${idx % 2 === 0 ? 'bottom-[-0.5rem]' : 'top-[-0.5rem]'}`} />

                                        {/* Card */}
                                        <div className={`bg-gradient-to-b ${getTypeColor(item.type)} backdrop-blur-xl border rounded-[2rem] p-6 shadow-2xl hover:scale-105 transition-transform duration-300 cursor-pointer`}>
                                            <div className="text-white/40 text-xs font-bold uppercase tracking-wider mb-2 flex items-center gap-2">
                                                <Clock className="h-3 w-3" /> {item.date}
                                            </div>
                                            <h3 className="text-xl font-bold text-white mb-2">{item.title}</h3>
                                            <p className="text-white/60 text-sm leading-relaxed">{item.description}</p>
                                        </div>
                                    </motion.div>
                                ))}
                            </div>
                        </motion.div>
                    ) : (
                        <motion.div
                            key="calendar"
                            initial={{ opacity: 0, scale: 0.9, y: 50 }}
                            animate={{ opacity: 1, scale: 1, y: 0 }}
                            exit={{ opacity: 0, scale: 1.1, y: -50 }}
                            transition={{ duration: 0.6, ease: [0.16, 1, 0.3, 1] }}
                            className="absolute inset-0 overflow-y-auto p-12 md:p-24 hide-scrollbar"
                        >
                            <div className="max-w-4xl mx-auto space-y-4">
                                {data.map((item, idx) => (
                                    <motion.div
                                        key={item.id}
                                        initial={{ opacity: 0, x: -20 }}
                                        animate={{ opacity: 1, x: 0 }}
                                        transition={{ delay: idx * 0.05 }}
                                        className={`bg-gradient-to-r ${getTypeColor(item.type)} backdrop-blur-xl border p-6 rounded-3xl flex flex-col md:flex-row md:items-center gap-6 group hover:translate-x-2 transition-transform cursor-pointer`}
                                    >
                                        <div className="shrink-0 w-32 md:border-r border-white/10 md:pr-6">
                                            <div className="text-white/80 font-bold">{item.date}</div>
                                            <div className="text-xs text-white/40 uppercase tracking-widest mt-1">{item.type}</div>
                                        </div>
                                        <div className="flex-1">
                                            <h3 className="text-lg font-bold text-white mb-1 group-hover:text-white/90 transition-colors">{item.title}</h3>
                                            <p className="text-white/50 text-sm">{item.description}</p>
                                        </div>
                                        <div className="shrink-0 hidden md:block">
                                            <ChevronRight className="h-6 w-6 text-white/20 group-hover:text-white/80 transition-colors" />
                                        </div>
                                    </motion.div>
                                ))}
                            </div>
                        </motion.div>
                    )}
                </AnimatePresence>
            </div>

            {/* Global Hide Scrollbar Styles */}
            <style jsx global>{`
                .hide-scrollbar::-webkit-scrollbar {
                    display: none;
                }
                .hide-scrollbar {
                    -ms-overflow-style: none;
                    scrollbar-width: none;
                }
            `}</style>
        </div>
    );
}

"use client";

import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { StrategyStep } from "@/components/admin/cms/CUET2026Editors";
import * as Icons from "lucide-react";
import { ChevronLeft, ChevronRight, Target } from "lucide-react";

export function StrategyGuide({ data }: { data: StrategyStep[] }) {
    const [currentIndex, setCurrentIndex] = useState(0);

    const nextStep = () => setCurrentIndex(prev => (prev + 1) % data.length);
    const prevStep = () => setCurrentIndex(prev => (prev - 1 + data.length) % data.length);

    if (!data.length) return null;

    const currentData = data[currentIndex];
    const IconComponent = (Icons as any)[currentData.icon] || Target;

    return (
        <div className="h-full flex flex-col items-center justify-center bg-[#0A0A0B] relative overflow-hidden p-6 md:p-12">
            {/* Background elements */}
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[800px] h-[800px] bg-purple-500/10 blur-[120px] rounded-full pointer-events-none" />

            {/* Stepper Dots */}
            <div className="flex items-center gap-3 mb-12 relative z-10 w-full max-w-sm justify-center">
                {data.map((_, idx) => (
                    <button
                        key={idx}
                        onClick={() => setCurrentIndex(idx)}
                        className={`h-2 rounded-full transition-all duration-500 ${idx === currentIndex ? 'w-12 bg-purple-500 shadow-[0_0_15px_rgba(168,85,247,0.5)]' : 'w-2 bg-white/20 hover:bg-white/40'
                            }`}
                        aria-label={`Go to step ${idx + 1}`}
                    />
                ))}
            </div>

            {/* Main Interactive Playbook */}
            <div className="relative w-full max-w-2xl flex items-center justify-center min-h-[400px]">
                {/* Navigation Arrows */}
                <button
                    onClick={prevStep}
                    className="absolute left-0 md:-left-16 p-3 rounded-full bg-white/5 border border-white/10 text-white/50 hover:text-white hover:bg-white/10 hover:scale-110 active:scale-95 transition-all z-20"
                >
                    <ChevronLeft className="h-6 w-6" />
                </button>
                <button
                    onClick={nextStep}
                    className="absolute right-0 md:-right-16 p-3 rounded-full bg-white/5 border border-white/10 text-white/50 hover:text-white hover:bg-white/10 hover:scale-110 active:scale-95 transition-all z-20"
                >
                    <ChevronRight className="h-6 w-6" />
                </button>

                {/* Content */}
                <AnimatePresence mode="wait">
                    <motion.div
                        key={currentIndex}
                        initial={{ opacity: 0, x: 50, filter: 'blur(10px)' }}
                        animate={{ opacity: 1, x: 0, filter: 'blur(0px)' }}
                        exit={{ opacity: 0, x: -50, filter: 'blur(10px)' }}
                        transition={{ duration: 0.5, ease: "easeOut" }}
                        className="w-full h-full flex flex-col items-center text-center p-8 bg-white/5 backdrop-blur-xl border border-white/10 rounded-[3rem] shadow-2xl relative"
                    >
                        <div className="absolute -top-12 w-24 h-24 bg-gradient-to-br from-purple-500 to-blue-500 rounded-3xl rotate-12 shadow-[0_0_40px_rgba(168,85,247,0.4)] flex items-center justify-center">
                            <IconComponent className="h-10 w-10 text-white -rotate-12" />
                        </div>

                        <div className="mt-12 text-purple-400 font-bold tracking-widest uppercase text-sm mb-4">
                            Step {currentIndex + 1} of {data.length}
                        </div>

                        <h2 className="text-3xl md:text-5xl font-bold text-white mb-6 leading-tight">
                            {currentData.title}
                        </h2>

                        <p className="text-lg text-white/60 leading-relaxed max-w-lg mx-auto">
                            {currentData.description}
                        </p>
                    </motion.div>
                </AnimatePresence>
            </div>
        </div>
    );
}

"use client";

import { useEffect, useState } from 'react';
import { useParams, useRouter } from "next/navigation";
import { useAuth } from "@/context/AuthContext";
import { firestoreService } from '@/services/firestoreService';
import { Test, Question, TestAttempt, TestResult } from "@/types/admin";
import { Button } from "@/components/ui/Button";
import Link from "next/link";
import {
    Trophy,
    Target,
    BarChart2,
    CheckCircle2,
    XCircle,
    AlertCircle,
    ArrowRight,
    ChevronDown,
    ChevronUp,
    Loader2,
    TrendingUp,
    TrendingDown,
    Minus
} from "lucide-react";

export default function AnalysisPage() {
    const params = useParams();
    const testId = params.testId as string;
    const { user, loading: authLoading } = useAuth();
    const router = useRouter();

    const [loading, setLoading] = useState(true);
    const [test, setTest] = useState<Test | null>(null);
    const [attempt, setAttempt] = useState<TestAttempt | null>(null);
    const [questions, setQuestions] = useState<Question[]>([]);
    const [result, setResult] = useState<Partial<TestResult> | null>(null);

    // UI State
    const [expandedQuestion, setExpandedQuestion] = useState<string | null>(null);

    useEffect(() => {
        if (!authLoading && !user) {
            router.push(`/auth/login?redirect=/dashboard/analysis/${testId}`);
            return;
        }

        async function fetchData() {
            if (!user || !testId) return;

            try {
                // Parallel fetch
                const [fetchedTest, fetchedQuestions, fetchedAttempt] = await Promise.all([
                    firestoreService.getTest(testId),
                    firestoreService.getQuestions({ testId }),
                    firestoreService.getLastTestAttempt(user.uid, testId)
                ]);

                setTest(fetchedTest);
                setQuestions(fetchedQuestions);
                setAttempt(fetchedAttempt);

                if (fetchedAttempt && fetchedAttempt.resultData) {
                    setResult(fetchedAttempt.resultData);
                } else if (fetchedAttempt) {
                    // Fallback calculation
                    let score = 0;
                    let correct = 0;
                    let incorrect = 0;
                    let unanswered = 0;

                    fetchedQuestions.forEach(q => {
                        const ans = fetchedAttempt.answers[q.id];
                        if (ans === undefined) unanswered++;
                        else if (ans === q.correctOption) {
                            score += 5;
                            correct++;
                        } else {
                            score -= 1;
                            incorrect++;
                        }
                    });

                    setResult({
                        score,
                        correctAnswers: correct,
                        incorrectAnswers: incorrect,
                        unanswered,
                        accuracy: correct / (correct + incorrect) * 100 || 0,
                        timeTaken: (fetchedTest?.duration || 0) * 60 - fetchedAttempt.timeRemaining
                    });
                }

            } catch (error) {
                console.error("Error loading analysis:", error);
            } finally {
                setLoading(false);
            }
        }

        if (user) fetchData();
    }, [user, testId, authLoading, router]);

    if (loading || authLoading) {
        return (
            <div className="h-[60vh] flex flex-col items-center justify-center">
                <Loader2 className="h-10 w-10 animate-spin text-blue-600 mb-4" />
                <p className="text-slate-500 font-medium">Analyzing Performance...</p>
            </div>
        );
    }

    if (!attempt || !test) {
        return (
            <div className="h-[60vh] flex flex-col items-center justify-center text-center">
                <AlertCircle className="h-12 w-12 text-slate-400 mb-4" />
                <h2 className="text-xl font-bold text-slate-900 mb-2">No Result Found</h2>
                <p className="text-slate-500 mb-6">We couldn&apos;t find a completed attempt for this test.</p>
                <Link href="/dashboard/tests">
                    <Button>Browse Tests</Button>
                </Link>
            </div>
        );
    }

    // derived for display
    const accuracy = result?.accuracy ? Math.round(result.accuracy * 100) / 100 : 0;
    const timeDisplay = result?.timeTaken
        ? `${Math.floor(result.timeTaken / 60)}m ${result.timeTaken % 60}s`
        : "N/A";

    // Insights Logic
    const weakAreas = [];
    if (accuracy < 50) weakAreas.push("Overall Accuracy is low. Focus on core concepts.");
    if (result?.incorrectAnswers && result.incorrectAnswers > (result.correctAnswers || 0)) weakAreas.push("High negative marking impact. Avoid guessing.");

    return (
        <div className="space-y-8">
            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h1 className="text-2xl font-bold text-slate-900">Test Analysis</h1>
                    <p className="text-slate-500">{test.title} • Attempted on {new Date(attempt.startTime).toLocaleDateString()}</p>
                </div>
                <div className="flex gap-3">
                    <Link href="/dashboard/attempts">
                        <Button variant="outline">My Attempts</Button>
                    </Link>
                    <Button
                        onClick={() => {
                            localStorage.removeItem(`test_session_${testId}_${user!.uid}`);
                            router.push(`/test/${testId}`);
                        }}
                        className="bg-blue-600 hover:bg-blue-700"
                    >
                        Re-attempt Test
                    </Button>
                </div>
            </div>

            {/* Score Card */}
            <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 relative overflow-hidden">
                <div className="absolute top-0 right-0 p-4 opacity-5 pointer-events-none">
                    <Trophy className="h-40 w-40 text-yellow-500" />
                </div>

                <div className="grid grid-cols-2 lg:grid-cols-4 gap-8 relative z-10">
                    {/* Total Score */}
                    <div>
                        <p className="text-sm font-medium text-slate-500 mb-1">Total Score</p>
                        <div className="text-3xl font-bold text-slate-900 flex items-end gap-2">
                            {result?.score} <span className="text-lg text-slate-400 font-medium">/ {test.totalMarks}</span>
                        </div>
                        {result?.improvement && (
                            <div className={`text-xs font-medium mt-1 flex items-center gap-1 ${result.improvement.scoreDiff > 0 ? 'text-green-600' : result.improvement.scoreDiff < 0 ? 'text-red-600' : 'text-slate-400'}`}>
                                {result.improvement.scoreDiff > 0 ? <TrendingUp className="h-3 w-3" /> : result.improvement.scoreDiff < 0 ? <TrendingDown className="h-3 w-3" /> : <Minus className="h-3 w-3" />}
                                {result.improvement.scoreDiff > 0 ? '+' : ''}{result.improvement.scoreDiff} vs last attempt
                            </div>
                        )}
                    </div>

                    {/* Rank */}
                    <div>
                        <p className="text-sm font-medium text-slate-500 mb-1">Rank</p>
                        <div className="text-3xl font-bold text-slate-900">--</div>
                        <div className="text-sm text-slate-400 font-medium">Coming Soon</div>
                    </div>

                    {/* Time Taken */}
                    <div>
                        <p className="text-sm font-medium text-slate-500 mb-1">Time Taken</p>
                        <div className="text-3xl font-bold text-indigo-600">{timeDisplay}</div>
                        {result?.improvement && (
                            <div className={`text-xs font-medium mt-1 flex items-center gap-1 ${result.improvement.timeDiff > 0 ? 'text-green-600' : result.improvement.timeDiff < 0 ? 'text-red-600' : 'text-slate-400'}`}>
                                {/* Logic inverted for time: less is better if score maintained, but context varies. Assuming faster is "green" if accurate? Actually, let's keep it simple. */}
                                {Math.abs(Math.round(result.improvement.timeDiff / 60))}m diff
                            </div>
                        )}
                    </div>

                    {/* Accuracy */}
                    <div>
                        <p className="text-sm font-medium text-slate-500 mb-1">Accuracy</p>
                        <div className={`text-3xl font-bold ${accuracy >= 80 ? 'text-green-600' : accuracy >= 50 ? 'text-yellow-600' : 'text-red-600'}`}>
                            {accuracy}%
                        </div>
                        {result?.improvement && (
                            <div className={`text-xs font-medium mt-1 flex items-center gap-1 ${result.improvement.accuracyDiff > 0 ? 'text-green-600' : result.improvement.accuracyDiff < 0 ? 'text-red-600' : 'text-slate-400'}`}>
                                {Math.round(result.improvement.accuracyDiff)}% diff
                            </div>
                        )}
                    </div>
                </div>
            </div>

            {/* Detailed Stats Grid */}
            <div className="grid md:grid-cols-3 gap-6">
                {/* Question Breakdown */}
                <div className="bg-white p-6 rounded-xl border border-slate-200">
                    <h3 className="font-semibold text-slate-900 mb-4 flex items-center gap-2">
                        <Target className="h-5 w-5 text-blue-500" /> Question Breakdown
                    </h3>
                    <div className="space-y-4">
                        <div className="flex items-center justify-between">
                            <div className="flex items-center gap-2 text-slate-600">
                                <CheckCircle2 className="h-4 w-4 text-green-500" /> Correct
                            </div>
                            <span className="font-bold text-slate-900">{result?.correctAnswers}</span>
                        </div>
                        <div className="flex items-center justify-between">
                            <div className="flex items-center gap-2 text-slate-600">
                                <XCircle className="h-4 w-4 text-red-500" /> Incorrect
                            </div>
                            <span className="font-bold text-slate-900">{result?.incorrectAnswers}</span>
                        </div>
                        <div className="flex items-center justify-between">
                            <div className="flex items-center gap-2 text-slate-600">
                                <AlertCircle className="h-4 w-4 text-slate-400" /> Skipped
                            </div>
                            <span className="font-bold text-slate-900">{result?.unanswered}</span>
                        </div>
                    </div>
                </div>

                {/* Improvement Areas */}
                <div className="md:col-span-2 bg-white p-6 rounded-xl border border-slate-200">
                    <h3 className="font-semibold text-slate-900 mb-4 flex items-center gap-2">
                        <BarChart2 className="h-5 w-5 text-orange-500" /> Improvement Insights
                    </h3>
                    <div className="space-y-3">
                        {weakAreas.length > 0 ? (
                            weakAreas.map((area, i) => (
                                <div key={i} className="bg-amber-50 text-amber-800 px-4 py-3 rounded-lg text-sm border border-amber-100 flex items-start gap-2">
                                    <AlertCircle className="h-4 w-4 mt-0.5 shrink-0" />
                                    {area}
                                </div>
                            ))
                        ) : (
                            <div className="bg-green-50 text-green-800 px-4 py-3 rounded-lg text-sm border border-green-100 flex items-center gap-2">
                                <CheckCircle2 className="h-4 w-4" />
                                Great job! Keep practicing to maintain this performance.
                            </div>
                        )}
                    </div>
                </div>
            </div>

            {/* Detailed Question Review */}
            <div className="space-y-6">
                <h2 className="text-xl font-bold text-slate-900">Detailed Question Review</h2>

                {questions.map((q, index) => {
                    const userAnswerIdx = attempt.answers[q.id];
                    const isSkipped = userAnswerIdx === undefined;
                    const isCorrect = userAnswerIdx === q.correctOption;

                    const statusColor = isSkipped
                        ? "border-slate-200 bg-white"
                        : isCorrect
                            ? "border-green-200 bg-green-50/30"
                            : "border-red-200 bg-red-50/30";

                    const isExpanded = expandedQuestion === q.id;

                    return (
                        <div key={q.id} className={`rounded-xl border ${statusColor} overflow-hidden transition-all duration-200`}>
                            <div
                                className="p-4 md:p-6 flex items-start gap-4 cursor-pointer hover:bg-slate-50/50"
                                onClick={() => setExpandedQuestion(isExpanded ? null : q.id)}
                            >
                                <div className={`
                                        shrink-0 w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm
                                        ${isSkipped ? 'bg-slate-100 text-slate-500' : isCorrect ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}
                                    `}>
                                    {index + 1}
                                </div>

                                <div className="flex-1">
                                    <div className="flex justify-between items-start">
                                        <h3 className="font-medium text-slate-900 pr-8">{q.text}</h3>
                                        {isExpanded ? <ChevronUp className="h-5 w-5 text-slate-400" /> : <ChevronDown className="h-5 w-5 text-slate-400" />}
                                    </div>

                                    {!isExpanded && (
                                        <div className="mt-2 flex items-center gap-4 text-sm">
                                            <span className={`${isCorrect ? 'text-green-600' : isSkipped ? 'text-slate-500' : 'text-red-600'} font-medium`}>
                                                {isSkipped ? 'Skipped' : isCorrect ? 'Correct (+5)' : 'Incorrect (-1)'}
                                            </span>
                                        </div>
                                    )}
                                </div>
                            </div>

                            {isExpanded && (
                                <div className="px-4 md:px-6 pb-6 pt-0 border-t border-slate-100/50">
                                    <div className="mt-4 space-y-3">
                                        {q.options.map((opt, i) => {
                                            const isSelected = i === userAnswerIdx;
                                            const isCorrectOpt = i === q.correctOption;

                                            let optClass = "border-slate-200 text-slate-700 hover:bg-slate-50";
                                            if (isCorrectOpt) optClass = "border-green-500 bg-green-50 text-green-900 font-medium";
                                            else if (isSelected && !isCorrectOpt) optClass = "border-red-500 bg-red-50 text-red-900";

                                            return (
                                                <div key={i} className={`p-3 rounded border text-sm flex items-center gap-3 ${optClass}`}>
                                                    <div className="w-6 h-6 rounded-full border flex items-center justify-center text-xs opacity-70">
                                                        {String.fromCharCode(65 + i)}
                                                    </div>
                                                    {opt}
                                                    {isCorrectOpt && <CheckCircle2 className="h-4 w-4 text-green-600 ml-auto" />}
                                                    {isSelected && !isCorrectOpt && <XCircle className="h-4 w-4 text-red-600 ml-auto" />}
                                                </div>
                                            );
                                        })}
                                    </div>

                                    {q.explanation && (
                                        <div className="mt-4 bg-blue-50 p-4 rounded-lg text-sm text-blue-800 border border-blue-100">
                                            <span className="font-bold block mb-1">Explanation:</span>
                                            {q.explanation}
                                        </div>
                                    )}
                                </div>
                            )}
                        </div>
                    );
                })}
            </div>
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import { firestoreService } from "@/services/firestoreService";
import { TestAttempt } from "@/types/admin";
import { useAuth } from "@/context/AuthContext";
import { StatCard } from "@/components/dashboard/StatCard";
import { Target, Clock, Trophy, TrendingUp, AlertTriangle, X, MessageSquare, Bot } from "lucide-react";

type MetricType = 'tests' | 'score' | 'accuracy' | 'time' | null;

export default function AnalyticsPage() {
    const { user } = useAuth();
    const [attempts, setAttempts] = useState<TestAttempt[]>([]);
    const [loading, setLoading] = useState(true);
    const [selectedMetric, setSelectedMetric] = useState<MetricType>(null);

    useEffect(() => {
        async function loadData() {
            if (!user) return;
            try {
                // Fetch only completed for analytics
                const completedAttempts = await firestoreService.getUserAttempts(user.uid, 'completed');
                // Sort by date ascending for chart
                completedAttempts.sort((a, b) => new Date(a.startTime).getTime() - new Date(b.startTime).getTime());
                setAttempts(completedAttempts);
            } catch (error) {
                console.error("Error loading analytics:", error);
            } finally {
                setLoading(false);
            }
        }
        loadData();
    }, [user]);

    // Compute Stats
    const totalTests = attempts.length;
    let totalScore = 0;
    let totalAccuracy = 0;
    let totalTime = 0; // minutes
    let maxScore = 0;

    const chartData = attempts.map((att, index) => {
        const score = att.resultData?.score || 0;
        const accuracy = att.resultData?.accuracy || 0;
        const time = (att.resultData?.timeTaken || 0) / 60;

        totalScore += score;
        totalAccuracy += accuracy;
        totalTime += time;
        if (score > maxScore) maxScore = score;

        return {
            index: index + 1,
            score,
            accuracy,
            time,
            date: new Date(att.startTime).toLocaleDateString()
        };
    });

    const avgScore = totalTests > 0 ? Math.round(totalScore / totalTests) : 0;
    const avgAccuracy = totalTests > 0 ? Math.round(totalAccuracy / totalTests) : 0;
    const totalTimeHours = (totalTime / 60).toFixed(1);

    // AI Insight Generator
    const getInsight = (metric: MetricType) => {
        if (attempts.length < 2) return "Keep taking tests to unlock detailed trend analysis!";

        const last = chartData[chartData.length - 1];
        const prev = chartData[chartData.length - 2];

        switch (metric) {
            case 'score':
                return last.score > prev.score
                    ? `Great job! Your score improved by ${last.score - prev.score} points in the last test. You're on an upward trend!`
                    : `Your score dipped slightly by ${prev.score - last.score} points. Review your incorrect answers to bounce back.`;
            case 'accuracy':
                return last.accuracy > 80
                    ? "Your accuracy is excellent! You're minimizing improved negative marking effectively."
                    : "Focus on accuracy. Try to skip questions you're unsure about to avoid negative marking.";
            case 'time':
                return "You're managing time well. Try to maintain this pace while improving accuracy.";
            case 'tests':
                return "Consistency is key! Try to take at least one mock test every 3 days to stay sharp.";
            default:
                return "Select a metric to see detailed insights.";
        }
    };

    // SVG Chart Logic
    const Chart = ({ dataKey = 'score', color = '#3b82f6' }: { dataKey?: 'score' | 'accuracy' | 'time', color?: string }) => {
        if (chartData.length < 2) return <div className="h-64 flex items-center justify-center text-slate-400">Not enough data for chart</div>;

        const width = 100; // viewBox units
        const height = 50;
        const maxVal = Math.max(...chartData.map(d => d[dataKey] as number), 10) * 1.1;

        const points = chartData.map((d, i) => {
            const x = (i / (chartData.length - 1)) * width;
            const y = height - ((d[dataKey] as number) / maxVal) * height;
            return `${x},${y}`;
        }).join(" ");

        return (
            <div className="w-full aspect-[2/1] bg-white rounded-lg p-4">
                <svg viewBox={`0 0 ${width} ${height}`} className="w-full h-full overflow-visible">
                    {/* Grid lines */}
                    <line x1="0" y1="0" x2={width} y2="0" stroke="#f1f5f9" strokeWidth="0.5" />
                    <line x1="0" y1={height / 2} x2={width} y2={height / 2} stroke="#f1f5f9" strokeWidth="0.5" />
                    <line x1="0" y1={height} x2={width} y2={height} stroke="#f1f5f9" strokeWidth="0.5" />

                    {/* Line */}
                    <polyline fill="none" stroke={color} strokeWidth="2" points={points} vectorEffect="non-scaling-stroke" />

                    {/* Points */}
                    {chartData.map((d, i) => {
                        const x = (i / (chartData.length - 1)) * width;
                        const y = height - ((d[dataKey] as number) / maxVal) * height;
                        return (
                            <circle key={i} cx={x} cy={y} r="2" fill="white" stroke={color} strokeWidth="1" className="hover:r-4 transition-all" vectorEffect="non-scaling-stroke">
                                <title>{`Test ${i + 1}: ${d[dataKey]}`}</title>
                            </circle>
                        );
                    })}
                </svg>
                <div className="flex justify-between text-xs text-slate-400 mt-2">
                    <span>{chartData[0]?.date}</span>
                    <span>{chartData[chartData.length - 1]?.date}</span>
                </div>
            </div>
        );
    };

    if (loading) return <div className="p-8 text-center text-slate-500">Loading analytics...</div>;

    return (
        <div className="space-y-8 relative">
            <h1 className="text-2xl font-bold text-slate-900">Performance Analytics</h1>

            {/* KPI Cards */}
            <div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-6">
                <StatCard
                    title="Tests Taken"
                    value={totalTests.toString()}
                    icon={Target}
                    trend="Total"
                    trendUp={true}
                    onClick={() => setSelectedMetric('tests')}
                />
                <StatCard
                    title="Avg. Score"
                    value={avgScore.toString()}
                    icon={TrendingUp}
                    trend="Marks"
                    trendUp={true}
                    onClick={() => setSelectedMetric('score')}
                />
                <StatCard
                    title="Avg. Accuracy"
                    value={avgAccuracy + "%"}
                    icon={AlertTriangle}
                    trend={avgAccuracy < 60 ? "Improvement Needed" : "Good"}
                    trendUp={avgAccuracy >= 60}
                    onClick={() => setSelectedMetric('accuracy')}
                />
                <StatCard
                    title="Hours Practiced"
                    value={totalTimeHours + "h"}
                    icon={Clock}
                    trend="Time"
                    trendUp={true}
                    onClick={() => setSelectedMetric('time')}
                />
            </div>

            <div className="grid lg:grid-cols-3 gap-8">
                {/* Main Chart */}
                <div className="lg:col-span-2 bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                    <h3 className="font-semibold text-slate-900 mb-6">Score Progression</h3>
                    <Chart dataKey="score" color="#3b82f6" />
                </div>

                {/* Insights / Weakness */}
                <div className="space-y-6">
                    <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                        <h3 className="font-semibold text-slate-900 mb-4">Subject Performance</h3>
                        <div className="space-y-4">
                            <div>
                                <div className="flex justify-between text-sm mb-1">
                                    <span className="text-slate-600">General Test</span>
                                    <span className="font-medium text-slate-900">75%</span>
                                </div>
                                <div className="h-2 bg-slate-100 rounded-full overflow-hidden">
                                    <div className="h-full bg-blue-500 w-3/4"></div>
                                </div>
                            </div>
                            <div>
                                <div className="flex justify-between text-sm mb-1">
                                    <span className="text-slate-600">English</span>
                                    <span className="font-medium text-slate-900">82%</span>
                                </div>
                                <div className="h-2 bg-slate-100 rounded-full overflow-hidden">
                                    <div className="h-full bg-green-500 w-[82%]"></div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Metric Detail Overlay */}
            {selectedMetric && (
                <div className="fixed inset-0 bg-black/20 backdrop-blur-sm z-50 flex justify-end">
                    <div className="w-full max-w-md bg-white h-full shadow-2xl p-6 flex flex-col animate-in slide-in-from-right duration-300">
                        <div className="flex items-center justify-between mb-8">
                            <h2 className="text-xl font-bold text-slate-900 capitalize">
                                {selectedMetric === 'tests' ? 'Test History' :
                                    selectedMetric === 'score' ? 'Score Analysis' :
                                        selectedMetric === 'accuracy' ? 'Accuracy Trend' : 'Time Analysis'}
                            </h2>
                            <button
                                onClick={() => setSelectedMetric(null)}
                                className="p-2 hover:bg-slate-100 rounded-full transition-colors"
                            >
                                <X className="h-5 w-5 text-slate-500" />
                            </button>
                        </div>

                        {/* Chart in Details */}
                        <div className="mb-8 border rounded-xl p-4 bg-slate-50">
                            <Chart
                                dataKey={selectedMetric === 'tests' ? 'score' : selectedMetric}
                                color={selectedMetric === 'accuracy' ? '#10b981' : selectedMetric === 'time' ? '#f59e0b' : '#3b82f6'}
                            />
                        </div>

                        {/* Recent Values */}
                        <div className="flex-1 overflow-y-auto space-y-4 mb-6">
                            <h3 className="font-semibold text-slate-900 mb-2">Recent History</h3>
                            {chartData.slice().reverse().map((d, i) => (
                                <div key={i} className="flex justify-between items-center p-3 border-b border-slate-100">
                                    <span className="text-sm text-slate-500">{d.date}</span>
                                    <span className="font-medium text-slate-900">
                                        {selectedMetric === 'tests' ? `Test #${d.index}` :
                                            selectedMetric === 'score' ? `${d.score} Marks` :
                                                selectedMetric === 'accuracy' ? `${d.accuracy}%` :
                                                    `${d.time.toFixed(1)} mins`}
                                    </span>
                                </div>
                            ))}
                        </div>

                        {/* Chat Bot Comment */}
                        <div className="mt-auto bg-blue-50 p-4 rounded-xl border border-blue-100">
                            <div className="flex items-start gap-3">
                                <div className="w-8 h-8 rounded-full bg-blue-100 flex items-center justify-center shrink-0">
                                    <Bot className="h-5 w-5 text-blue-600" />
                                </div>
                                <div>
                                    <p className="text-xs font-bold text-blue-800 mb-1">AI Insight</p>
                                    <p className="text-sm text-blue-700 leading-relaxed">
                                        {getInsight(selectedMetric)}
                                    </p>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import { firestoreService } from "@/services/firestoreService";
import { Test, TestAttempt } from "@/types/admin";
import { useAuth } from "@/context/AuthContext";
import { Button } from "@/components/ui/Button";
import Link from "next/link";
import { FileText, ArrowRight, Clock, CheckCircle, AlertCircle } from "lucide-react";

export default function MyAttemptsPage() {
    const { user } = useAuth();
    const [attempts, setAttempts] = useState<TestAttempt[]>([]);
    const [tests, setTests] = useState<Record<string, Test>>({});
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        async function loadData() {
            if (!user) return;
            try {
                // Fetch attempts
                const userAttempts = await firestoreService.getUserAttempts(user.uid);
                setAttempts(userAttempts);

                // Fetch related test details for titles
                // Optimize: only fetch unique testIds locally or assume we have a test cache if feasible. 
                // For now, simple parallel fetch for unique IDs.
                const uniqueTestIds = Array.from(new Set(userAttempts.map(a => a.testId)));
                const testPromises = uniqueTestIds.map(id => firestoreService.getTest(id));
                const testsData = await Promise.all(testPromises);

                const testMap: Record<string, Test> = {};
                testsData.forEach(t => {
                    if (t) testMap[t.id] = t;
                });
                setTests(testMap);

            } catch (error) {
                console.error("Error loading attempts:", error);
            } finally {
                setLoading(false);
            }
        }
        loadData();
    }, [user]);

    if (loading) {
        return (
            <div className="flex items-center justify-center min-h-[400px]">
                <div className="animate-pulse text-slate-400">Loading attempts...</div>
            </div>
        );
    }

    return (
        <div className="space-y-8">
            <div>
                <h1 className="text-2xl font-bold text-slate-900">My Attempts</h1>
                <p className="text-slate-500">Track your progress and review past performance.</p>
            </div>

            <div className="bg-white rounded-xl border border-slate-200 overflow-hidden shadow-sm">
                {attempts.length > 0 ? (
                    <div className="overflow-x-auto">
                        <table className="w-full text-sm text-left">
                            <thead className="bg-slate-50 text-slate-500 font-medium border-b border-slate-200">
                                <tr>
                                    <th className="px-6 py-4">Test Name</th>
                                    <th className="px-6 py-4">Date</th>
                                    <th className="px-6 py-4">Status</th>
                                    <th className="px-6 py-4">Score</th>
                                    <th className="px-6 py-4">Accuracy</th>
                                    <th className="px-6 py-4 text-right">Action</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100">
                                {attempts.map((attempt) => {
                                    const test = tests[attempt.testId];
                                    const date = new Date(attempt.startTime).toLocaleDateString(undefined, {
                                        year: 'numeric', month: 'short', day: 'numeric',
                                        hour: '2-digit', minute: '2-digit'
                                    });

                                    return (
                                        <tr key={attempt.id} className="hover:bg-slate-50 transition-colors">
                                            <td className="px-6 py-4 font-medium text-slate-900">
                                                {test?.title || 'Unknown Test'}
                                            </td>
                                            <td className="px-6 py-4 text-slate-500">
                                                {date}
                                            </td>
                                            <td className="px-6 py-4">
                                                {attempt.status === 'completed' ? (
                                                    <span className="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-medium bg-green-50 text-green-700">
                                                        <CheckCircle className="h-3 w-3" />
                                                        Completed
                                                    </span>
                                                ) : (
                                                    <span className="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-medium bg-blue-50 text-blue-700">
                                                        <Clock className="h-3 w-3" />
                                                        In Progress
                                                    </span>
                                                )}
                                            </td>
                                            <td className="px-6 py-4 font-medium">
                                                {attempt.resultData?.score ?? '-'}
                                                <span className="text-slate-400 font-normal text-xs ml-1">
                                                    / {test?.totalMarks}
                                                </span>
                                            </td>
                                            <td className="px-6 py-4">
                                                {attempt.resultData?.accuracy ? `${attempt.resultData.accuracy}%` : '-'}
                                            </td>
                                            <td className="px-6 py-4 text-right">
                                                {attempt.status === 'completed' ? (
                                                    <Link href={`/dashboard/analysis/${attempt.testId}`}>
                                                        <Button size="sm" variant="ghost" className="text-slate-600 hover:text-primary">
                                                            Analysis <ArrowRight className="h-4 w-4 ml-1" />
                                                        </Button>
                                                    </Link>
                                                ) : (
                                                    <Link href={`/test/${attempt.testId}`}>
                                                        <Button size="sm" variant="primary" className="h-8">
                                                            Resume
                                                        </Button>
                                                    </Link>
                                                )}
                                            </td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>
                ) : (
                    <div className="text-center py-16 px-6">
                        <div className="mx-auto w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center mb-4">
                            <FileText className="h-8 w-8 text-slate-300" />
                        </div>
                        <h3 className="text-slate-900 font-medium mb-1">No attempts yet</h3>
                        <p className="text-slate-500 text-sm mb-6">Start your first mock test to see performance history.</p>
                        <Link href="/dashboard/tests">
                            <Button variant="primary">Browse Tests</Button>
                        </Link>
                    </div>
                )}
            </div>
        </div>
    );
}

