"use client";

import { useEffect, useState } from 'react';
import { StatCard } from "@/components/dashboard/StatCard";
import { Button } from "@/components/ui/Button";
import {
    Clock,
    Target,
    Trophy,
    ArrowRight,
    FileText,
    TrendingUp,
} from "lucide-react";
import Link from "next/link";
import { firestoreService } from "@/services/firestoreService";
import { Test, TestAttempt } from "@/types/admin";
import { useAuth } from "@/context/AuthContext";
import { TestCard } from "@/components/dashboard/TestCard";
import { useRouter } from "next/navigation";
import { PaymentModal } from "@/components/dashboard/PaymentModal";

interface DashboardStats {
    testsAttempted: number;
    avgAccuracy: number;
    avgSpeed: number; // minutes per question
    bestScore: number;
}

interface PerformanceInsight {
    type: 'strength' | 'weakness' | 'neutral';
    message: string;
}

export default function DashboardPage() {
    const { user, userData, loading: authLoading } = useAuth();
    const [stats, setStats] = useState<DashboardStats>({
        testsAttempted: 0,
        avgAccuracy: 0,
        avgSpeed: 0,
        bestScore: 0
    });

    const [recommendedTests, setRecommendedTests] = useState<Test[]>([]);
    const [recentAttempts, setRecentAttempts] = useState<TestAttempt[]>([]);
    const [activeAttempt, setActiveAttempt] = useState<TestAttempt | null>(null);
    const [activeAttemptTest, setActiveAttemptTest] = useState<Test | null>(null);
    const [loading, setLoading] = useState(true);
    const [insights, setInsights] = useState<PerformanceInsight[]>([]);
    const router = useRouter();
    const [selectedTestToUnlock, setSelectedTestToUnlock] = useState<Test | null>(null);

    const handleUnlock = (test: Test) => {
        setSelectedTestToUnlock(test);
    };

    const onPaymentSuccess = () => {
        setSelectedTestToUnlock(null);
        window.location.reload();
    };

    useEffect(() => {
        if (!authLoading && !user) {
            router.push('/auth/login');
        }
    }, [user, authLoading, router]);

    useEffect(() => {
        async function loadDashboardData() {
            if (authLoading || !user) return; // Wait for auth state

            try {
                setLoading(true);

                // Parallel fetching
                const [tests, attempts, active] = await Promise.all([
                    firestoreService.getTests(true),
                    firestoreService.getUserAttempts(user.uid, 'completed'),
                    firestoreService.getActiveAttempt(user.uid)
                ]);

                // 1. Process Recommended Tests (Logic: Top 3 for now)
                setRecommendedTests(tests.slice(0, 3));

                // 2. Process Active Attempt
                if (active) {
                    setActiveAttempt(active);
                    const testDetails = tests.find(t => t.id === active.testId) || await firestoreService.getTest(active.testId);
                    setActiveAttemptTest(testDetails);
                }

                // 3. Process Recent Attempts
                setRecentAttempts(attempts.slice(0, 3)); // show top 3 recent

                // 4. Compute Stats
                if (attempts.length > 0) {
                    const totalAttempts = attempts.length;
                    let totalAccuracy = 0;
                    let totalTimePerQ = 0; // seconds
                    let maxScore = 0;
                    let totalQs = 0;

                    attempts.forEach(att => {
                        const result = att.resultData;
                        if (result) {
                            totalAccuracy += result.accuracy || 0;
                            if (result.score > maxScore) maxScore = result.score;

                            // Estimate speed? Time Taken / Total Questions
                            if (result.totalQuestions > 0 && result.timeTaken) {
                                totalTimePerQ += (result.timeTaken / result.totalQuestions);
                                totalQs++;
                            }
                        }
                    });

                    const avgTimePerQuestionMin = totalQs > 0
                        ? (totalTimePerQ / totalQs) / 60
                        : 0;

                    setStats({
                        testsAttempted: totalAttempts,
                        avgAccuracy: Math.round(totalAccuracy / totalAttempts),
                        avgSpeed: Number(avgTimePerQuestionMin.toFixed(1)),
                        bestScore: maxScore
                    });

                    // 5. Generate Insights (Simple Rule-based)
                    const newInsights: PerformanceInsight[] = [];
                    const avgAcc = totalAccuracy / totalAttempts;

                    if (avgAcc >= 80) {
                        newInsights.push({ type: 'strength', message: "Great accuracy! Push for speed now." });
                    } else if (avgAcc < 60) {
                        newInsights.push({ type: 'weakness', message: "Focus on accuracy before speed." });
                    } else {
                        newInsights.push({ type: 'neutral', message: "Consistent performance. Keep practicing." });
                    }

                    setInsights(newInsights);

                } else {
                    // No attempts
                    setStats({
                        testsAttempted: 0,
                        avgAccuracy: 0,
                        avgSpeed: 0,
                        bestScore: 0
                    });
                    setInsights([{ type: 'neutral', message: "Take your first test to get insights!" }]);
                }

            } catch (error) {
                console.error("Failed to load dashboard data", error);
            } finally {
                setLoading(false);
            }
        }

        loadDashboardData();
    }, [user, authLoading]);

    const statCards = [
        { title: "Tests Attempted", value: stats.testsAttempted.toString(), icon: FileText, trend: "Total", trendUp: true },
        { title: "Avg. Accuracy", value: `${stats.avgAccuracy}%`, icon: Target, trend: "Overall", trendUp: stats.avgAccuracy > 70 },
        { title: "Avg. Speed", value: `${stats.avgSpeed} m/qn`, icon: Clock, trend: "Pace", trendUp: true },
        { title: "Best Score", value: stats.bestScore.toString(), icon: Trophy, trend: "All Time", trendUp: true },
    ];

    if (authLoading || loading) {
        return <div className="p-8 text-center text-slate-500 flex justify-center items-center py-20">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
        </div>;
    }

    if (!user) {
        return null; // Will redirect via useEffect
    }

    return (
        <div className="space-y-8 max-w-7xl mx-auto">
            <div>
                <h1 className="text-3xl font-bold text-slate-900 tracking-tight">Dashboard Overview</h1>
                {/* eslint-disable-next-line react/no-unescaped-entities */}
                <p className="text-slate-500 mt-1">Welcome back, {userData?.name || user?.displayName || 'Student'}! Here's your progress.</p>
            </div>

            <div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-6">
                {statCards.map((stat, i) => (
                    <StatCard key={i} {...stat} />
                ))}
            </div>

            <div className="grid lg:grid-cols-3 gap-8">
                <div className="lg:col-span-2 space-y-8">
                    {/* Recent Performance / Insights */}
                    {insights.length > 0 && (
                        <div className="bg-surface-elevated border border-border/50 p-5 rounded-2xl flex items-start gap-4 shadow-sm">
                            <div className="bg-surface-base border border-border/50 p-2.5 rounded-xl shadow-sm">
                                <TrendingUp className="h-5 w-5 text-cta-primary" />
                            </div>
                            <div>
                                <h3 className="font-semibold text-text-primary">Performance Insight</h3>
                                <p className="text-text-secondary text-sm mt-1 leading-relaxed">{insights[0].message}</p>
                            </div>
                        </div>
                    )}

                    {/* Recommended Tests */}
                    <div className="space-y-4">
                        <div className="flex items-center justify-between">
                            <h2 className="text-xl font-bold text-slate-900">Recommended Tests</h2>
                            <Link href="/dashboard/tests" className="text-sm text-primary font-medium hover:underline">
                                View All
                            </Link>
                        </div>

                        {recommendedTests.length > 0 ? (
                            <div className="grid sm:grid-cols-2 gap-4 mt-4">
                                {recommendedTests.map((test) => (
                                    <TestCard
                                        key={test.id}
                                        test={test}
                                        isPurchased={test.price === 'free' || !!userData?.purchasedTests?.[test.id]}
                                        onUnlock={(t) => router.push('/dashboard/tests')}
                                    />
                                ))}
                            </div>
                        ) : (
                            <div className="text-center py-12 text-text-muted bg-surface-elevated rounded-2xl border border-border/50 mt-4">
                                <p className="font-medium text-sm">No recommended tests available right now.</p>
                            </div>
                        )}
                    </div>

                    {/* Recent Attempts List */}
                    {recentAttempts.length > 0 && (
                        <div className="space-y-4">
                            <h2 className="text-xl font-bold text-text-primary">Recent History</h2>
                            <div className="space-y-3">
                                {recentAttempts.map((attempt) => (
                                    <div key={attempt.id} className="flex items-center justify-between p-4 bg-surface-card border border-border/50 rounded-2xl hover:border-text-secondary hover:shadow transition-all shadow-sm">
                                        <div className="flex items-center gap-4">
                                            <div className="h-10 w-10 bg-surface-elevated border border-border/50 rounded-xl flex items-center justify-center text-text-muted">
                                                <FileText className="h-5 w-5" />
                                            </div>
                                            <div>
                                                <div className="font-semibold text-text-primary">
                                                    {new Date(attempt.startTime).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' })}
                                                </div>
                                                <div className="text-text-secondary text-xs">
                                                    Score: <span className="font-medium text-text-primary">{attempt.resultData?.score ?? '-'}</span> • Accuracy: {attempt.resultData?.accuracy ?? 0}%
                                                </div>
                                            </div>
                                        </div>
                                        <Link href={`/dashboard/analysis/${attempt.testId}`}>
                                            <Button size="sm" variant="outline" className="h-8 text-xs">View Analysis</Button>
                                        </Link>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}
                </div>

                <div className="space-y-8">
                    {/* Continue Learning Widget */}
                    <div>
                        <h2 className="text-xl font-bold text-text-primary mb-4">Continue Learning</h2>
                        {activeAttempt ? (
                            <div className="bg-surface-elevated border border-border/50 rounded-2xl p-6 shadow-sm">
                                <div className="mb-6">
                                    <h3 className="font-semibold text-lg mb-1 text-text-primary">{activeAttemptTest?.title || 'Unknown Test'}</h3>
                                    <p className="text-text-secondary text-sm flex items-center gap-2">
                                        <Clock className="h-3.5 w-3.5" /> Resuming from Q. {activeAttempt.currentQuestionIndex + 1}
                                    </p>
                                </div>

                                <div className="space-y-2 mb-6">
                                    <div className="flex justify-between text-xs text-text-secondary font-medium">
                                        <span>Progress</span>
                                        <span>{Math.round(((activeAttempt.currentQuestionIndex + 1) / (activeAttemptTest?.questions?.length || 100)) * 100)}%</span>
                                    </div>
                                    <div className="w-full bg-border rounded-full h-1.5 overflow-hidden">
                                        <div
                                            className="bg-cta-primary h-1.5 rounded-full transition-all duration-500"
                                            style={{ width: `${((activeAttempt.currentQuestionIndex + 1) / (activeAttemptTest?.questions?.length || 100)) * 100}%` }}
                                        ></div>
                                    </div>
                                </div>

                                <Link href={`/test/${activeAttempt.testId}`}>
                                    <Button fullWidth variant="primary" className="shadow-sm">
                                        Resume Test <ArrowRight className="h-4 w-4 ml-2" />
                                    </Button>
                                </Link>
                            </div>
                        ) : (
                            <div className="bg-surface-elevated rounded-2xl p-8 border border-border/50 text-center shadow-sm">
                                <div className="mx-auto w-12 h-12 bg-surface-base border border-border/50 rounded-full flex items-center justify-center mb-4 text-text-primary shadow-sm">
                                    <Trophy className="h-5 w-5 opacity-80" />
                                </div>
                                <h3 className="font-semibold text-text-primary">All Caught Up!</h3>
                                <p className="text-text-secondary text-sm mt-1 mb-6">You have no pending tests. Why not start a new challenge?</p>
                                <Link href="/dashboard/tests">
                                    <Button size="md" variant="primary" fullWidth>Browse Tests</Button>
                                </Link>
                            </div>
                        )}
                    </div>
                </div>
            </div>
            {selectedTestToUnlock && (
                <PaymentModal
                    isOpen={!!selectedTestToUnlock}
                    onClose={() => setSelectedTestToUnlock(null)}
                    test={selectedTestToUnlock}
                    onUnlock={onPaymentSuccess}
                />
            )}
        </div>
    );
}

"use client";

import { useState } from "react";
import { useAuth } from "@/context/AuthContext";
import { Button } from "@/components/ui/Button";
import { db } from "@/lib/firebase/config";
import { doc, updateDoc } from "firebase/firestore";
import { User, Lock, Mail, Save, LogOut } from "lucide-react";

export default function SettingsPage() {
    const { userData, logout } = useAuth();
    const [name, setName] = useState(userData?.name || "");
    const [isSaving, setIsSaving] = useState(false);
    const [message, setMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);

    const handleSave = async () => {
        if (!userData || !name.trim()) return;
        setIsSaving(true);
        setMessage(null);
        try {
            await updateDoc(doc(db, "users", userData.uid), {
                name: name.trim()
            });
            setMessage({ type: 'success', text: "Profile updated successfully!" });
        } catch (error) {
            setMessage({ type: 'error', text: "Failed to update profile." });
        } finally {
            setIsSaving(false);
        }
    };

    return (
        <div className="max-w-2xl mx-auto space-y-8">
            <h1 className="text-2xl font-bold text-slate-900">Account Settings</h1>

            <div className="bg-white p-8 rounded-xl border border-slate-200 shadow-sm space-y-6">
                <div className="flex items-center gap-4 border-b border-slate-100 pb-6">
                    <div className="h-16 w-16 bg-blue-100 rounded-full flex items-center justify-center text-blue-600 text-xl font-bold">
                        {name ? name[0].toUpperCase() : "U"}
                    </div>
                    <div>
                        <h2 className="text-lg font-semibold text-slate-900">{userData?.name}</h2>
                        <p className="text-slate-500 text-sm capitalize">{userData?.role}</p>
                    </div>
                </div>

                {/* Profile Form */}
                <div className="space-y-4">
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Full Name</label>
                        <div className="relative">
                            <User className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
                            <input
                                type="text"
                                value={name}
                                onChange={(e) => setName(e.target.value)}
                                className="w-full pl-10 pr-4 py-2 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-100"
                            />
                        </div>
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Email Address</label>
                        <div className="flex gap-3">
                            <div className="relative flex-1">
                                <Mail className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
                                <input
                                    type="email"
                                    value={userData?.email}
                                    disabled
                                    className="w-full pl-10 pr-4 py-2 border border-slate-200 rounded-lg bg-slate-50 text-slate-500"
                                />
                            </div>
                            <Button variant="outline" size="sm">Change Email</Button>
                        </div>
                    </div>
                </div>

                <div className="pt-4 border-t border-slate-100 flex items-center justify-between">
                    <Button variant="primary" onClick={handleSave} disabled={isSaving} className="gap-2">
                        <Save className="h-4 w-4" />
                        {isSaving ? "Saving..." : "Save Changes"}
                    </Button>
                    {message && (
                        <span className={`text-sm ${message.type === 'success' ? 'text-green-600' : 'text-red-600'}`}>
                            {message.text}
                        </span>
                    )}
                </div>
            </div>

            <div className="bg-white p-8 rounded-xl border border-slate-200 shadow-sm space-y-6">
                <h3 className="text-lg font-semibold text-slate-900 flex items-center gap-2">
                    <Lock className="h-5 w-5 text-slate-400" /> Security
                </h3>

                <div className="flex items-center justify-between p-4 bg-slate-50 rounded-lg border border-slate-100">
                    <div>
                        <p className="font-medium text-slate-900">Password</p>
                        <p className="text-xs text-slate-500">Last changed 3 months ago</p>
                    </div>
                    <Button variant="outline" size="sm">Change Password</Button>
                </div>

                <div className="pt-4">
                    <Button
                        onClick={logout}
                        variant="outline"
                        fullWidth
                        className="text-red-600 hover:text-red-700 hover:bg-red-50 border-slate-200 text-center justify-center"
                    >
                        <LogOut className="h-4 w-4 mr-2" />
                        Sign Out
                    </Button>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import { useAuth } from "@/context/AuthContext";
import { doc, updateDoc } from "firebase/firestore";
import { db } from "@/lib/firebase/config";
import { SYLLABUS_DATA } from "@/data/syllabus";
import { ChevronDown, ChevronRight, BookOpen, GraduationCap, ArrowRight, Sparkles } from "lucide-react";
import { Button } from "@/components/ui/Button";

// --- Types ---
type StreamType = 'Science' | 'Commerce' | 'Humanities' | null;

// --- Components ---

function OnboardingModal({
    isOpen,
    onComplete
}: {
    isOpen: boolean;
    onComplete: (stream: StreamType, target: string) => void;
}) {
    const [stream, setStream] = useState<StreamType>(null);
    const [target, setTarget] = useState("University of Delhi");

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-300">
            <div className="bg-white rounded-2xl shadow-2xl max-w-lg w-full p-8 space-y-8 animate-in zoom-in-95 duration-300">
                <div className="text-center space-y-2">
                    <div className="mx-auto w-12 h-12 bg-blue-100 rounded-full flex items-center justify-center mb-4">
                        <GraduationCap className="h-6 w-6 text-blue-600" />
                    </div>
                    <h2 className="text-2xl font-bold text-slate-900">Welcome to your Prep Journey</h2>
                    <p className="text-slate-500">To personalize your guidance, tell us a bit about your goals.</p>
                </div>

                <div className="space-y-6">
                    <div className="space-y-3">
                        <label className="text-sm font-medium text-slate-700">Which stream are you from?</label>
                        <div className="grid grid-cols-3 gap-3">
                            {(['Science', 'Commerce', 'Humanities'] as const).map((s) => (
                                <button
                                    key={s}
                                    onClick={() => setStream(s)}
                                    className={`
                                        py-3 px-2 rounded-xl text-sm font-medium border-2 transition-all
                                        ${stream === s
                                            ? 'border-blue-600 bg-blue-50 text-blue-700'
                                            : 'border-slate-100 bg-white text-slate-600 hover:border-slate-200 hover:bg-slate-50'}
                                    `}
                                >
                                    {s}
                                </button>
                            ))}
                        </div>
                    </div>

                    <div className="space-y-3">
                        <label className="text-sm font-medium text-slate-700">Target University</label>
                        <input
                            type="text"
                            value={target}
                            onChange={(e) => setTarget(e.target.value)}
                            className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-100 font-medium"
                            placeholder="e.g. BHU, JNU, AMU"
                        />
                        {/* eslint-disable-next-line react/no-unescaped-entities */}
                        <p className="text-xs text-slate-400">We've set Delhi University as default as it's the most popular choice.</p>
                    </div>
