                <Button
                    fullWidth
                    size="lg"
                    disabled={!stream || !target}
                    onClick={() => onComplete(stream, target)}
                    className="bg-blue-600 hover:bg-blue-700 text-lg py-6 rounded-xl shadow-lg shadow-blue-200/50"
                >
                    Start My Journey
                </Button>
            </div>
        </div>
    );
}

