            </section>

            {/* Section 3: Stream Specific */}
            <section className="space-y-6 p-8 bg-blue-600 text-white shadow-xl shadow-blue-200/40 rounded-3xl transform transition-all hover:scale-[1.01] duration-500">
                <h2 className="text-2xl font-bold">{content.title}</h2>
                <p className="text-lg text-blue-50 leading-relaxed opacity-90">
                    {content.text}
                </p>
            </section>

            {/* Section 4: Action */}
            <section className="text-center space-y-8 pt-8">
                <p className="text-xl font-medium text-slate-900">
                    Ready to see your roadmap?
                </p>
                <Button
                    size="lg"
                    onClick={onFinish}
                    className="bg-slate-900 text-white hover:bg-slate-800 text-lg px-10 py-6 rounded-full shadow-xl shadow-slate-200 transition-all hover:scale-105 active:scale-95"
                >
                    Reveal My Syllabus <ArrowRight className="ml-2 h-5 w-5" />
                </Button>
            </section>
        </div>
    );
}

function SyllabusAccordion({ data }: { data: typeof SYLLABUS_DATA }) {
    const [openSubject, setOpenSubject] = useState<string | null>(null);

    return (
        <div className="space-y-8 max-w-4xl mx-auto animate-in slide-in-from-bottom-8 duration-700">
            {data.map((section, idx) => (
                <div key={idx} className="space-y-4">
                    <h3 className="text-lg font-bold text-slate-400 uppercase tracking-wider pl-1">{section.category}</h3>
                    <div className="grid gap-4">
                        {section.subjects.map((subject) => (
                            <div
                                key={subject.name}
                                className={`
                                    bg-white rounded-xl border transition-all duration-300 overflow-hidden
                                    ${openSubject === subject.name ? 'border-blue-200 shadow-md ring-1 ring-blue-50' : 'border-slate-200 shadow-sm hover:border-slate-300'}
                                `}
                            >
                                <button
                                    onClick={() => setOpenSubject(openSubject === subject.name ? null : subject.name)}
                                    className="w-full flex items-center justify-between p-5 text-left"
                                >
                                    <span className={`font-semibold text-lg ${openSubject === subject.name ? 'text-blue-700' : 'text-slate-900'}`}>
                                        {subject.name} {subject.code && <span className="text-slate-400 font-normal text-sm ml-2">({subject.code})</span>}
                                    </span>
                                    {openSubject === subject.name
                                        ? <ChevronDown className="h-5 w-5 text-blue-500" />
                                        : <ChevronRight className="h-5 w-5 text-slate-400" />
                                    }
                                </button>

                                {openSubject === subject.name && (
                                    <div className="px-5 pb-6 pt-0 animate-in slide-in-from-top-2 duration-200">
                                        <div className="h-px bg-slate-100 mb-4"></div>
                                        <div className="grid md:grid-cols-2 gap-4">
                                            {subject.topics.map((topic, i) => (
                                                <div key={i} className="p-4 rounded-xl bg-slate-50 border border-slate-100 hover:border-blue-100 transition-colors">
                                                    <h4 className="font-semibold text-slate-800 mb-2 flex items-center gap-2">
                                                        <div className="w-1.5 h-1.5 rounded-full bg-blue-500 shrink-0" />
                                                        {topic.title}
                                                    </h4>
                                                    {topic.subtopics && topic.subtopics.length > 0 && (
                                                        <ul className="space-y-1.5 ml-3.5">
                                                            {topic.subtopics.map((sub, j) => (
                                                                <li key={j} className="text-sm text-slate-600 leading-relaxed flex items-start gap-2">
                                                                    <span className="text-slate-300 mt-1.5 text-[10px]">•</span>
                                                                    <span>{sub}</span>
                                                                </li>
                                                            ))}
                                                        </ul>
                                                    )}
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                )}
                            </div>
                        ))}
                    </div>
                </div>
            ))}
        </div>
    );
}

// --- Main Page ---

export default function SyllabusPage() {
    const { user, userData } = useAuth();
    const [stream, setStream] = useState<StreamType>(null);
    const [showGuide, setShowGuide] = useState(false);
    const [showModal, setShowModal] = useState(false);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (userData) {
            setTimeout(() => {
                setStream(userData.stream as StreamType);

                // Logic: 
                // 1. If no stream/target set -> Show Modal
                // 2. If stream set BUT onboarding not completed -> Show Guide
                // 3. If onboarding completed -> Show Syllabus directly

                if (!userData.stream || !userData.targetUniversity) {
                    setShowModal(true);
                } else if (!userData.onboardingCompleted) {
                    setShowGuide(true);
                }

                setLoading(false);
            }, 0);
        }
    }, [userData]);

    const handleOnboardingComplete = async (selectedStream: StreamType, selectedTarget: string) => {
        if (!user) return;
        setStream(selectedStream);
        setShowModal(false);
        setShowGuide(true); // Transition to guide

        try {
            await updateDoc(doc(db, "users", user.uid), {
                stream: selectedStream,
                targetUniversity: selectedTarget
            });
        } catch (err) {
            console.error("Failed to update user profile", err);
        }
    };

    const handleGuideFinish = async () => {
        if (!user) return;
        setShowGuide(false);
        try {
            await updateDoc(doc(db, "users", user.uid), {
                onboardingCompleted: true
            });
        } catch (err) {
            console.error("Failed to mark onboarding complete", err);
        }
    };

    if (loading) return null;

    if (showGuide) {
        return (
            <div className="min-h-screen bg-gradient-to-b from-white to-slate-50">
                <MentorGuide stream={stream} onFinish={handleGuideFinish} />
            </div>
        );
    }

    return (
        <div className="space-y-8 pb-20">
            <div className="flex flex-col md:flex-row md:items-end justify-between gap-4 border-b border-slate-200 pb-6">
                <div>
                    <h1 className="text-3xl font-bold text-slate-900">Syllabus & Roadmap</h1>
                    <p className="text-slate-500 mt-2">Check the official topics for CUET UG 2026</p>
                </div>
                <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => setShowGuide(true)}
                    className="text-indigo-600 hover:text-indigo-700 hover:bg-indigo-50"
                >
                    <Sparkles className="h-4 w-4 mr-2" /> View Mentor Guide
                </Button>
            </div>

            <SyllabusAccordion data={SYLLABUS_DATA} />

            <OnboardingModal isOpen={showModal} onComplete={handleOnboardingComplete} />
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import { firestoreService } from "@/services/firestoreService";
import { Test, TestAttempt } from "@/types/admin";
import { useAuth } from "@/context/AuthContext";
import { TestCard } from "@/components/dashboard/TestCard";
import { Search, Filter } from "lucide-react";
import { PaymentModal } from "@/components/dashboard/PaymentModal";

type FilterType = 'All' | 'Full Mock' | 'Subject' | 'General' | 'Free';

export default function MockTestsPage() {
    const { user, userData } = useAuth();
    const [tests, setTests] = useState<Test[]>([]);
    const [userAttempts, setUserAttempts] = useState<TestAttempt[]>([]);
    const [loading, setLoading] = useState(true);
    const [activeFilter, setActiveFilter] = useState<FilterType>('All');
    const [searchQuery, setSearchQuery] = useState("");

    const [selectedTestToUnlock, setSelectedTestToUnlock] = useState<Test | null>(null);

    useEffect(() => {
        async function loadData() {
            if (!user) return;
            try {
                const [allTests, attempts] = await Promise.all([
                    firestoreService.getTests(true),
                    firestoreService.getUserAttempts(user.uid)
                ]);
                setTests(allTests);
                setUserAttempts(attempts);
            } catch (error) {
                console.error("Error loading tests:", error);
            } finally {
                setLoading(false);
            }
        }
        loadData();
    }, [user]);

    // Derived state for filtering
    const filteredTests = tests.filter(test => {
        // Search filter
        if (searchQuery && !test.title.toLowerCase().includes(searchQuery.toLowerCase())) {
            return false;
        }

        // Category filter
        if (activeFilter === 'All') return true;
        if (activeFilter === 'Free') return test.price === 'free';
        return test.category === activeFilter;
    });

    // Helper to check attempts
    const getAttemptState = (testId: string) => {
        const attempt = userAttempts.find(a => a.testId === testId && a.status === 'in_progress');
        if (attempt) return 'in_progress';

        const completed = userAttempts.some(a => a.testId === testId && a.status === 'completed');
        return completed ? 'completed' : 'new';
    };

    const handleUnlock = (test: Test) => {
        setSelectedTestToUnlock(test);
    };

    const onPaymentSuccess = async () => {
        // Logic to update local state (optimistic UI) - mostly useful if we don't refetch
        // In a real app we'd call an API. Here we just close modal and maybe refresh user?
        // We're currently just showing the UI. The access control is the main part.
        if (selectedTestToUnlock && user) {
            // Mock purchase update in local state for immediate feedback
            // This is "UI only" as requested, but we should clear the modal
        }
        setSelectedTestToUnlock(null);
        // Reload page or re-fetch user to get updated purchasedTests
        window.location.reload();
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center min-h-[400px]">
                <div className="animate-pulse text-slate-400">Loading mock tests...</div>
            </div>
        );
    }

    return (
        <div className="space-y-8">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h1 className="text-2xl font-bold text-slate-900">Mock Tests</h1>
                    <p className="text-slate-500">Practice with official pattern mock tests</p>
                </div>

                <div className="relative">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
                    <input
                        type="text"
                        placeholder="Search tests..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="pl-10 pr-4 py-2 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-100 w-full md:w-64"
                    />
                </div>
            </div>

            {/* Filters */}
            <div className="flex items-center gap-2 overflow-x-auto pb-2 scrollbar-none">
                {(['All', 'Full Mock', 'Subject', 'General', 'Free'] as FilterType[]).map((filter) => (
                    <button
                        key={filter}
                        onClick={() => setActiveFilter(filter)}
                        className={`
                            px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-colors
                            ${activeFilter === filter
                                ? 'bg-slate-900 text-white'
                                : 'bg-white border border-slate-200 text-slate-600 hover:bg-slate-50'}
                        `}
                    >
                        {filter}
                    </button>
                ))}
            </div>

            {/* Grid */}
            {filteredTests.length > 0 ? (
                <div className="grid sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                    {filteredTests.map(test => {
                        const state = getAttemptState(test.id);
                        const isPurchased = !!user?.uid && (test.price === 'free' || !!userData?.purchasedTests?.[test.id]);

                        return (
                            <TestCard
                                key={test.id}
                                test={test}
                                isInProgress={state === 'in_progress'}
                                isAttempted={state === 'completed'}
                                isPurchased={test.price === 'free' || !!userData?.purchasedTests?.[test.id]}
                                onUnlock={handleUnlock}
                            />
                        );
                    })}
                </div>
            ) : (
                <div className="text-center py-16 bg-slate-50 rounded-xl border border-dashed border-slate-200">
                    <h3 className="text-slate-900 font-medium mb-1">No tests found</h3>
                    <p className="text-slate-500 text-sm">Try adjusting your filters or search query.</p>
                </div>
            )}

            {selectedTestToUnlock && (
                <PaymentModal
                    isOpen={!!selectedTestToUnlock}
                    onClose={() => setSelectedTestToUnlock(null)}
                    test={selectedTestToUnlock}
                    onUnlock={onPaymentSuccess}
                />
            )}
        </div>
    );
}

