            // If logged in, they should probably go to dashboard to take mocks
            // but we can let them browse here too if it's a public directory.
            // For now, let's keep it accessible but redirect if they are admin
            if (userData.role === 'admin' || userData.role === 'developer') {
                router.push("/admin");
            }
        }
    }, [user, userData, authLoading, router]);

    // Persist choice in localStorage
    useEffect(() => {
        const savedStream = localStorage.getItem("user_stream_preference");
        if (savedStream) {
            setSelectedStream(savedStream);
            setView('directory');
        }
        loadData();
    }, []);

    async function loadData() {
        setLoading(true);
