                            onClick={integrity.dismissTabWarning}
                            className="bg-amber-600 hover:bg-amber-700 text-white w-full"
                        >
                            I Understand, Return to Test
                        </Button>
                    </div>
                </div>
            )}

            {/* Top Bar - Fixed */}
