import React, { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/Dialog";
import { Button } from "@/components/ui/Button";
import { UnifiedQuestionCard } from "@/components/admin/test-builder/UnifiedQuestionCard";
import { Question, Passage } from "@/types/admin";
import { firestoreService } from "@/services/firestoreService";
import { Loader2 } from "lucide-react";

interface QuestionEditorModalProps {
    isOpen: boolean;
    onClose: () => void;
    questionId: string | null; // null means 'new'
    onSuccess: () => void;
}

export function QuestionEditorModal({ isOpen, onClose, questionId, onSuccess }: QuestionEditorModalProps) {
    const [question, setQuestion] = useState<Question | null>(null);
    const [loading, setLoading] = useState(false);
    const [saving, setSaving] = useState(false);
    const [passages, setPassages] = useState<Passage[]>([]);

    useEffect(() => {
        if (!isOpen) {
            setQuestion(null);
            return;
        }

        loadData();
    }, [isOpen, questionId]);

    const loadData = async () => {
        setLoading(true);
        try {
            // Load passages
            const p = await firestoreService.getPassages();
            setPassages(p);

            if (questionId) {
                // To fetch a single question reliably, we could fetch all and find, or just use getQuestions
                const allQs = await firestoreService.getQuestions();
                const found = allQs.find(q => q.id === questionId);
                if (found) {
                    setQuestion({
                        ...found,
                        questionType: found.questionType || "mcq",
                        matchPairs: found.matchPairs || [{ left: "", right: "" }]
                    });
                }
            } else {
                setQuestion({
                    id: `temp_${Date.now()}`,
                    text: "",
                    options: ["", "", "", ""],
                    correctOption: 0,
                    difficulty: "Medium",
                    stream: "General",
                    subject: "",
                    questionType: "mcq",
                    matchPairs: [{ left: "", right: "" }, { left: "", right: "" }, { left: "", right: "" }, { left: "", right: "" }]
                } as Question);
            }
        } catch (error) {
            console.error("Failed to load question details:", error);
        } finally {
            setLoading(false);
        }
    };

    const handleSave = async () => {
        if (!question) return;

        // Validation
        if (!question.text || (question.options?.length && question.options.some(o => !o))) {
            alert("Please fill in question text and all options.");
            return;
        }

        if (question.questionType === "match") {
            if (question.matchPairs?.some(p => !p.left || !p.right)) {
                alert("Please fill in all match pairs.");
                return;
            }
        }

        setSaving(true);
        try {
            let finalPassageId = question.passageId;
            const passageTextToCreate = (question as any).passageText;

            // Handle inline passage creation
            if (question.questionType === "passage" && passageTextToCreate && passageTextToCreate.trim() !== "") {
                const newId = await firestoreService.createPassage({ text: passageTextToCreate });
                if (newId) {
                    finalPassageId = newId;
                } else {
                    alert("Failed to create the new passage.");
                    setSaving(false);
                    return;
                }
            } else if (question.questionType === "passage" && !finalPassageId) {
                alert("Please select or create a passage for this question.");
                setSaving(false);
                return;
            }

            const payload: any = {
                ...question,
                passageId: question.questionType === "passage" ? finalPassageId : null,
                matchPairs: question.questionType === "match" ? question.matchPairs : null
            };

            // Remove temporary fields
            delete payload.passageText;

            if (questionId) {
                await firestoreService.updateQuestion(question.id, payload);
            } else {
                delete payload.id; // Let Firestore generate the ID
                await firestoreService.createQuestion(payload);
            }

            onSuccess();
            onClose();
        } catch (error) {
            console.error(error);
            alert("Failed to save the question. Check console.");
        } finally {
            setSaving(false);
        }
    };

    return (
        <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
            <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
                <DialogHeader>
                    <DialogTitle>{questionId ? "Edit Question" : "Add New Question"}</DialogTitle>
                    <DialogDescription>
                        Modify the details below to update the question in the global repository.
                    </DialogDescription>
                </DialogHeader>

                <div className="py-4">
                    {loading ? (
                        <div className="flex justify-center items-center py-12 text-slate-500">
                            <Loader2 className="h-6 w-6 animate-spin mr-2" /> Loading...
                        </div>
                    ) : question ? (
                        <div className="w-full">
                            {/* We re-use UnifiedQuestionCard with isDragDisabled=true so it displays full-width and permanently expanded essentially */}
                            <UnifiedQuestionCard
                                question={question}
                                onChange={setQuestion}
                                isExpanded={true}
                                onToggleExpand={() => { }} // Disabled toggle for modal
                                passages={passages}
                                isDragDisabled={true}
                            />
                        </div>
                    ) : (
                        <div className="text-center py-12 text-semantic-error">Failed to load question</div>
                    )}
                </div>

                <div className="flex justify-end gap-3 pt-4 border-t border-border mt-4 pr-4 pb-4">
                    <Button variant="outline" onClick={onClose} disabled={saving}>Cancel</Button>
                    <Button onClick={handleSave} disabled={saving || !question} className="bg-cta-primary hover:bg-cta-hover text-white">
                        {saving ? <><Loader2 className="h-4 w-4 animate-spin mr-2" /> Saving...</> : "Save Question"}
                    </Button>
                </div>
            </DialogContent>
        </Dialog>
    );
}

"use client";

import { useEffect, useState } from "react";
import { Button } from "@/components/ui/Button";
import { PlusCircle, Search, Edit, Trash2, Loader2, RefreshCw, Filter, Upload } from "lucide-react";
import { firestoreService } from "@/services/firestoreService";
import { Question } from "@/types/admin";
import Link from "next/link";
import { Input } from "@/components/ui/Input";
import { CSVImportModal } from "@/components/admin/questions/CSVImportModal";
import { AddToTestModal } from "@/components/admin/questions/AddToTestModal";
import { QuestionEditorModal } from "./QuestionEditorModal";

export function QuestionsTab() {
    const [questions, setQuestions] = useState<Question[]>([]);
    const [loading, setLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState("");
    const [streamFilter, setStreamFilter] = useState("");
    const [subjectFilter, setSubjectFilter] = useState("");
    const [isImportModalOpen, setIsImportModalOpen] = useState(false);
    const [editingQuestionId, setEditingQuestionId] = useState<string | null>(null);

    // Selection State
    const [selectedQuestions, setSelectedQuestions] = useState<string[]>([]);
    const [isAddToTestModalOpen, setIsAddToTestModalOpen] = useState(false);
    const [isBulkDeleting, setIsBulkDeleting] = useState(false);

    useEffect(() => {
        loadQuestions();
    }, []);

    async function loadQuestions() {
        setLoading(true);
        try {
            const data = await firestoreService.getQuestions();
            setQuestions(data);
        } catch (error) {
            console.error("Failed to load questions:", error);
        } finally {
            setLoading(false);
        }
    }

    async function handleDelete(id: string) {
        if (confirm("Are you sure you want to delete this question? This action cannot be undone.")) {
            const success = await firestoreService.deleteQuestion(id);
            if (success) {
                loadQuestions();
                setSelectedQuestions(prev => prev.filter(qId => qId !== id));
            } else {
                alert("Failed to delete question. Please try again.");
            }
        }
    }

    async function handleBulkDelete() {
        if (confirm(`Are you sure you want to delete ${selectedQuestions.length} questions? This cannot be undone.`)) {
            setIsBulkDeleting(true);
            try {
                const success = await firestoreService.batchDeleteQuestions(selectedQuestions);
                if (success) {
                    await loadQuestions();
                    setSelectedQuestions([]);
                } else {
                    alert("Failed to delete some questions.");
                }
            } catch (error) {
                console.error("Bulk delete failed", error);
            } finally {
                setIsBulkDeleting(false);
            }
        }
    }

    const filteredQuestions = questions.filter(q => {
        const matchesSearch = (q.text?.toLowerCase() || "").includes(searchTerm.toLowerCase()) ||
            (q.testId?.toLowerCase() || "").includes(searchTerm.toLowerCase());
        const matchesStream = streamFilter ? q.stream === streamFilter : true;
        const matchesSubject = subjectFilter ? (q.subject || "").toLowerCase().includes(subjectFilter.toLowerCase()) : true;

        return matchesSearch && matchesStream && matchesSubject;
    });

    const toggleSelectAll = () => {
        if (selectedQuestions.length === filteredQuestions.length && filteredQuestions.length > 0) {
            setSelectedQuestions([]);
        } else {
            setSelectedQuestions(filteredQuestions.map(q => q.id));
        }
    };

    const toggleSelect = (id: string) => {
        setSelectedQuestions(prev =>
            prev.includes(id) ? prev.filter(qId => qId !== id) : [...prev, id]
        );
    };

    return (
        <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-500">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                <div className="flex gap-2 w-full sm:w-auto">
                    <Button variant="outline" size="sm" onClick={loadQuestions} className="gap-2">
                        <RefreshCw className="h-4 w-4" /> Refresh
                    </Button>
                    <Button
                        variant="outline"
                        size="sm"
                        onClick={() => setIsImportModalOpen(true)}
                        className="gap-2 border-green-200 bg-green-50 text-green-700 hover:bg-green-100 hover:text-green-800"
                    >
                        <Upload className="h-4 w-4" /> Import CSV
                    </Button>
                    <Button onClick={() => setEditingQuestionId('new')} className="gap-2 bg-blue-600 hover:bg-blue-700 text-white">
                        <PlusCircle className="h-4 w-4" /> Add Question
                    </Button>
                </div>
            </div>

            <CSVImportModal
                isOpen={isImportModalOpen}
                onClose={() => setIsImportModalOpen(false)}
                onSuccess={() => {
                    loadQuestions();
                }}
            />

            <AddToTestModal
                isOpen={isAddToTestModalOpen}
                onClose={() => setIsAddToTestModalOpen(false)}
                questionIds={selectedQuestions}
                onSuccess={() => {
                    setSelectedQuestions([]);
                    loadQuestions(); // Optional: Reload if we show test assignments in table
                }}
            />

            <QuestionEditorModal
                isOpen={editingQuestionId !== null}
                onClose={() => setEditingQuestionId(null)}
                questionId={editingQuestionId === 'new' ? null : editingQuestionId}
                onSuccess={() => {
                    setEditingQuestionId(null);
                    loadQuestions();
                }}
            />

            <div className="bg-white rounded-xl shadow-sm border border-slate-200">
                <div className="p-4 border-b border-slate-100 flex flex-col sm:flex-row gap-4">
                    <div className="relative flex-1">
                        <Search className="absolute left-3 top-2.5 h-4 w-4 text-slate-400" />
                        <Input
                            placeholder="Search questions by text or test ID..."
                            className="pl-9"
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                        />
                    </div>
                    <select
                        className="px-3 py-2 bg-slate-50 border border-slate-200 rounded-md text-sm outline-none w-full sm:w-auto"
                        value={streamFilter}
                        onChange={(e) => setStreamFilter(e.target.value)}
                    >
                        <option value="">All Streams</option>
                        <option value="Science">Science</option>
                        <option value="Commerce">Commerce</option>
                        <option value="Humanities">Humanities</option>
                        <option value="General">General</option>
                    </select>
                    <Input
                        placeholder="Subject..."
                        className="w-full sm:w-40"
                        value={subjectFilter}
                        onChange={(e) => setSubjectFilter(e.target.value)}
                    />
                </div>

                {/* Bulk Actions Bar */}
                {selectedQuestions.length > 0 && (
                    <div className="bg-blue-50 border-b border-blue-100 p-4 flex items-center justify-between animate-in slide-in-from-top-2">
                        <div className="text-sm text-blue-800 font-medium">
                            {selectedQuestions.length} question{selectedQuestions.length > 1 ? 's' : ''} selected
                        </div>
                        <div className="flex gap-2">
                            <Button
                                size="sm"
                                variant="outline"
                                onClick={() => setIsAddToTestModalOpen(true)}
                                className="bg-white text-blue-700 border-blue-200 hover:bg-blue-50 hover:text-blue-800 hover:border-blue-300 transition-colors"
                            >
                                Add to Test
                            </Button>
                            <Button
                                size="sm"
                                variant="outline"
                                onClick={handleBulkDelete}
                                disabled={isBulkDeleting}
                                className="bg-white text-red-700 border-red-200 hover:bg-red-50 hover:text-red-800 hover:border-red-300 transition-colors"
                            >
                                {isBulkDeleting ? <Loader2 className="h-4 w-4 animate-spin" /> : "Delete Selected"}
                            </Button>
                        </div>
                    </div>
                )}

                {/* Desktop Table */}
                <div className="hidden sm:block overflow-x-auto">
                    <table className="w-full text-left text-sm">
                        <thead className="bg-slate-50 text-slate-500 font-medium border-b border-slate-200">
                            <tr>
                                <th className="px-6 py-4 w-4">
                                    <input
                                        type="checkbox"
                                        className="rounded border-slate-300"
                                        checked={selectedQuestions.length > 0 && selectedQuestions.length === filteredQuestions.length}
                                        onChange={toggleSelectAll}
                                    />
                                </th>
                                <th className="px-6 py-4 w-[50%]">Question Text</th>
                                <th className="px-6 py-4">Test ID</th>
                                <th className="px-6 py-4">Options</th>
                                <th className="px-6 py-4 text-right">Actions</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {loading ? (
                                <tr>
                                    <td colSpan={5} className="px-6 py-12 text-center text-slate-500">
                                        <div className="flex justify-center items-center gap-2">
                                            <Loader2 className="h-5 w-5 animate-spin text-blue-500" />
                                            Loading questions...
                                        </div>
                                    </td>
                                </tr>
                            ) : filteredQuestions.length === 0 ? (
                                <tr>
                                    <td colSpan={5} className="px-6 py-12 text-center text-slate-500">No questions found.</td>
                                </tr>
                            ) : (
                                filteredQuestions.map((q) => (
                                    <tr
                                        key={q.id}
                                        className={`hover:bg-slate-50 transition-colors group ${selectedQuestions.includes(q.id) ? 'bg-blue-50/30' : ''}`}
                                    >
                                        <td className="px-6 py-4">
                                            <input
                                                type="checkbox"
                                                className="rounded border-slate-300"
                                                checked={selectedQuestions.includes(q.id)}
                                                onChange={() => toggleSelect(q.id)}
                                            />
                                        </td>
                                        <td className="px-6 py-4">
                                            <div className="font-medium text-slate-900 line-clamp-2" title={q.text}>
                                                {q.text}
                                            </div>
                                        </td>
                                        <td className="px-6 py-4">
                                            <span className="font-mono text-xs text-slate-500 bg-slate-100 px-2 py-1 rounded">
                                                {q.testId || "Unassigned"}
                                            </span>
                                        </td>
                                        <td className="px-6 py-4 text-slate-600">
                                            {q.options?.length || 0}
                                        </td>
                                        <td className="px-6 py-4 text-right">
                                            <div className="flex items-center justify-end gap-2">
                                                <Button variant="outline" size="sm" className="h-9 w-9 p-0 text-slate-500 hover:text-blue-600 hover:bg-blue-50 border-slate-200" onClick={() => setEditingQuestionId(q.id)} title="Edit">
                                                    <Edit className="h-4 w-4" />
                                                </Button>
                                                <Button
                                                    variant="outline"
                                                    size="sm"
                                                    className="h-9 w-9 p-0 text-slate-500 hover:text-red-600 hover:bg-red-50 border-slate-200"
                                                    onClick={() => handleDelete(q.id)}
                                                    title="Delete"
                                                >
                                                    <Trash2 className="h-4 w-4" />
                                                </Button>
                                            </div>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>

                {/* Mobile Card List */}
                <div className="sm:hidden divide-y divide-slate-100">
                    {loading ? (
                        <div className="px-6 py-12 text-center text-slate-500">
                            <div className="flex justify-center items-center gap-2">
                                <Loader2 className="h-5 w-5 animate-spin text-blue-500" />
                                Loading...
                            </div>
                        </div>
                    ) : filteredQuestions.length === 0 ? (
                        <div className="px-6 py-12 text-center text-slate-500">No questions found.</div>
                    ) : (
                        filteredQuestions.map((q) => (
                            <div key={q.id} className="p-4 space-y-3">
                                <div className="flex items-start gap-3">
                                    <input
                                        type="checkbox"
                                        className="rounded border-slate-300 mt-1"
                                        checked={selectedQuestions.includes(q.id)}
                                        onChange={() => toggleSelect(q.id)}
                                    />
                                    <div className="flex-1 space-y-2">
                                        <div className="flex justify-between items-start">
                                            <div className="pr-4">
                                                <p className="font-medium text-slate-900 line-clamp-3 text-sm">{q.text}</p>
                                            </div>
                                            <div className="flex gap-1 shrink-0">
                                                <Button variant="ghost" size="sm" className="h-8 w-8 p-0 text-slate-400 hover:text-blue-600" onClick={() => setEditingQuestionId(q.id)}>
                                                    <Edit className="h-4 w-4" />
                                                </Button>
                                                <Button
                                                    variant="ghost"
                                                    size="sm"
                                                    className="h-8 w-8 p-0 text-slate-400 hover:text-red-600"
                                                    onClick={() => handleDelete(q.id)}
                                                >
                                                    <Trash2 className="h-4 w-4" />
                                                </Button>
                                            </div>
                                        </div>
                                        <div className="flex gap-2 text-xs text-slate-500 flex-wrap">
                                            {q.stream && <span className="bg-slate-100 px-2 py-1 rounded">{q.stream}</span>}
                                            {q.subject && <span className="bg-slate-100 px-2 py-1 rounded">{q.subject}</span>}
                                            <span className={`px-2 py-1 rounded border ${q.difficulty === 'Hard' ? 'bg-red-50 text-red-700 border-red-100' : q.difficulty === 'Easy' ? 'bg-green-50 text-green-700 border-green-100' : 'bg-yellow-50 text-yellow-700 border-yellow-100'}`}>
                                                {q.difficulty || 'Medium'}
                                            </span>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        ))
                    )}
                </div>
            </div>
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import { Button } from "@/components/ui/Button";
import { PlusCircle, Search, Edit, Trash2, Eye, BarChart2, Filter } from "lucide-react";
import { firestoreService } from "@/services/firestoreService";
import { Test } from "@/types/admin";
import Link from "next/link";
import { Input } from "@/components/ui/Input";

import { useAuth } from "@/context/AuthContext";

export function TestsTab() {
    const [tests, setTests] = useState<Test[]>([]);
    const [loading, setLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState("");
    const [streamFilter, setStreamFilter] = useState("");
    const [categoryFilter, setCategoryFilter] = useState("");

    const { user, userData } = useAuth(); // Get auth context

    useEffect(() => {
        if (user && userData) {
            console.log("TestsTab: User:", user.uid, "Role:", userData.role);
            console.log("TestsTab: Loading tests...");
            loadTests();
        } else {
            console.log("TestsTab: Waiting for auth...");
        }
    }, [user, userData]);

    async function loadTests() {
        setLoading(true);
        try {
            const data = await firestoreService.getTests();
            console.log("TestsTab: Fetched tests:", data.length);
            setTests(data);
        } catch (err) {
            console.error("TestsTab: Permission Error?", err);
        }
        setLoading(false);
    }

    const [selectedTests, setSelectedTests] = useState<string[]>([]);
    const [isBulkUpdating, setIsBulkUpdating] = useState(false);

    async function handleBulkAction(action: 'publish' | 'draft' | 'delete') {
        if (!confirm(`Are you sure you want to ${action} ${selectedTests.length} tests?`)) return;

        setIsBulkUpdating(true);
        try {
            const promises = selectedTests.map(id => {
                if (action === 'delete') return firestoreService.deleteTest(id);
                return firestoreService.updateTest(id, { status: action === 'publish' ? 'published' : 'draft' });
            });

            await Promise.all(promises);
            await loadTests();
            setSelectedTests([]); // Clear selection
        } catch (error) {
            console.error("Bulk action failed:", error);
            alert("Some items failed to update. Check console.");
        } finally {
            setIsBulkUpdating(false);
        }
    }

    const toggleSelectAll = () => {
        if (selectedTests.length === filteredTests.length) {
            setSelectedTests([]);
        } else {
            setSelectedTests(filteredTests.map(t => t.id));
        }
    };

    const toggleSelect = (id: string) => {
        setSelectedTests(prev =>
            prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]
        );
    };

    async function handleDelete(id: string) {
        if (confirm("Are you sure you want to delete this test?")) {
            const success = await firestoreService.deleteTest(id);
            if (success) loadTests();
        }
    }

    const filteredTests = tests.filter(t => {
        const matchesSearch = t.title.toLowerCase().includes(searchTerm.toLowerCase());
        const matchesStream = streamFilter ? t.streams?.includes(streamFilter) : true;
        const matchesCategory = categoryFilter ? t.category === categoryFilter : true;
        return matchesSearch && matchesStream && matchesCategory;
    });

    return (
        <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-500">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                <div className="w-full sm:w-auto">
                    <Link href="/admin/tests/new">
                        <Button className="gap-2 bg-blue-600 hover:bg-blue-700 text-white shadow-sm shadow-blue-200">
                            <PlusCircle className="h-4 w-4" /> Create New Test
                        </Button>
                    </Link>
                </div>
            </div>

            <div className="bg-white rounded-xl shadow-sm border border-slate-200">
                {/* Filters */}
                <div className="p-4 border-b border-slate-100 flex flex-col sm:flex-row gap-4">
                    <div className="relative flex-1">
                        <Search className="absolute left-3 top-2.5 h-4 w-4 text-slate-400" />
                        <Input
                            placeholder="Search tests..."
                            className="pl-9"
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                        />
                    </div>
                    <select
                        className="px-3 py-2 bg-slate-50 border border-slate-200 rounded-md text-sm outline-none w-full sm:w-auto"
                        value={streamFilter}
                        onChange={(e) => setStreamFilter(e.target.value)}
                    >
                        <option value="">All Streams</option>
                        <option value="Science">Science</option>
                        <option value="Commerce">Commerce</option>
                        <option value="Humanities">Humanities</option>
                        <option value="General">General</option>
                        <option value="English">English</option>
                    </select>
                    <select
                        className="px-3 py-2 bg-slate-50 border border-slate-200 rounded-md text-sm outline-none w-full sm:w-auto"
                        value={categoryFilter}
                        onChange={(e) => setCategoryFilter(e.target.value)}
                    >
                        <option value="">All Categories</option>
                        <option value="Full Mock">Full Mock</option>
                        <option value="Subject">Subject Test</option>
                        <option value="General">General Test</option>
                    </select>
                </div>

                {/* Bulk Actions Bar */}
                {selectedTests.length > 0 && (
                    <div className="bg-blue-50 border-b border-blue-100 p-4 flex items-center justify-between animate-in slide-in-from-top-2">
                        <div className="text-sm text-blue-800 font-medium">
                            {selectedTests.length} test{selectedTests.length > 1 ? 's' : ''} selected
                        </div>
                        <div className="flex gap-2">
                            <Button size="sm" onClick={() => handleBulkAction('publish')} disabled={isBulkUpdating} className="bg-white text-green-700 border border-green-200 hover:bg-green-50">
                                Publish Selected
                            </Button>
                            <Button size="sm" onClick={() => handleBulkAction('draft')} disabled={isBulkUpdating} className="bg-white text-slate-700 border border-slate-300 hover:bg-slate-50">
                                Unpublish Selected
                            </Button>
                            <Button size="sm" onClick={() => handleBulkAction('delete')} disabled={isBulkUpdating} className="bg-white text-red-700 border border-red-200 hover:bg-red-50">
                                Delete Selected
                            </Button>
                        </div>
                    </div>
                )}

                {/* Desktop Table */}
                <div className="hidden sm:block overflow-x-auto">
                    <table className="w-full text-left text-sm">
                        <thead className="bg-slate-50 text-slate-500 font-medium border-b border-slate-200">
                            <tr>
                                <th className="px-6 py-4 w-4">
                                    <input
                                        type="checkbox"
                                        className="rounded border-slate-300"
                                        checked={selectedTests.length > 0 && selectedTests.length === filteredTests.length}
                                        onChange={toggleSelectAll}
                                    />
                                </th>
                                <th className="px-6 py-4">Title</th>
                                <th className="px-6 py-4">Streams</th>
                                <th className="px-6 py-4">Category</th>
                                <th className="px-6 py-4">Questions</th>
                                <th className="px-6 py-4">Status</th>
                                <th className="px-6 py-4 text-right">Actions</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {filteredTests.length === 0 ? (
                                <tr>
                                    <td colSpan={7} className="px-6 py-12 text-center text-slate-500">
                                        {loading ? "Loading tests..." : "No tests found."}
                                    </td>
                                </tr>
                            ) : (
                                filteredTests.map((test) => (
                                    <tr key={test.id} className={`hover:bg-slate-50 transition-colors group ${selectedTests.includes(test.id) ? 'bg-blue-50/30' : ''}`}>
                                        <td className="px-6 py-4">
                                            <input
                                                type="checkbox"
                                                className="rounded border-slate-300"
                                                checked={selectedTests.includes(test.id)}
                                                onChange={() => toggleSelect(test.id)}
                                            />
                                        </td>
                                        <td className="px-6 py-4">
                                            <div className="font-medium text-slate-900">{test.title}</div>
                                            <div className="text-xs text-slate-500 mt-0.5 max-w-xs truncate">
                                                {test.description}
                                            </div>
                                        </td>
                                        <td className="px-6 py-4">
                                            <div className="flex flex-wrap gap-1">
                                                {test.streams?.map(s => (
                                                    <span key={s} className="text-xs bg-slate-100 px-2 py-1 rounded text-slate-600">
                                                        {s}
                                                    </span>
                                                )) || "General"}
                                            </div>
                                        </td>
                                        <td className="px-6 py-4 text-slate-600">
                                            {test.category}
                                        </td>
                                        <td className="px-6 py-4 text-slate-600">
                                            {test.questions?.length || test.questionIds?.length || 0}
                                        </td>
                                        <td className="px-6 py-4">
                                            <span className={`inline-flex items-center px-2 py-1 rounded-full text-xs font-medium ${test.status === 'published'
                                                ? 'bg-green-100 text-green-700'
                                                : 'bg-slate-100 text-slate-600'
                                                }`}>
                                                {test.status === 'published' ? 'Published' : 'Draft'}
                                            </span>
                                        </td>
                                        <td className="px-6 py-4 text-right">
                                            <div className="flex items-center justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                                <Link href={`/test/${test.id}`} target="_blank">
                                                    <Button variant="outline" size="sm" className="h-9 w-9 p-0 text-slate-500 hover:text-blue-600 hover:bg-blue-50 border-slate-200" title="Preview">
                                                        <Eye className="h-4 w-4" />
                                                    </Button>
                                                </Link>
                                                <Link href={`/admin/tests/${test.id}`}>
                                                    <Button variant="outline" size="sm" className="h-9 w-9 p-0 text-slate-500 hover:text-indigo-600 hover:bg-indigo-50 border-slate-200" title="Edit">
                                                        <Edit className="h-4 w-4" />
                                                    </Button>
                                                </Link>
                                                <Button
                                                    variant="outline"
                                                    size="sm"
                                                    className="h-9 w-9 p-0 text-slate-500 hover:text-red-600 hover:bg-red-50 border-slate-200"
                                                    onClick={() => handleDelete(test.id)}
                                                    title="Delete"
                                                >
                                                    <Trash2 className="h-4 w-4" />
                                                </Button>
                                            </div>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>

                {/* Mobile Card List */}
                <div className="sm:hidden divide-y divide-slate-100">
                    {filteredTests.length === 0 ? (
                        <div className="px-6 py-12 text-center text-slate-500">
                            {loading ? "Loading tests..." : "No tests found."}
                        </div>
                    ) : (
                        filteredTests.map((test) => (
                            <div key={test.id} className="p-4 space-y-3">
                                <div className="flex justify-between items-start">
                                    <div>
                                        <h3 className="font-medium text-slate-900">{test.title}</h3>
                                        <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-medium mt-1 ${test.status === 'published'
                                            ? 'bg-green-100 text-green-700'
                                            : 'bg-slate-100 text-slate-600'
                                            }`}>
                                            {test.status === 'published' ? 'Published' : 'Draft'}
                                        </span>
                                    </div>
                                    <div className="flex gap-1">
                                        <Link href={`/admin/tests/${test.id}`}>
                                            <Button variant="ghost" size="sm" className="h-8 w-8 p-0 text-slate-400 hover:text-blue-600">
                                                <Edit className="h-4 w-4" />
                                            </Button>
                                        </Link>
                                        <Button
                                            variant="ghost"
                                            size="sm"
                                            className="h-8 w-8 p-0 text-slate-400 hover:text-red-600"
                                            onClick={() => handleDelete(test.id)}
                                        >
                                            <Trash2 className="h-4 w-4" />
                                        </Button>
                                    </div>
                                </div>
                                <div className="flex gap-2 text-xs text-slate-500 overflow-x-auto">
                                    {test.streams?.map(s => (
                                        <span key={s} className="bg-slate-100 px-2 py-1 rounded shrink-0">{s}</span>
                                    )) || "General"}
                                    <span className="bg-slate-100 px-2 py-1 rounded shrink-0">{test.category}</span>
                                    <span className="bg-slate-100 px-2 py-1 rounded shrink-0">{test.questions?.length || test.questionIds?.length || 0} Qs</span>
                                </div>
                            </div>
                        ))
                    )}
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogFooter
} from "@/components/ui/Dialog";
import { Button } from "@/components/ui/Button";
import { Input } from "@/components/ui/Input";
import { firestoreService } from "@/services/firestoreService";
import { Test } from "@/types/admin";
import { Loader2, Search, Plus, FileText, Check } from "lucide-react";

interface AddToTestModalProps {
    isOpen: boolean;
    onClose: () => void;
    questionIds: string[];
    onSuccess: () => void;
}

export function AddToTestModal({ isOpen, onClose, questionIds, onSuccess }: AddToTestModalProps) {
    const [activeTab, setActiveTab] = useState<'existing' | 'new'>('existing');
    const [isLoading, setIsLoading] = useState(false);

    // Existing Test State
    const [tests, setTests] = useState<Test[]>([]);
    const [searchTerm, setSearchTerm] = useState("");
    const [selectedTestId, setSelectedTestId] = useState<string | null>(null);
    const [loadingTests, setLoadingTests] = useState(false);

    // New Test State
    const [newTest, setNewTest] = useState({
        title: "",
        description: "",
        stream: "General",
        category: "Genera", // Typo fixed in render
        duration: 60,
        totalMarks: 100,
        difficulty: "Medium"
    });

    useEffect(() => {
        if (isOpen && activeTab === 'existing') {
            loadTests();
        }
    }, [isOpen, activeTab]);

    async function loadTests() {
        setLoadingTests(true);
        try {
            const data = await firestoreService.getTests();
            setTests(data);
        } catch (error) {
            console.error("Failed to load tests", error);
        } finally {
            setLoadingTests(false);
        }
    }

    const filteredTests = tests.filter(t =>
        t.title.toLowerCase().includes(searchTerm.toLowerCase())
    );

    async function handleAddToExisting() {
        if (!selectedTestId) return;
        setIsLoading(true);
        try {
            await firestoreService.addQuestionsToTest(selectedTestId, questionIds);
            onSuccess();
            onClose();
        } catch (error) {
            console.error("Failed to add to test", error);
            alert("Failed to add questions to test.");
        } finally {
            setIsLoading(false);
        }
    }

    async function handleCreateAndAdd() {
        if (!newTest.title) return;
        setIsLoading(true);
        try {
            // 1. Create Test
            const testId = await firestoreService.createTest({
                ...newTest,
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                category: newTest.category as any,
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                difficulty: newTest.difficulty as any,
                streams: [newTest.stream]
            });

            if (testId) {
                // 2. Add Questions
                await firestoreService.addQuestionsToTest(testId, questionIds);
                onSuccess();
                onClose();
            } else {
                throw new Error("Failed to create test");
            }
        } catch (error) {
            console.error("Failed to create and add", error);
            alert("Failed to create test.");
        } finally {
            setIsLoading(false);
        }
    }

    return (
        <Dialog open={isOpen} onOpenChange={onClose}>
            <DialogContent className="max-w-md max-h-[90vh] overflow-y-auto">
                <DialogHeader>
                    <DialogTitle>Add {questionIds.length} Questions to Test</DialogTitle>
                </DialogHeader>

                <div className="flex gap-2 mb-4 border-b border-slate-100 pb-2">
                    <button
                        onClick={() => setActiveTab('existing')}
                        className={`flex-1 pb-2 text-sm font-medium transition-colors ${activeTab === 'existing'
                                ? 'text-blue-600 border-b-2 border-blue-600'
                                : 'text-slate-500 hover:text-slate-800'
                            }`}
                    >
                        Existing Test
                    </button>
                    <button
                        onClick={() => setActiveTab('new')}
                        className={`flex-1 pb-2 text-sm font-medium transition-colors ${activeTab === 'new'
                                ? 'text-blue-600 border-b-2 border-blue-600'
                                : 'text-slate-500 hover:text-slate-800'
                            }`}
                    >
                        Create New Test
                    </button>
                </div>

                {activeTab === 'existing' && (
                    <div className="space-y-4">
                        <div className="relative">
                            <Search className="absolute left-3 top-2.5 h-4 w-4 text-slate-400" />
                            <Input
                                placeholder="Search tests..."
                                className="pl-9"
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                            />
                        </div>

                        <div className="h-60 overflow-y-auto border rounded-md divide-y">
                            {loadingTests ? (
                                <div className="flex justify-center items-center h-full">
                                    <Loader2 className="h-6 w-6 animate-spin text-slate-400" />
                                </div>
                            ) : filteredTests.length === 0 ? (
                                <div className="p-4 text-center text-sm text-slate-500">No tests found.</div>
                            ) : (
                                filteredTests.map(test => (
                                    <div
                                        key={test.id}
                                        onClick={() => setSelectedTestId(test.id)}
                                        className={`p-3 cursor-pointer hover:bg-slate-50 flex items-center justify-between ${selectedTestId === test.id ? 'bg-blue-50 border-l-4 border-blue-500' : ''
                                            }`}
                                    >
                                        <div>
                                            <p className="font-medium text-sm text-slate-900">{test.title}</p>
                                            <p className="text-xs text-slate-500">{test.questions?.length || 0} questions • {test.streams?.join(", ")}</p>
                                        </div>
                                        {selectedTestId === test.id && <Check className="h-4 w-4 text-blue-600" />}
                                    </div>
                                ))
                            )}
                        </div>

                        <DialogFooter>
                            <Button variant="outline" onClick={onClose}>Cancel</Button>
                            <Button
                                onClick={handleAddToExisting}
                                disabled={!selectedTestId || isLoading}
                                className="bg-blue-600 hover:bg-blue-700 text-white"
                            >
                                {isLoading ? <Loader2 className="h-4 w-4 animate-spin" /> : "Add to Test"}
                            </Button>
                        </DialogFooter>
                    </div>
                )}

                {activeTab === 'new' && (
                    <div className="space-y-4">
                        <div className="space-y-2">
                            <label className="text-sm font-medium">Test Title</label>
                            <Input
                                value={newTest.title}
                                onChange={(e) => setNewTest({ ...newTest, title: e.target.value })}
                                placeholder="e.g. Physics Chapter 1 Quiz"
                            />
                        </div>

                        <div className="grid grid-cols-2 gap-4">
                            <div className="space-y-2">
                                <label className="text-sm font-medium">Stream</label>
                                <select
                                    className="w-full h-10 px-3 rounded-md border border-slate-200 bg-white text-sm"
                                    value={newTest.stream}
                                    onChange={(e) => setNewTest({ ...newTest, stream: e.target.value })}
                                >
                                    <option value="General">General</option>
                                    <option value="Science">Science</option>
                                    <option value="Commerce">Commerce</option>
                                    <option value="Humanities">Humanities</option>
                                </select>
                            </div>
                            <div className="space-y-2">
                                <label className="text-sm font-medium">Category</label>
                                <select
                                    className="w-full h-10 px-3 rounded-md border border-slate-200 bg-white text-sm"
                                    value={newTest.category}
                                    onChange={(e) => setNewTest({ ...newTest, category: e.target.value })}
                                >
                                    <option value="General">General Test</option>
                                    <option value="Subject">Subject Test</option>
                                    <option value="Full Mock">Full Mock</option>
                                </select>
                            </div>
                        </div>

                        <div className="space-y-2">
                            <label className="text-sm font-medium">Description (Optional)</label>
                            <Input
                                value={newTest.description}
                                onChange={(e) => setNewTest({ ...newTest, description: e.target.value })}
                                placeholder="Short description..."
                            />
                        </div>

                        <DialogFooter>
                            <Button variant="outline" onClick={onClose}>Cancel</Button>
                            <Button
                                onClick={handleCreateAndAdd}
                                disabled={!newTest.title || isLoading}
                                className="bg-green-600 hover:bg-green-700 text-white"
                            >
                                {isLoading ? <Loader2 className="h-4 w-4 animate-spin" /> : "Create & Add"}
                            </Button>
                        </DialogFooter>
                    </div>
                )}
            </DialogContent>
        </Dialog>
    );
}

"use client";

import { useState } from "react";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogDescription,
    DialogFooter
} from "@/components/ui/Dialog";
import { Button } from "@/components/ui/Button";
import { FileUploader } from "./FileUploader";
import { QuestionPreviewTable } from "./QuestionPreviewTable";
import { parseCSV, ParseResult, ParsedRow } from "@/utils/csvParser";
import { firestoreService } from "@/services/firestoreService";
import { Question } from "@/types/admin";
import { Loader2, CheckCircle, AlertCircle, Upload, FileDown, AlertTriangle } from "lucide-react";

interface CSVImportModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSuccess: () => void;
    onPrepopulateFromCSV?: (questions: Partial<Question>[]) => void;
}

export function CSVImportModal({ isOpen, onClose, onSuccess, onPrepopulateFromCSV }: CSVImportModalProps) {
    const [step, setStep] = useState<"upload" | "validating" | "preview" | "uploading" | "result">("upload");
    const [file, setFile] = useState<File | null>(null);
    const [parseResult, setParseResult] = useState<ParseResult | null>(null);
    const [uploadStats, setUploadStats] = useState<{ success: number; failed: number; errors: string[] } | null>(null);
    const [duplicates, setDuplicates] = useState<Partial<Question>[]>([]);
    const [duplicateAction, setDuplicateAction] = useState<"skip" | "allow" | "overwrite">("skip");
    const [uploadProgress, setUploadProgress] = useState(0);

    const handleFileSelect = async (selectedFile: File) => {
        setFile(selectedFile);
        try {
            setStep("validating");
            const result = await parseCSV(selectedFile);


            // Check for duplicates in DB
            const existingSignatures = await firestoreService.getQuestionSignatures();
            const dups: Partial<Question>[] = [];

            // Mark duplicates directly in the rows array
            result.rows.forEach(row => {
                if (!row.valid) return; // Skip checking invalid rows
                const q = row.data;
                const isDup = existingSignatures.some(ex =>
                    ex.text === (q.text || "").trim().toLowerCase() &&
                    (!q.subject || ex.subject === (q.subject || "").trim().toLowerCase())
                );

                if (isDup) {
                    // eslint-disable-next-line @typescript-eslint/no-explicit-any
                    (row as any).isDuplicate = true;
                    dups.push(q);
                }
            });

            setDuplicates(dups);
            // result.duplicates = dups; // No longer needed on ParseResult directly if using rows

            setParseResult(result);
            setStep("preview");
        } catch (error) {
            console.error("Failed to parse CSV:", error);
            setStep("upload");
            // Could set error state here
        }
    };

    const handleDownloadTemplate = () => {
        const headers = [
            "questionType", "listA", "listB", "passageId", "passageText",
            "questionText", "optionA", "optionB", "optionC", "optionD",
            "correctAnswer", "explanation", "subjectTag", "topicTag",
            "difficulty", "marks", "negativeMarks", "streams"
        ];
        const dummyRow1 = [
            "mcq", "", "", "", "",
            "What is the capital of France?", "London", "Berlin", "Paris", "Madrid",
            "C", "Paris is the capital of France.", "Geography", "World Capitals",
            "Easy", "5", "1", "Humanities"
        ];
        // Match example
        const dummyRow2 = [
            "match", "A:Apple|B:Banana", "1:Red|2:Yellow", "", "",
            "Match the fruits with their colors.", "", "", "", "",
            "A-1, B-2", "Apples are red, bananas are yellow.", "Science", "Botany",
            "Medium", "5", "1", "Science"
        ];
        // Passage example (Using passageText leaves passageId blank. The system auto-generates passageId)
        const dummyRow3 = [
            "passage", "", "", "", "This is a sample passage text. System will auto-create passageId for it.",
            "According to the passage what is it?", "A sample", "A book", "A movie", "A song",
            "A", "The passage explicitly says it is a sample.", "English", "Reading Comprehension",
            "Hard", "5", "1", "General"
        ];

        const csvContent = "data:text/csv;charset=utf-8,"
            + headers.join(",") + "\n"
            + dummyRow1.map(val => `"${val}"`).join(",") + "\n"
            + dummyRow2.map(val => `"${val}"`).join(",") + "\n"
            + dummyRow3.map(val => `"${val}"`).join(",");

        const encodedUri = encodeURI(csvContent);
        const link = document.createElement("a");
        link.setAttribute("href", encodedUri);
        link.setAttribute("download", "question_import_template.csv");
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    const handleUpload = async () => {
        if (!parseResult || parseResult.rows.length === 0) return;

        // Filter valid questions
        let validRows = parseResult.rows.filter(r => r.valid);

        if (validRows.length === 0) return; // No valid data

        setStep("uploading");
        setUploadProgress(0);

        // Filter based on duplicate action
        if (duplicateAction === "skip") {
            // Remove those marked as duplicate
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            validRows = validRows.filter(r => !(r as any).isDuplicate);
        }

        let questionsToUpload = validRows.map(r => r.data);

        // --- Handle Passage Creation ---
        // Group by passageText to avoid creating duplicates for the same passage in one CSV
        const passageTextMap = new Map<string, string>(); // text -> new passageId

        for (const q of questionsToUpload) {
            // we attached passageText temporally on q (which is Partial<Question> anyway and passes down)
            const passageText = (q as any).passageText;
            if (q.questionType === 'passage' && passageText && !q.passageId) {
                if (!passageTextMap.has(passageText)) {
                    // Create passage
                    const newId = await firestoreService.createPassage({ text: passageText });
                    if (newId) passageTextMap.set(passageText, newId);
                }
            }
        }

        // Assign created passageIds
        questionsToUpload = questionsToUpload.map(q => {
            const passageText = (q as any).passageText;
            if (q.questionType === 'passage' && passageText && !q.passageId) {
                const createdId = passageTextMap.get(passageText);
                if (createdId) {
                    q.passageId = createdId;
                }
            }
            // Clean up temporary property
            const finalQ = { ...q };
            delete (finalQ as any).passageText;
            return finalQ;
        });

        if (onPrepopulateFromCSV) {
            onPrepopulateFromCSV(questionsToUpload);
            resetModal();
            onClose();
            return;
        }

        const result = await firestoreService.batchCreateQuestions(
            questionsToUpload,
            (progress) => setUploadProgress(progress)
        );

        setUploadStats(result);
        setStep("result");
        if (result.success > 0) {
            onSuccess();
        }
    };

    const resetModal = () => {
        setStep("upload");
        setFile(null);
        setParseResult(null);
        setUploadStats(null);
        setDuplicates([]);
        setUploadProgress(0);
    };

    const handleClose = () => {
        if (step === "uploading") return;
        resetModal();
        onClose();
    };

    return (
        <Dialog open={isOpen} onOpenChange={handleClose}>
            <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
                <DialogHeader>
                    <DialogTitle>Import Questions via CSV</DialogTitle>
                    <DialogDescription>
                        Bulk upload questions. Download the template to ensure correct formatting.
                    </DialogDescription>
                </DialogHeader>

                <div className="mt-4">
                    {step === "upload" && (
                        <div className="space-y-4">
                            <FileUploader onFileSelect={handleFileSelect} />
                            <div className="flex justify-center">
                                <Button variant="outline" size="sm" onClick={handleDownloadTemplate} className="gap-2 text-slate-600">
                                    <FileDown className="h-4 w-4" /> Download Template
                                </Button>
                            </div>
                        </div>
                    )}

                    {step === "validating" && (
                        <div className="flex flex-col items-center justify-center py-12 space-y-4">
                            <Loader2 className="h-10 w-10 animate-spin text-blue-500" />
                            <p className="text-slate-600">Validating CSV and checking for duplicates...</p>
                        </div>
                    )}

                    {step === "preview" && parseResult && (
                        <div className="space-y-4">
                            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                                <h3 className="text-sm font-medium">Preview Data</h3>
                                {duplicates.length > 0 && (
                                    <div className="flex items-center gap-2 bg-amber-50 px-3 py-1 rounded border border-amber-200">
                                        <AlertTriangle className="h-4 w-4 text-amber-600" />
                                        <span className="text-xs font-medium text-amber-700">Duplicates Action:</span>
                                        <select
                                            value={duplicateAction}
                                            onChange={(e) => setDuplicateAction(e.target.value as "skip" | "allow" | "overwrite")}
                                            className="text-xs bg-white border border-amber-300 rounded px-2 py-0.5 outline-none text-slate-700"
                                        >
                                            <option value="skip">Skip Duplicates</option>
                                            <option value="allow">Allow (Create Copies)</option>
                                        </select>
                                    </div>
                                )}
                            </div>
                            <QuestionPreviewTable parseResult={parseResult} />
                        </div>
                    )}

                    {step === "uploading" && (
                        <div className="flex flex-col items-center justify-center py-12 space-y-4 w-full max-w-md mx-auto">
                            <Loader2 className="h-10 w-10 animate-spin text-blue-600" />
                            <p className="text-slate-600 font-medium">Uploading questions...</p>
                            <div className="w-full bg-slate-100 rounded-full h-2.5 overflow-hidden">
                                <div
                                    className="bg-blue-600 h-2.5 rounded-full transition-all duration-300"
                                    style={{ width: `${uploadProgress}%` }}
                                ></div>
                            </div>
                            <p className="text-xs text-slate-400">{uploadProgress}% Complete</p>
                            <p className="text-sm text-slate-500 text-center">Please do not close this window.</p>
                        </div>
                    )}

                    {step === "result" && uploadStats && (
                        <div className="space-y-6 py-4">
                            <div className={`flex flex-col items-center justify-center p-6 rounded-lg ${uploadStats.success > 0 ? 'bg-green-50' : 'bg-red-50'}`}>
                                {uploadStats.success > 0 ? (
                                    <CheckCircle className="h-12 w-12 text-green-600 mb-2" />
                                ) : (
                                    <AlertCircle className="h-12 w-12 text-red-600 mb-2" />
                                )}
                                <h3 className="text-lg font-bold text-slate-900">
                                    {uploadStats.success > 0 ? "Import Complete" : "Import Failed"}
                                </h3>
                                <p className="text-slate-600 text-center mt-1">
                                    Successfully imported <span className="font-bold text-slate-900">{uploadStats.success}</span> questions.
                                    {uploadStats.failed > 0 && (
                                        <span className="text-red-600 ml-1">({uploadStats.failed} failed/skipped)</span>
                                    )}
                                </p>
                            </div>

                            {uploadStats.errors.length > 0 && (
                                <div className="bg-slate-50 border border-slate-200 rounded-lg p-4 max-h-40 overflow-y-auto">
                                    <h4 className="font-medium text-slate-900 mb-2 text-sm">Error Log</h4>
                                    <ul className="space-y-1 text-xs text-red-600 font-mono">
                                        {uploadStats.errors.map((err, idx) => (
                                            <li key={idx}>{err}</li>
                                        ))}
                                    </ul>
                                </div>
                            )}
                        </div>
                    )}
                </div>

                <DialogFooter className="mt-6 gap-2">
                    {(step === "upload" || step === "preview") && (
                        <Button variant="outline" onClick={handleClose}>Cancel</Button>
                    )}

                    {step === "preview" && (
                        <>
                            <Button variant="outline" onClick={() => setStep("upload")}>Back</Button>
                            <Button
                                onClick={handleUpload}
                                disabled={!parseResult?.meta.validRows}
                                className="bg-blue-600 hover:bg-blue-700 text-white gap-2"
                            >
                                <Upload className="h-4 w-4" />
                                Import Questions
                            </Button>
                        </>
                    )}

                    {step === "result" && (
                        <Button onClick={handleClose}>Close</Button>
                    )}
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

"use client";

import { useState, useRef } from "react";
import { Upload, FileText, AlertCircle, X } from "lucide-react";
import { Button } from "@/components/ui/Button";

interface FileUploaderProps {
    onFileSelect: (file: File) => void;
    isLoading?: boolean;
}

export function FileUploader({ onFileSelect, isLoading }: FileUploaderProps) {
    const [isDragging, setIsDragging] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleDragEvent = (e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        if (e.type === "dragenter" || e.type === "dragover") {
            setIsDragging(true);
        } else if (e.type === "dragleave") {
            setIsDragging(false);
        }
    };

    const validateAndSelectFile = (file: File) => {
        setError(null);
        if (file.type !== "text/csv" && !file.name.endsWith(".csv")) {
            setError("Please upload a valid CSV file.");
            return;
        }
        onFileSelect(file);
    };

    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        setIsDragging(false);

        if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
            validateAndSelectFile(e.dataTransfer.files[0]);
        }
    };

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files.length > 0) {
            validateAndSelectFile(e.target.files[0]);
        }
    };

    return (
        <div className="w-full">
            <div
                className={`relative flex flex-col items-center justify-center w-full h-64 border-2 border-dashed rounded-lg cursor-pointer transition-colors
                ${isDragging ? "border-blue-500 bg-blue-50" : "border-slate-300 bg-slate-50 hover:bg-slate-100"}
                ${isLoading ? "opacity-50 pointer-events-none" : ""}`}
                onDragEnter={handleDragEvent}
                onDragOver={handleDragEvent}
                onDragLeave={handleDragEvent}
                onDrop={handleDrop}
                onClick={() => fileInputRef.current?.click()}
            >
                <div className="flex flex-col items-center justify-center pt-5 pb-6">
                    <div className="bg-blue-100 p-4 rounded-full mb-3">
                        <Upload className="w-8 h-8 text-blue-600" />
                    </div>
                    <p className="mb-2 text-sm text-slate-500">
                        <span className="font-semibold text-slate-700">Click to upload</span> or drag and drop
                    </p>
                    <p className="text-xs text-slate-500">CSV files only (Max 5MB)</p>
                </div>
                <input
                    ref={fileInputRef}
                    type="file"
                    className="hidden"
                    accept=".csv"
                    onChange={handleChange}
                />
            </div>

            {error && (
                <div className="mt-3 flex items-center gap-2 text-sm text-red-600 bg-red-50 p-2 rounded border border-red-200">
                    <AlertCircle className="h-4 w-4" />
                    {error}
                </div>
            )}

            <div className="mt-4 text-sm text-slate-500">
                <p className="font-medium mb-1">Expected CSV columns:</p>
                <code className="block bg-slate-100 p-2 rounded text-xs overflow-x-auto border border-slate-200">
                    questionText, optionA, optionB, optionC, optionD, correctAnswer, explanation, subjectTag, topicTag, difficulty, marks, negativeMarks, streams
                </code>
            </div>
        </div>
    );
}

import { ParseResult } from "@/utils/csvParser";
import { Question } from "@/types/admin";
import { AlertCircle, CheckCircle, AlertTriangle } from "lucide-react";

interface QuestionPreviewTableProps {
    parseResult: ParseResult;
}

export function QuestionPreviewTable({ parseResult }: QuestionPreviewTableProps) {
    const { rows, meta } = parseResult;

    return (
        <div className="space-y-4">
            {/* Stats Header */}
            <div className="flex gap-4 text-sm flex-wrap">
                <div className="flex items-center gap-2 text-slate-700 bg-slate-100 px-3 py-1 rounded-full border border-slate-200">
                    <span className="font-medium">Total: {meta.totalRows}</span>
                </div>
                <div className="flex items-center gap-2 text-green-600 bg-green-50 px-3 py-1 rounded-full border border-green-200">
                    <CheckCircle className="h-4 w-4" />
                    <span className="font-medium">{meta.validRows} Valid</span>
                </div>
                {meta.invalidRows > 0 && (
                    <div className="flex items-center gap-2 text-red-600 bg-red-50 px-3 py-1 rounded-full border border-red-200">
                        <AlertCircle className="h-4 w-4" />
                        <span className="font-medium">{meta.invalidRows} Errors</span>
                    </div>
                )}
            </div>

            <div className="border rounded-lg overflow-hidden">
                <div className="max-h-[400px] overflow-auto">
                    <table className="w-full text-left text-sm whitespace-nowrap">
                        <thead className="bg-slate-50 text-slate-500 font-medium sticky top-0 z-10 shadow-sm">
                            <tr>
                                <th className="px-4 py-3">Row</th>
                                <th className="px-4 py-3">Status</th>
                                <th className="px-4 py-3">Type</th>
                                <th className="px-4 py-3">Question/Passage</th>
                                <th className="px-4 py-3">Subject / Diff</th>
                                <th className="px-4 py-3">Details / Ans</th>
                                <th className="px-4 py-3">Marks</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {rows.length === 0 ? (
                                <tr>
                                    <td colSpan={7} className="px-4 py-8 text-center text-slate-500">
                                        No data to display.
                                    </td>
                                </tr>
                            ) : (
                                rows.map((row) => {
                                    const { data, valid, errors, row: rowNum } = row;
                                    const q = data;

                                    // eslint-disable-next-line @typescript-eslint/no-explicit-any
                                    const isDuplicate = (row as any).isDuplicate;

                                    let statusColor = "bg-green-50";
                                    let statusText = "Valid";
                                    let statusIcon = <CheckCircle className="h-3 w-3" />;

                                    if (!valid) {
                                        statusColor = "bg-red-50";
                                        statusText = "Error";
                                        statusIcon = <AlertCircle className="h-3 w-3" />;
                                    } else if (isDuplicate) {
                                        statusColor = "bg-amber-50";
                                        statusText = "Duplicate";
                                        statusIcon = <AlertTriangle className="h-3 w-3" />;
                                    }

                                    return (
                                        <tr key={rowNum} className={`hover:bg-slate-50 ${!valid ? 'bg-red-50/30' : ''} ${isDuplicate ? 'bg-amber-50/30' : ''}`}>
                                            <td className="px-4 py-2 text-slate-400 font-mono text-xs">{rowNum}</td>
                                            <td className="px-4 py-2">
                                                <div className="flex flex-col items-start gap-1">
                                                    <span className={`flex items-center gap-1 text-xs font-semibold px-2 py-0.5 rounded border ${!valid ? 'text-red-700 bg-red-100 border-red-200' :
                                                        isDuplicate ? 'text-amber-700 bg-amber-100 border-amber-200' :
                                                            'text-green-700 bg-green-100 border-green-200'
                                                        }`}>
                                                        {statusIcon} {statusText}
                                                    </span>
                                                    {errors.length > 0 && (
                                                        <span className="text-[10px] text-red-600 font-medium max-w-[200px] whitespace-normal">
                                                            {errors.join(", ")}
                                                        </span>
                                                    )}
                                                </div>
                                            </td>

                                            <td className="px-4 py-2">
                                                <span className={`px-2 py-0.5 rounded text-xs font-medium border ${q.questionType === 'match' ? 'bg-purple-50 text-purple-700 border-purple-200' :
                                                        q.questionType === 'passage' ? 'bg-blue-50 text-blue-700 border-blue-200' :
                                                            'bg-slate-100 text-slate-700 border-slate-200'
                                                    }`}>
                                                    {q.questionType?.toUpperCase() || 'MCQ'}
                                                </span>
                                            </td>

                                            <td className="px-4 py-2 max-w-[300px] truncate">
                                                <div className="flex flex-col">
                                                    <span title={q.text}>{q.text || <span className="text-slate-300 italic">Missing Text</span>}</span>
                                                    {q.questionType === 'passage' && (
                                                        <span className="text-xs text-blue-600 truncate mt-0.5" title={(q as any).passageText || q.passageId}>
                                                            Passage: {(q as any).passageText || q.passageId}
                                                        </span>
                                                    )}
                                                </div>
                                            </td>

                                            <td className="px-4 py-2">
                                                <div className="flex flex-col gap-1 items-start">
                                                    <span className="text-xs font-medium text-slate-700">{q.subject || "-"}</span>
                                                    <span className={`px-2 py-0.5 rounded text-[10px] border ${q.difficulty === "Easy" ? "bg-green-50 text-green-700 border-green-100" :
                                                        q.difficulty === "Hard" ? "bg-red-50 text-red-700 border-red-100" :
                                                            "bg-yellow-50 text-yellow-700 border-yellow-100"
                                                        }`}>
                                                        {q.difficulty || "Med"}
                                                    </span>
                                                </div>
                                            </td>

                                            <td className="px-4 py-2 font-mono text-xs">
                                                {q.questionType === 'match' ? (
                                                    <span className="text-purple-600 border border-purple-200 bg-purple-50 px-1 py-0.5 rounded">{q.matchPairs?.length || 0} Pairs</span>
                                                ) : q.correctOption !== -1 ? (
                                                    <span className="bg-slate-100 border border-slate-200 px-1.5 py-0.5 rounded">Ans: {["A", "B", "C", "D"][q.correctOption!]}</span>
                                                ) : <span className="text-red-400">-</span>}
                                            </td>

                                            <td className="px-4 py-2 text-xs">
                                                <span className="text-green-600">+{q.marks || 0}</span> / <span className="text-red-500">-{q.negativeMarks || 0}</span>
                                            </td>
                                        </tr>
                                    );
                                })
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
}

import React, { useState, useEffect } from "react";
import { Question } from "@/types/admin";
import { firestoreService } from "@/services/firestoreService";
import { Input } from "@/components/ui/Input";
import { Button } from "@/components/ui/Button";
import { AnimatePresence, motion } from "framer-motion";
import { X, Search, Filter, Loader2, Check, Plus, Library } from "lucide-react";

interface QuestionBankSidePanelProps {
    open: boolean;
    onClose: () => void;
    onAddQuestions: (questions: Question[]) => void;
    existingIds: string[];
}

export function QuestionBankSidePanel({ open, onClose, onAddQuestions, existingIds }: QuestionBankSidePanelProps) {
    const [questions, setQuestions] = useState<Question[]>([]);
    const [loading, setLoading] = useState(false);
    const [searchTerm, setSearchTerm] = useState("");
    const [selectedIds, setSelectedIds] = useState<string[]>([]);
    const [filterDifficulty, setFilterDifficulty] = useState<string>('all');
    const [filterSubject, setFilterSubject] = useState<string>('all');

    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        if (open && questions.length === 0) {
            loadQuestions();
        }
    }, [open]);

    async function loadQuestions() {
        setLoading(true);
        setError(null);
        try {
            console.log("QuestionBank: Loading questions...");
            const data = await firestoreService.getQuestions();
            setQuestions(data);
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
        } catch (err: any) {
            console.error("Failed to load questions", err);
            setError(err.message || "Failed to load questions. Check console or permissions.");
        } finally {
            setLoading(false);
        }
    }

    const filteredQuestions = questions.filter(q => {
        const matchesSearch = q.text.toLowerCase().includes(searchTerm.toLowerCase());
        const matchesDifficulty = filterDifficulty === 'all' || q.difficulty === filterDifficulty;
        const matchesSubject = filterSubject === 'all' || (q.subject || '').toLowerCase().includes(filterSubject.toLowerCase());
        const isAlreadyAdded = existingIds.includes(q.id);

        // Hide questions that are already in the test to prevent duplication
        return matchesSearch && matchesDifficulty && matchesSubject && !isAlreadyAdded;
    });

    const toggleSelection = (id: string) => {
        setSelectedIds(prev =>
            prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]
        );
    };

    const handleAddSelected = () => {
        const selectedQuestions = questions.filter(q => selectedIds.includes(q.id));
        onAddQuestions(selectedQuestions);
        setSelectedIds([]);
        onClose();
    };

    return (
        <AnimatePresence>
            {open && (
                <>
                    {/* Backdrop */}
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        onClick={onClose}
                        className="fixed inset-0 bg-black/40 backdrop-blur-sm z-50"
                    />
                    {/* Modal Container */}
                    <motion.div
                        initial={{ opacity: 0, scale: 0.95, y: 20 }}
                        animate={{ opacity: 1, scale: 1, y: 0 }}
                        exit={{ opacity: 0, scale: 0.95, y: 20 }}
                        transition={{ duration: 0.2 }}
                        className="fixed inset-4 md:inset-auto md:left-1/2 md:top-1/2 md:-translate-x-1/2 md:-translate-y-1/2 md:w-[800px] md:h-[600px] bg-surface-card rounded-2xl shadow-2xl z-50 flex flex-col overflow-hidden border border-border"
                    >
                        {/* Header */}
                        <div className="p-6 border-b border-border flex justify-between items-start bg-surface-elevated">
                            <div>
                                <div className="flex items-center gap-2 text-cta-primary mb-1">
                                    <Library className="h-5 w-5" />
                                    <span className="text-xs font-semibold uppercase tracking-wider">Question Bank</span>
                                </div>
                                <h2 className="text-xl font-bold text-text-primary">Add Questions from Bank</h2>
                                <p className="text-sm text-text-secondary mt-1">Select questions from your shared repository to add to this test.</p>
                            </div>
                            <button onClick={onClose} className="p-2 hover:bg-surface-elevated rounded-full transition-colors text-text-muted hover:text-text-primary">
                                <X className="h-5 w-5" />
                            </button>
                        </div>

                        {/* Filters & Search */}
                        <div className="p-4 border-b border-border flex gap-4 bg-surface-card items-center">
                            <div className="relative flex-1">
                                <Search className="absolute left-3 top-2.5 h-4 w-4 text-text-muted" />
                                <Input
                                    placeholder="Search question text..."
                                    className="pl-9 bg-background border-border"
                                    value={searchTerm}
                                    onChange={(e) => setSearchTerm(e.target.value)}
                                />
                            </div>
                            <select
                                className="px-3 py-2 bg-background border border-border rounded-md text-sm outline-none text-text-primary focus:border-cta-primary focus:ring-1 focus:ring-cta-primary"
                                value={filterDifficulty}
                                onChange={(e) => setFilterDifficulty(e.target.value)}
                            >
                                <option value="all">All Difficulties</option>
                                <option value="Easy">Easy</option>
                                <option value="Medium">Medium</option>
                                <option value="Hard">Hard</option>
                            </select>
                        </div>

                        {/* Question List */}
                        <div className="flex-1 overflow-y-auto p-4 space-y-3 bg-background">
                            {loading ? (
                                <div className="flex flex-col items-center justify-center h-full text-text-muted gap-2">
                                    <Loader2 className="h-8 w-8 animate-spin text-cta-primary" />
                                    <p>Loading questions...</p>
                                </div>
                            ) : error ? (
                                <div className="flex flex-col items-center justify-center h-full text-semantic-error gap-2 p-4 text-center">
                                    <div className="h-12 w-12 bg-semantic-error/10 rounded-full flex items-center justify-center mb-2">
                                        <X className="h-6 w-6 text-semantic-error" />
                                    </div>
                                    <p className="font-semibold">Error Loading Questions</p>
                                    <p className="text-sm text-text-secondary max-w-sm">{error}</p>
                                    <Button onClick={loadQuestions} variant="outline" size="sm" className="mt-4">
                                        Retry
                                    </Button>
                                </div>
                            ) : filteredQuestions.length === 0 ? (
                                <div className="flex flex-col items-center justify-center h-full text-text-muted gap-2">
                                    <Search className="h-8 w-8 text-border" />
                                    <p>No matching questions found.</p>
                                </div>
                            ) : (
                                <div className="grid gap-3">
                                    {filteredQuestions.map(q => {
                                        const isSelected = selectedIds.includes(q.id);
                                        return (
                                            <motion.div
                                                layout
                                                initial={{ opacity: 0, y: 10 }}
                                                animate={{ opacity: 1, y: 0 }}
                                                key={q.id}
                                                onClick={() => toggleSelection(q.id)}
                                                className={`
                                                    p-4 rounded-xl border cursor-pointer transition-all relative group
                                                    ${isSelected
                                                        ? 'bg-cta-primary/5 border-cta-primary shadow-sm'
                                                        : 'bg-surface-card border-border hover:border-cta-primary/50 hover:shadow-md'}
                                                `}
                                            >
                                                <div className="pr-12">
                                                    <p className="text-sm font-medium text-text-primary line-clamp-2 mb-2 group-hover:text-text-primary">{q.text}</p>
                                                    <div className="flex gap-2">
                                                        <span className={`text-[10px] px-2 py-0.5 rounded-full font-medium ${q.difficulty === 'Hard' ? 'bg-semantic-error/10 text-semantic-error border-semantic-error/30' :
                                                            q.difficulty === 'Easy' ? 'bg-semantic-success/10 text-semantic-success border-semantic-success/30' :
                                                                'bg-semantic-warning/10 text-semantic-warning border-semantic-warning/30'
                                                            }`}>
                                                            {q.difficulty || 'Medium'}
                                                        </span>
                                                        {q.subject && (
                                                            <span className="text-[10px] px-2 py-0.5 rounded-full bg-surface-base text-text-secondary border border-border">
                                                                {q.subject}
                                                            </span>
                                                        )}
                                                    </div>
                                                </div>

                                                <div className={`
                                                    absolute top-4 right-4 w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all duration-200
                                                    ${isSelected ? 'bg-cta-primary border-cta-primary scale-110' : 'border-border bg-background group-hover:border-cta-primary/50'}
                                                `}>
                                                    {isSelected && <Check className="h-3.5 w-3.5 text-white" strokeWidth={3} />}
                                                </div>
                                            </motion.div>
                                        );
                                    })}
                                </div>
                            )}
                        </div>

                        {/* Footer */}
                        <div className="p-4 bg-surface-card border-t border-border flex justify-between items-center z-10">
                            <div className="flex items-center gap-2 text-sm text-text-secondary">
                                <span className="font-semibold text-text-primary">{selectedIds.length}</span> questions selected
                            </div>
                            <div className="flex gap-3">
                                <Button variant="ghost" onClick={onClose}>Cancel</Button>
                                <Button
                                    onClick={handleAddSelected}
                                    disabled={selectedIds.length === 0}
                                    className="bg-cta-primary hover:bg-cta-hover text-white gap-2 px-6"
                                >
                                    <Plus className="h-4 w-4" /> Add Questions
                                </Button>
                            </div>
                        </div>
                    </motion.div>
                </>
            )}
        </AnimatePresence>
    );
}

import React, { useState } from "react";
import { Question, Passage } from "@/types/admin";
import { Input } from "@/components/ui/Input";
import { Button } from "@/components/ui/Button";
import { Trash2, GripVertical, Check, Copy, X, ChevronDown, ChevronUp } from "lucide-react";
import { Reorder, useDragControls } from "framer-motion";

interface UnifiedQuestionCardProps {
    question: Question;
    index?: number; // Optional if not in a list
    onChange: (updated: Question) => void;
    onDelete?: () => void;
    onDuplicate?: () => void;
    isExpanded: boolean;
    onToggleExpand: () => void;
    passages: Passage[]; // For passage selection
    isDragDisabled?: boolean; // True when rendered outside a reorder list
}

export function UnifiedQuestionCard({
    question,
    index,
    onChange,
    onDelete,
    onDuplicate,
    isExpanded,
    onToggleExpand,
    passages,
    isDragDisabled
}: UnifiedQuestionCardProps) {
    const dragControls = useDragControls();

    const [isCreatingPassage, setIsCreatingPassage] = useState(false);
    const [newPassageText, setNewPassageText] = useState("");

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const handleChange = (field: keyof Question, value: any) => {
        onChange({ ...question, [field]: value });
    };

    const handleOptionChange = (optIndex: number, text: string) => {
        const newOptions = [...(question.options || [])];
        newOptions[optIndex] = text;
        handleChange('options', newOptions);
    };

    const addOption = () => {
        handleChange('options', [...(question.options || []), ""]);
    };

    const removeOption = (optIndex: number) => {
        const newOptions = (question.options || []).filter((_, i) => i !== optIndex);
        handleChange('options', newOptions);
        if (question.correctOption === optIndex) {
            handleChange('correctOption', 0);
        } else if (question.correctOption > optIndex) {
            handleChange('correctOption', question.correctOption - 1);
        }
    };

    const handleNewPassageChange = (text: string) => {
        setNewPassageText(text);
        // Note: Actual passage creation needs to be handled on save by the parent
        // For inline editing, it's easier if we store a temporary prop or rely on parent
        handleChange('passageText' as any, text);
    };

    const cardContent = (
        <div className={`bg-surface-card rounded-xl shadow-sm border p-4 transition-all ${isExpanded ? 'border-cta-primary/50 ring-1 ring-cta-primary/20 z-50 relative' : 'border-border hover:border-cta-primary/30'} ${isDragDisabled ? 'w-full' : ''}`}>

            {/* Header/Summary View */}
            <div className="flex items-center gap-3">
                {!isDragDisabled && (
                    <div className="cursor-move text-text-muted hover:text-text-secondary p-1 touch-none" onPointerDown={(e) => dragControls.start(e)}>
                        <GripVertical className="h-5 w-5" />
                    </div>
                )}

                <div
                    className="flex-1 cursor-pointer flex items-center justify-between"
                    onClick={onToggleExpand}
                >
                    <div className="flex items-center gap-3 truncate">
                        {index !== undefined && <span className="text-xs font-bold text-text-muted bg-surface-elevated px-2 py-1 rounded">Q{index + 1}</span>}
                        <span className={`px-2 py-0.5 rounded text-[10px] font-medium border ${question.questionType === 'match' ? 'bg-purple-50 text-purple-700 border-purple-200' :
                                question.questionType === 'passage' ? 'bg-blue-50 text-blue-700 border-blue-200' :
                                    'bg-slate-100 text-slate-700 border-slate-200'
                            }`}>
                            {question.questionType?.toUpperCase() || 'MCQ'}
                        </span>
                        <span className="text-sm font-medium text-text-primary truncate max-w-[300px] md:max-w-[500px]">
                            {question.text || "New Empty Question"}
                        </span>
                    </div>

                    <div className="flex items-center gap-2">
                        <span className={`px-2 py-0.5 rounded text-[10px] border hidden sm:inline-block ${question.difficulty === "Easy" ? "bg-green-50 text-green-700 border-green-100" :
                            question.difficulty === "Hard" ? "bg-red-50 text-red-700 border-red-100" :
                                "bg-yellow-50 text-yellow-700 border-yellow-100"
                            }`}>
                            {question.difficulty || "Medium"}
                        </span>
                        {isExpanded ? <ChevronUp className="h-4 w-4 text-text-muted" /> : <ChevronDown className="h-4 w-4 text-text-muted" />}
                    </div>
                </div>

                {/* Quick Actions */}
                <div className="flex gap-1 ml-2">
                    {onDuplicate && (
                        <Button variant="ghost" size="sm" onClick={(e) => { e.stopPropagation(); onDuplicate(); }} title="Duplicate">
                            <Copy className="h-4 w-4 text-text-muted hover:text-cta-primary" />
                        </Button>
                    )}
                    {onDelete && (
                        <Button variant="ghost" size="sm" onClick={(e) => { e.stopPropagation(); onDelete(); }} title="Delete">
                            <Trash2 className="h-4 w-4 text-text-muted hover:text-semantic-error" />
                        </Button>
                    )}
                </div>
            </div>

            {/* Expanded Edit View */}
            {isExpanded && (
                <div className="mt-6 pl-0 sm:pl-8 space-y-6 animate-in fade-in slide-in-from-top-2 duration-200">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        <div className="md:col-span-2 space-y-4">

                            {/* Question Type Selection */}
                            <div>
                                <label className="block text-xs font-semibold text-text-secondary uppercase mb-1">Question Type</label>
                                <select
                                    className="w-full sm:w-1/2 px-3 py-2 bg-surface-base border border-border rounded-lg text-sm"
                                    value={question.questionType || "mcq"}
                                    onChange={(e) => handleChange('questionType', e.target.value)}
                                >
                                    <option value="mcq">Standard MCQ</option>
                                    <option value="match">Match the Following</option>
                                    <option value="passage">Passage-based</option>
                                </select>
                            </div>

                            {/* Passage Selection/Creation */}
                            {question.questionType === "passage" && (
                                <div className="p-4 bg-blue-50/50 border border-blue-100 rounded-lg space-y-4">
                                    <h4 className="font-medium text-blue-900 text-sm">Passage Configuration</h4>
                                    <div className="flex gap-4">
                                        <label className="flex items-center gap-2 text-sm text-text-secondary cursor-pointer">
                                            <input
                                                type="radio"
                                                checked={!isCreatingPassage}
                                                onChange={() => setIsCreatingPassage(false)}
                                                className="text-cta-primary focus:ring-cta-primary h-4 w-4"
                                            />
                                            Select Existing
                                        </label>
                                        <label className="flex items-center gap-2 text-sm text-text-secondary cursor-pointer">
                                            <input
                                                type="radio"
                                                checked={isCreatingPassage}
                                                onChange={() => setIsCreatingPassage(true)}
                                                className="text-cta-primary focus:ring-cta-primary h-4 w-4"
                                            />
                                            Create New
                                        </label>
                                    </div>

                                    {!isCreatingPassage ? (
                                        <select
                                            className="w-full px-3 py-2 bg-surface-card border border-border rounded-lg text-sm"
                                            value={question.passageId || ""}
                                            onChange={(e) => handleChange('passageId', e.target.value)}
                                        >
                                            <option value="">-- Select a Passage --</option>
                                            {passages.map(p => (
                                                <option key={p.id} value={p.id}>
                                                    {p.text.length > 80 ? p.text.substring(0, 80) + "..." : p.text}
                                                </option>
                                            ))}
                                        </select>
                                    ) : (
                                        <div>
                                            <textarea
                                                className="w-full px-3 py-2 bg-surface-card border border-border rounded-lg text-sm outline-none focus:ring-2 focus:ring-cta-primary min-h-[120px]"
                                                value={newPassageText || (question as any).passageText || ""}
                                                onChange={(e) => handleNewPassageChange(e.target.value)}
                                                placeholder="Enter passage text here. It will be created when you save."
                                            />
                                            <p className="text-[10px] text-text-muted mt-1">Note: The passage is created when the question/test is saved.</p>
                                        </div>
                                    )}
                                </div>
                            )}

                            {/* Question Text */}
                            <div>
                                <label className="block text-xs font-semibold text-text-secondary uppercase mb-1">
                                    {question.questionType === "passage" ? "Question Text related to Passage" : "Question Text"}
                                </label>
                                <textarea
                                    className="w-full px-3 py-2 bg-surface-base border border-border rounded-lg text-sm outline-none focus:ring-2 focus:ring-cta-primary transition-all min-h-[80px] resize-y"
                                    value={question.text}
                                    onChange={(e) => handleChange('text', e.target.value)}
                                    placeholder="Type the question here..."
                                />
                            </div>

                            {/* Match Pairs Builder */}
                            {question.questionType === "match" && (
                                <div className="p-4 bg-surface-elevated border border-border rounded-lg space-y-4">
                                    <h4 className="font-medium text-text-primary text-sm flex items-center justify-between">
                                        Match Pairs
                                        <Button
                                            variant="ghost"
                                            size="sm"
                                            className="h-6 text-xs"
                                            onClick={() => {
                                                const newPairs = [...(question.matchPairs || [])];
                                                newPairs.push({ left: "", right: "" });
                                                handleChange('matchPairs', newPairs);
                                            }}
                                        >
                                            + Add Pair
                                        </Button>
                                    </h4>
                                    <div className="space-y-2">
                                        {(question.matchPairs || []).map((pair, idx) => (
                                            <div key={idx} className="flex items-center gap-2">
                                                <span className="text-xs font-bold text-text-muted w-6 text-center">{String.fromCharCode(65 + idx)}.</span>
                                                <Input
                                                    className="h-8 text-sm"
                                                    value={pair.left}
                                                    onChange={(e) => {
                                                        const newPairs = [...(question.matchPairs || [])];
                                                        newPairs[idx].left = e.target.value;
                                                        handleChange('matchPairs', newPairs);
                                                    }}
                                                    placeholder="List I Item"
                                                />
                                                <span className="text-xs font-bold text-text-muted w-6 text-center text-red">{"= "}</span>
                                                <Input
                                                    className="h-8 text-sm"
                                                    value={pair.right}
                                                    onChange={(e) => {
                                                        const newPairs = [...(question.matchPairs || [])];
                                                        newPairs[idx].right = e.target.value;
                                                        handleChange('matchPairs', newPairs);
                                                    }}
                                                    placeholder="List II Item"
                                                />
                                                {(question.matchPairs || []).length > 2 && (
                                                    <button
                                                        onClick={() => {
                                                            const newPairs = (question.matchPairs || []).filter((_, i) => i !== idx);
                                                            handleChange('matchPairs', newPairs);
                                                        }}
                                                        className="text-text-muted hover:text-semantic-error p-1"
                                                    >
                                                        <X className="h-4 w-4" />
                                                    </button>
                                                )}
                                            </div>
                                        ))}
                                    </div>
                                    <p className="text-xs text-text-muted">Fill the options below with standard codes like A-I, B-II, C-III...</p>
                                </div>
                            )}

                            {/* Options */}
                            <div className="space-y-2">
                                <label className="block text-xs font-semibold text-text-secondary uppercase mb-1">Answers</label>
                                {(question.options || []).map((opt, i) => (
                                    <div key={i} className="flex items-center gap-3">
                                        <div
                                            className={`
                                                w-5 h-5 rounded-full border flex items-center justify-center cursor-pointer flex-shrink-0 transition-colors
                                                ${question.correctOption === i ? 'bg-semantic-success border-semantic-success text-white' : 'border-border hover:border-border-strong'}
                                            `}
                                            onClick={() => handleChange('correctOption', i)}
                                            title="Mark as correct"
                                        >
                                            {question.correctOption === i && <Check className="h-3 w-3" />}
                                        </div>
                                        <Input
                                            value={opt}
                                            onChange={(e) => handleOptionChange(i, e.target.value)}
                                            placeholder={`Option ${i + 1}`}
                                            className={`flex-1 h-9 ${question.correctOption === i ? 'bg-semantic-success/10 border-semantic-success/30' : ''}`}
                                        />
                                        {(question.options || []).length > 2 && (
                                            <button
                                                onClick={() => removeOption(i)}
                                                className="text-text-muted hover:text-semantic-error p-1"
                                            >
                                                <X className="h-4 w-4" />
                                            </button>
                                        )}
                                    </div>
                                ))}
                                {(question.options || []).length < 6 && (
                                    <div className="flex items-center gap-3">
                                        <button
                                            onClick={addOption}
                                            className="text-xs text-cta-primary hover:text-cta-hover font-medium py-1 px-2 hover:bg-cta-primary/10 rounded mt-1"
                                        >
                                            + Add Option
                                        </button>
                                    </div>
                                )}
                            </div>
                        </div>

                        {/* Right Column: Meta */}
                        <div className="bg-surface-base p-4 rounded-lg border border-border h-fit space-y-4">
                            <div>
                                <label className="block text-xs font-semibold text-text-secondary uppercase mb-1">Explanation</label>
                                <textarea
                                    className="w-full px-3 py-2 bg-surface-card border border-border rounded-lg text-xs outline-none focus:ring-1 focus:ring-cta-primary min-h-[100px] resize-y"
                                    value={question.explanation || ""}
                                    onChange={(e) => handleChange('explanation', e.target.value)}
                                    placeholder="Explain the correct answer..."
                                />
                            </div>

                            <hr className="border-border" />

                            <div>
                                <label className="block text-xs font-semibold text-text-secondary uppercase mb-1">Difficulty</label>
                                <select
                                    className="w-full px-2 py-1.5 bg-surface-card border border-border rounded text-sm outline-none focus:ring-1 focus:ring-cta-primary"
                                    value={question.difficulty || "Medium"}
                                    onChange={(e) => handleChange('difficulty', e.target.value)}
                                >
                                    <option value="Easy">Easy</option>
                                    <option value="Medium">Medium</option>
                                    <option value="Hard">Hard</option>
                                </select>
                            </div>
                            <div>
                                <label className="block text-xs font-semibold text-text-secondary uppercase mb-1">Stream</label>
                                <select
                                    className="w-full px-2 py-1.5 bg-surface-card border border-border rounded text-sm outline-none focus:ring-1 focus:ring-cta-primary"
                                    value={question.stream || "General"}
                                    onChange={(e) => handleChange('stream', e.target.value)}
                                >
                                    <option value="General">General</option>
                                    <option value="Science">Science</option>
                                    <option value="Commerce">Commerce</option>
                                    <option value="Humanities">Humanities</option>
                                    <option value="English">English</option>
                                </select>
                            </div>
                            <div>
                                <label className="block text-xs font-semibold text-text-secondary uppercase mb-1">Category (Subject)</label>
                                <Input
                                    className="h-8 text-sm bg-surface-card focus:bg-background"
                                    value={question.subject || ""}
                                    onChange={(e) => handleChange('subject', e.target.value)}
                                    placeholder="e.g. Physics"
                                />
                            </div>
                            <div className="grid grid-cols-2 gap-2">
                                <div>
                                    <label className="block text-[10px] font-semibold text-text-secondary uppercase mb-1">Marks (+)</label>
                                    <Input
                                        type="number"
                                        className="h-8 text-sm"
                                        value={question.marks || 5}
                                        onChange={(e) => handleChange('marks', Number(e.target.value))}
                                    />
                                </div>
                                <div>
                                    <label className="block text-[10px] font-semibold text-text-secondary uppercase mb-1">Negative (-)</label>
                                    <Input
                                        type="number"
                                        className="h-8 text-sm"
                                        value={question.negativeMarks || 1}
                                        onChange={(e) => handleChange('negativeMarks', Number(e.target.value))}
                                    />
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );

    if (isDragDisabled) {
        return cardContent;
    }

    return (
        <Reorder.Item value={question} id={question.id} dragListener={false} dragControls={dragControls} className="relative z-0 group">
            {/* The blurry overlay that appears behind everything else when THIS card is expanded, targeting sibling dimming */}
            {isExpanded && (
                <div className="fixed inset-0 bg-background/40 backdrop-blur-sm z-40 transition-all pointer-events-auto" onClick={onToggleExpand}></div>
            )}
            <div className={`relative ${isExpanded ? 'z-50' : 'z-10'}`}>
                {cardContent}
            </div>
        </Reorder.Item>
    );
}

