"use client";

import { useTheme } from "@/components/ui/ThemeProvider";
import { Sun, Moon } from "lucide-react";
import { useEffect, useState } from "react";

export function ThemeToggle() {
    const { theme, setTheme } = useTheme();
    const [mounted, setMounted] = useState(false);

    useEffect(() => {
        setMounted(true);
    }, []);

    if (!mounted) {
        return <div className="h-8 w-8" />; // Placeholder to avoid layout shift
    }

    const isDark = theme === 'dark' || (theme === 'system' && typeof window !== 'undefined' && window.matchMedia('(prefers-color-scheme: dark)').matches);

    return (
        <button
            onClick={() => setTheme(isDark ? 'light' : 'dark')}
            className="p-2 rounded-md hover:bg-surface-elevated text-text-secondary hover:text-text-primary transition-colors flex items-center justify-center"
            title="Toggle theme"
        >
            {isDark ? <Sun className="h-[1.2rem] w-[1.2rem]" /> : <Moon className="h-[1.2rem] w-[1.2rem]" />}
        </button>
    );
}

"use client";

import { createContext, useContext, useEffect, useState, ReactNode } from "react";
import {
    User,
    onAuthStateChanged,
    signInWithEmailAndPassword,
    createUserWithEmailAndPassword,
    signOut,
    GoogleAuthProvider,
    signInWithPopup
} from "firebase/auth";
import { doc, getDoc, setDoc, Timestamp, onSnapshot } from "firebase/firestore";
import { auth, db } from "@/lib/firebase/config";

// Define the shape of the user data stored in Firestore
export interface UserData {
    uid: string;
    email: string;
    name: string;
    role: "student" | "admin" | "developer"; // Default is student
    createdAt: Timestamp;
    lastLoginAt: Timestamp;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    purchasedTests: Record<string, any>; // Map for purchased tests
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    performanceSummary: Record<string, any>; // Map for performance summary
    stream?: 'Science' | 'Commerce' | 'Humanities';
    targetUniversity?: string;
    onboardingCompleted?: boolean;
}

interface AuthContextType {
    user: User | null;
    userData: UserData | null;
    loading: boolean;
    login: (email: string, password: string) => Promise<void>;
    signup: (email: string, password: string, name: string) => Promise<void>;
    loginWithGoogle: () => Promise<void>;
    logout: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: ReactNode }) {
    const [user, setUser] = useState<User | null>(null);
    const [userData, setUserData] = useState<UserData | null>(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        let unsubscribeSnapshot: () => void;

        const unsubscribeAuth = onAuthStateChanged(auth, async (currentUser) => {
            if (currentUser) {
                setUser(currentUser);
                // Don't set loading to false yet; wait for Firestore data

                // Set up real-time listener immediately when user is detected
                const userDocRef = doc(db, "users", currentUser.uid);
                unsubscribeSnapshot = onSnapshot(userDocRef, (docSnap) => {
                    if (docSnap.exists()) {
                        const data = docSnap.data() as UserData;
                        setUserData(data);
                    } else {
                        console.warn("User authenticated but no Firestore document found.");
                        setUserData(null);
                    }
                    // Data is loaded (or not found), so we can stop loading
                    setLoading(false);
                }, (error) => {
                    console.error("Error fetching user data:", error);
                    setLoading(false);
                });

            } else {
                setUser(null);
                setUserData(null);
                if (unsubscribeSnapshot) {
                    unsubscribeSnapshot();
                }
                setLoading(false);
            }
        });

        return () => {
            unsubscribeAuth();
            if (unsubscribeSnapshot) {
                unsubscribeSnapshot();
            }
        };
    }, []);

    // Independent One-time update for lastLogin (optional, can be skipped for now to strictly fix the issue)
    useEffect(() => {
        if (user) {
            const userDocRef = doc(db, "users", user.uid);
            // Fire and forget update
            setDoc(userDocRef, { lastLoginAt: Timestamp.now() }, { merge: true }).catch(console.error);
        }
    }, [user?.uid]); // Only run when UID changes (login)


    const signup = async (email: string, password: string, name: string) => {
        const userCredential = await createUserWithEmailAndPassword(auth, email, password);
        const user = userCredential.user;

        // Create user document in Firestore
        const newUser: UserData = {
            uid: user.uid,
            email: user.email!,
            name: name,
            role: "student",
            createdAt: Timestamp.now(),
            lastLoginAt: Timestamp.now(),
            purchasedTests: {},
            performanceSummary: {}
        };

        await setDoc(doc(db, "users", user.uid), newUser);
        setUserData(newUser);
    };

    const login = async (email: string, password: string) => {
        await signInWithEmailAndPassword(auth, email, password);
        // onAuthStateChanged will handle fetching user data
    };

    const loginWithGoogle = async () => {
        const provider = new GoogleAuthProvider();
        const result = await signInWithPopup(auth, provider);
        const user = result.user;

        // Check if user document exists
        const userDocRef = doc(db, "users", user.uid);
        const userDoc = await getDoc(userDocRef);

        if (!userDoc.exists()) {
            // Create new user document for Google Sign In
            const newUser: UserData = {
                uid: user.uid,
                email: user.email!,
                name: user.displayName || "User",
                role: "student",
                createdAt: Timestamp.now(),
                lastLoginAt: Timestamp.now(),
                purchasedTests: {},
                performanceSummary: {}
            };
            await setDoc(userDocRef, newUser);
            setUserData(newUser);
        } else {
            // onAuthStateChanged handles fetching, but we can set it here optimistically or just let the effect do it
        }
    };

    const logout = async () => {
        await signOut(auth);
        setUser(null);
        setUserData(null);
    };

    return (
        <AuthContext.Provider value={{ user, userData, loading, login, signup, loginWithGoogle, logout }}>
            {children}
        </AuthContext.Provider>
    );
}

export function useAuth() {
    const context = useContext(AuthContext);
    if (context === undefined) {
        throw new Error("useAuth must be used within an AuthProvider");
    }
    return context;
}

import { useState, useEffect, useRef, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '@/context/AuthContext';
import { firestoreService } from '@/services/firestoreService';
import { Test, Question, QuestionStatus, TestAttempt, TestResult, Passage } from '@/types/admin';

export function useTestEngine(testId: string) {
    const router = useRouter();
    const { user } = useAuth();

    // Core State
    const [test, setTest] = useState<Test | null>(null);
    const [questions, setQuestions] = useState<Question[]>([]);
    const [passages, setPassages] = useState<Record<string, Passage>>({});
    const [currentQIndex, setCurrentQIndex] = useState(0);
    const [answers, setAnswers] = useState<Record<string, number>>({});
    const [questionStatus, setQuestionStatus] = useState<Record<string, QuestionStatus>>({});
    const [timeRemaining, setTimeRemaining] = useState(0);
    const [isTestStarted, setIsTestStarted] = useState(false);
    const [loading, setLoading] = useState(true);
    const [attemptId, setAttemptId] = useState<string | null>(null);
    const [startTime, setStartTime] = useState<string | null>(null);

    // Integrity State
    const [tabSwitches, setTabSwitches] = useState(0);
    const [showTabWarning, setShowTabWarning] = useState(false);

    // Refs for intervals and safe state access
    const timerRef = useRef<NodeJS.Timeout | null>(null);
    const syncRef = useRef<NodeJS.Timeout | null>(null);
    const stateRef = useRef({
        answers,
        questionStatus,
        timeRemaining,
        currentQIndex,
        attemptId,
        status: 'in_progress',
        tabSwitches
    });

    // Sync stateRef
    useEffect(() => {
        stateRef.current = {
            answers,
            questionStatus,
            timeRemaining,
            currentQIndex,
            attemptId,
            status: isTestStarted ? 'in_progress' : 'idle',
            tabSwitches
        };
    }, [answers, questionStatus, timeRemaining, currentQIndex, attemptId, isTestStarted, tabSwitches]);

    // --- Integrity: Tab Switching & Visibility ---
    useEffect(() => {
        if (!isTestStarted) return;

        const handleVisibilityChange = () => {
            if (document.hidden) {
                incrementTabSwitch();
            }
        };

        const incrementTabSwitch = () => {
            setTabSwitches(prev => {
                const newVal = prev + 1;
                if (newVal > 0) setShowTabWarning(true);
                return newVal;
            });
        };

        document.addEventListener('visibilitychange', handleVisibilityChange);

        return () => {
            document.removeEventListener('visibilitychange', handleVisibilityChange);
        };
    }, [isTestStarted]);

    // --- Integrity: Navigation Guard (BeforeUnload) ---
    useEffect(() => {
        if (!isTestStarted) return;

        const handleBeforeUnload = (e: BeforeUnloadEvent) => {
            e.preventDefault();
            e.returnValue = ''; // Standard browser dialog trigger
            return '';
        };

        window.addEventListener('beforeunload', handleBeforeUnload);
        return () => window.removeEventListener('beforeunload', handleBeforeUnload);
    }, [isTestStarted]);

    // --- Initialization ---
    useEffect(() => {
        async function init() {
            if (!testId || !user) return;

            try {
                // 1. Fetch Test Details
                const allTests = await firestoreService.getTests(true);
                const foundTest = allTests.find(t => t.id === testId);

                if (foundTest) {
                    setTest(foundTest);
                    let qs: Question[] = [];
                    if (foundTest.questionIds && foundTest.questionIds.length > 0) {
                        qs = await firestoreService.getQuestions({ ids: foundTest.questionIds! });
                    } else {
                        qs = await firestoreService.getQuestions({ testId });
                    }
                    setQuestions(qs);

                    // Fetch associated passages
                    const passageIds = Array.from(new Set(qs.filter(q => q.passageId).map(q => q.passageId as string)));
                    if (passageIds.length > 0) {
                        const fetchedPassages: Record<string, Passage> = {};
                        await Promise.all(passageIds.map(async id => {
                            const p = await firestoreService.getPassage(id);
                            if (p) fetchedPassages[id] = p;
                        }));
                        setPassages(fetchedPassages);
                    }

                    // 2. Recovery & Shuffling Logic
                    const savedSession = localStorage.getItem(`test_session_${testId}_${user.uid}`);
                    let orderedQs = [...qs];

                    if (savedSession) {
                        const session = JSON.parse(savedSession);
                        if (session.status === 'submitted' || session.status === 'completed') {
                            router.replace(`/analysis/${testId}`);
                            return;
                        }

                        // Restore specific order if it was shuffled
                        if (session.shuffledQuestionIds && Array.isArray(session.shuffledQuestionIds)) {
                            const idMap = new Map(qs.map(q => [q.id, q]));
                            orderedQs = session.shuffledQuestionIds.map((id: string) => idMap.get(id)).filter(Boolean) as Question[];
                        }

                        setAnswers(session.answers || {});
                        setQuestionStatus(session.questionStatus || {});
                        setCurrentQIndex(session.currentQIndex || 0);
                        setAttemptId(session.attemptId);
                        setStartTime(session.startTime);
                        setTabSwitches(session.tabSwitches || 0);

                        // Calculate Time Remaining based on Server Start Time
                        if (session.startTime) {
                            const start = new Date(session.startTime).getTime();
                            const now = Date.now();
                            const elapsedSeconds = Math.floor((now - start) / 1000);
                            const totalSeconds = foundTest.duration * 60;
                            const remaining = Math.max(0, totalSeconds - elapsedSeconds);
                            setTimeRemaining(remaining);

                            if (remaining > 0) {
                                setIsTestStarted(true);
                                startTick(start, totalSeconds);
                            } else {
                                setTimeRemaining(0);
                                setIsTestStarted(true);
                            }
                        }
                    } else if (foundTest.shuffleQuestions) {
                        // Fresh start, shuffle questions if requested
                        for (let i = orderedQs.length - 1; i > 0; i--) {
                            const j = Math.floor(Math.random() * (i + 1));
                            [orderedQs[i], orderedQs[j]] = [orderedQs[j], orderedQs[i]];
                        }
                    }

                    setQuestions(orderedQs);
                }
            } catch (err) {
                console.error("Test Init Error:", err);
            } finally {
                setLoading(false);
            }
        }
        init();

        return () => {
            stopTimers();
        };
    }, [testId, user]);

    const stopTimers = () => {
        if (timerRef.current) clearInterval(timerRef.current);
        if (syncRef.current) clearInterval(syncRef.current);
    };

    // --- Timer Logic (Server Time Based) ---
    const startTick = useCallback((startTimestamp: number, totalDurationSeconds: number) => {
        if (timerRef.current) clearInterval(timerRef.current);

        timerRef.current = setInterval(() => {
            const now = Date.now();
            const elapsed = Math.floor((now - startTimestamp) / 1000);
            const remaining = Math.max(0, totalDurationSeconds - elapsed);

            setTimeRemaining(remaining);

            if (remaining <= 0) {
                clearInterval(timerRef.current!);
                handleAutoSubmit();
            }
        }, 1000);

        // Auto-Sync to Firestore every 30s
        if (syncRef.current) clearInterval(syncRef.current);
        syncRef.current = setInterval(() => {
            syncToFirestore();
        }, 30000);

    }, []);

    // --- Hybrid Sync ---
    // 1. Local Storage (Instant)
    const saveLocal = useCallback(() => {
        if (!user || !testId || !stateRef.current.attemptId) return;

        const session = {
            testId,
            userId: user.uid,
            ...stateRef.current,
            startTime,
            lastUpdated: Date.now(),
            shuffledQuestionIds: questions.map(q => q.id)
        };
        localStorage.setItem(`test_session_${testId}_${user.uid}`, JSON.stringify(session));
    }, [testId, user, startTime, questions]);

    // 2. Firestore Sync (Periodic)
    const syncToFirestore = async () => {
        const current = stateRef.current;
        if (!current.attemptId) return;

        // console.log("Syncing progress to Firestore...");
        await firestoreService.updateTestAttempt(current.attemptId, {
            answers: current.answers,
            questionStatus: current.questionStatus,
            timeRemaining: current.timeRemaining,
            currentQuestionIndex: current.currentQIndex,
            tabSwitches: current.tabSwitches
        });
    };

    // --- Actions ---
    const requestFullScreen = () => {
        const elem = document.documentElement as HTMLElement & {
            webkitRequestFullscreen?: () => Promise<void>;
            msRequestFullscreen?: () => Promise<void>;
        };
        if (elem.requestFullscreen) {
            elem.requestFullscreen().catch((err: unknown) => console.log(err));
        } else if (elem.webkitRequestFullscreen) { /* Safari */
            elem.webkitRequestFullscreen();
        } else if (elem.msRequestFullscreen) { /* IE11 */
            elem.msRequestFullscreen();
        }
    };

    const startTest = async () => {
        if (!test || !user) return;
        setLoading(true);

        const activeAttemptId = await firestoreService.startTestAttempt(user.uid, test.id, test.duration);

        if (activeAttemptId) {
            setAttemptId(activeAttemptId);
            const now = new Date().toISOString();
            setStartTime(now);

            const totalSeconds = test.duration * 60;
            setTimeRemaining(totalSeconds);
            setIsTestStarted(true);

            // Try Full Screen
            requestFullScreen();

            const initialStatus = { ...questionStatus };
            if (Object.keys(initialStatus).length === 0) {
                questions.forEach(q => {
                    initialStatus[q.id] = { questionId: q.id, status: 'not_visited', visited: false };
                });
                setQuestionStatus(initialStatus);
            }

            startTick(Date.now(), totalSeconds);

            localStorage.setItem(`test_session_${testId}_${user.uid}`, JSON.stringify({
                testId,
                userId: user.uid,
                attemptId: activeAttemptId,
                startTime: now,
                answers: {},
                questionStatus: initialStatus,
                timeRemaining: totalSeconds,
                status: 'in_progress',
                tabSwitches: 0,
                shuffledQuestionIds: questions.map(q => q.id)
            }));
        }
        setLoading(false);
    };


    // --- NTA Status Logic ---

    // 1. Auto-mark "not_answered" when visiting a "not_visited" question
    useEffect(() => {
        if (!isTestStarted || questions.length === 0) return;
        const currentQ = questions[currentQIndex];
        if (!currentQ) return;

        const qId = currentQ.id;
        setQuestionStatus(prev => {
            const currentStat = prev[qId]?.status;
            // Only update if currently 'not_visited'
            if (currentStat === 'not_visited') {
                return {
                    ...prev,
                    [qId]: { ...prev[qId], status: 'not_answered', visited: true }
                };
            }
            return prev;
        });
    }, [currentQIndex, isTestStarted, questions]);

    const handleOptionSelect = (optionIdx: number) => {
        const qId = questions[currentQIndex].id;
        setAnswers(prev => ({ ...prev, [qId]: optionIdx }));
        // NTA: Selecting an option makes it "Answered" (Green)
        updateStatus(qId, 'answered');
    };

    const updateStatus = (qId: string, statusType: QuestionStatus['status']) => {
        setQuestionStatus(prev => ({
            ...prev,
            [qId]: { ...prev[qId], status: statusType, visited: true }
        }));
    };

    // Effect to save local
    useEffect(() => {
        if (isTestStarted) saveLocal();
    }, [answers, questionStatus, currentQIndex, isTestStarted, tabSwitches, saveLocal]);


    const handleNext = () => {
        if (currentQIndex < questions.length - 1) {
            setCurrentQIndex(prev => prev + 1);
        }
    };

    const handlePrev = () => {
        if (currentQIndex > 0) {
            setCurrentQIndex(prev => prev - 1);
        }
    };

    const handleJump = (index: number) => {
        setCurrentQIndex(index);
    };

    const handleMarkForReview = () => {
        const qId = questions[currentQIndex].id;
        const isAnswered = answers[qId] !== undefined;
        // NTA: If answered -> "Answered & Marked for Review" (Purple with Green dot)
        //      If not answered -> "Marked for Review" (Purple)
        updateStatus(qId, isAnswered ? 'answered_marked_for_review' : 'marked_for_review');
        handleNext(); // Usually moves to next
    };

    const handleClearResponse = () => {
        const qId = questions[currentQIndex].id;
        const newAnswers = { ...answers };
        delete newAnswers[qId];
        setAnswers(newAnswers);
        // NTA: Clearing response reverts to "Not Answered" (Red)
        updateStatus(qId, 'not_answered');
    };

    // Robust Submit
    const [isSubmitting, setIsSubmitting] = useState(false);

    const performSubmission = async () => {
        if (isSubmitting || !attemptId || !test) return;
        setIsSubmitting(true);
        stopTimers();

        const current = stateRef.current;

        // Calculate Score
        let score = 0;
        let correct = 0;
        let incorrect = 0;
        let unanswered = 0;

        questions.forEach(q => {
            const ans = current.answers[q.id];
            if (ans === undefined) {
                unanswered++;
            } else if (ans === q.correctOption) {
                score += 5;
                correct++;
            } else {
                score -= 1;
                incorrect++;
            }
        });

        const resultData: Omit<TestResult, 'id'> = {
            attemptId,
            userId: user!.uid,
            testId: test.id,
            score,
            totalQuestions: questions.length,
            correctAnswers: correct,
            incorrectAnswers: incorrect,
            unanswered,
            accuracy: (correct / (correct + incorrect) * 100) || 0,
            timeTaken: (test.duration * 60) - current.timeRemaining,
            completedAt: new Date().toISOString()
        };

        // --- Improvement Logic ---
        try {
            // Fetch the LAST completed attempt for this test (before this current one)
            const previousAttempt = await firestoreService.getLastTestAttempt(user!.uid, test.id);
            if (previousAttempt && previousAttempt.resultData) {
                const prev = previousAttempt.resultData;

                // Normalize previous accuracy if it was stored as 0-1 (legacy bug)
                const prevAccuracy = prev.accuracy <= 1 ? prev.accuracy * 100 : prev.accuracy;

                resultData.improvement = {
                    scoreDiff: resultData.score - prev.score,
                    accuracyDiff: resultData.accuracy - prevAccuracy,
                    timeDiff: prev.timeTaken - resultData.timeTaken // Positive means we were FASTER
                };
            }
        } catch (err) {
            console.error("Error calculating improvement:", err);
            // Non-critical, continue submission
        }

        const success = await firestoreService.submitTestAttempt(
            attemptId,
            resultData,
            current.answers,
            current.questionStatus
        );

        if (success) {
            localStorage.setItem(`test_session_${testId}_${user!.uid}`, JSON.stringify({
                ...current,
                status: 'submitted'
            }));

            // Exit Full Screen if active
            if (document.fullscreenElement) {
                document.exitFullscreen().catch(err => console.log(err));
            }

            router.replace(`/analysis/${testId}`);
        } else {
            alert("Submission failed. Please check connection and try again.");
            setIsSubmitting(false);
        }
    };

    const handleAutoSubmit = () => {
        performSubmission();
    };

    const integrityHandlers = {
        onContextMenu: (e: React.MouseEvent) => {
            if (isTestStarted) e.preventDefault();
        },
        onCopy: (e: React.ClipboardEvent) => {
            if (isTestStarted) {
                e.preventDefault();
                alert("Copying is disabled during the exam.");
            }
        },
        onCut: (e: React.ClipboardEvent) => {
            if (isTestStarted) e.preventDefault();
        },
        onPaste: (e: React.ClipboardEvent) => {
            // Optional: allow pasting? Typically blocked.
            if (isTestStarted) e.preventDefault();
        }
    };

    // --- Expose ---
    return {
        test,
        questions,
        passages,
        currentQIndex,
        currentQuestion: questions[currentQIndex],
        answers,
        questionStatus,
        timeRemaining,
        isTestStarted,
        loading,
        integrity: {
            tabSwitches,
            showTabWarning,
            dismissTabWarning: () => setShowTabWarning(false),
            handlers: integrityHandlers
        },
        actions: {
            startTest,
            handleOptionSelect,
            handleNext,
            handlePrev,
            handleJump,
            handleMarkForReview,
            handleClearResponse,
            submitTest: performSubmission
        }
    };
}

import {
    collection,
    getDocs,
    getDoc,
    doc,
    updateDoc,
    query,
    orderBy,
    Timestamp,
    addDoc,
    deleteDoc,
    where,
    limit,
    documentId,
    getCountFromServer,
    QueryConstraint,
    arrayUnion,
    writeBatch
} from "firebase/firestore";
import { db } from "@/lib/firebase/config";
import { User, Test, Question, CMSContent, SiteSettings, AuditLog, DashboardStats, Transaction, TestAttempt, TestResult, Bundle, Passage } from "@/types/admin";
import { UserData } from "@/context/AuthContext";

// Helper to remove undefined fields recursively
// eslint-disable-next-line @typescript-eslint/no-explicit-any
function cleanData(data: any): any {
    if (data === null || data === undefined) return null;
    if (typeof data !== 'object') return data;
    if (data instanceof Date) return data;
    if (data.toMillis && typeof data.toMillis === 'function') return data; // Timestamp

    if (Array.isArray(data)) {
        return data.map(item => cleanData(item)).filter(item => item !== undefined);
    }

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const cleaned: any = {};
    for (const key in data) {
        if (data[key] !== undefined) {
            cleaned[key] = cleanData(data[key]);
        }
    }
    return cleaned;
}

export const firestoreService = {
    // --- Test Engine ---
    async startTestAttempt(userId: string, testId: string, durationMinutes: number): Promise<string | null> {
        try {
            const attemptsRef = collection(db, "testAttempts");

            // Check if there's an active attempt first?
            const q = query(
                attemptsRef,
                where("userId", "==", userId),
                where("testId", "==", testId),
                where("status", "==", "in_progress")
            );
            const snapshot = await getDocs(q);

            if (!snapshot.empty) {
                console.log("Resuming existing attempt:", snapshot.docs[0].id);
                return snapshot.docs[0].id;
            }

            const newAttempt: Omit<TestAttempt, 'id'> = {
                userId,
                testId,
                startTime: new Date().toISOString(),
                answers: {},
                timeRemaining: durationMinutes * 60,
                status: 'in_progress',
                currentQuestionIndex: 0,
                questionStatus: {}
            };

            const docRef = await addDoc(attemptsRef, newAttempt);
            return docRef.id;
        } catch (error) {
            console.error("Error starting test attempt:", error);
            return null;
        }
    },

    async updateTestAttempt(attemptId: string, data: Partial<TestAttempt>): Promise<boolean> {
        try {
            const attemptRef = doc(db, "testAttempts", attemptId);
            await updateDoc(attemptRef, data);
            return true;
        } catch (error) {
            console.error("Error updating test attempt:", error);
            return false;
        }
    },

    async submitTestAttempt(
        attemptId: string,
        resultData: Omit<TestResult, 'id'>,
        finalAnswers?: Record<string, number>,
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        finalStatus?: Record<string, any>
    ): Promise<boolean> {
        try {
            const attemptRef = doc(db, "testAttempts", attemptId);

            // We update the attempt with the final score, status, AND the final answers/state
            // This ensures that even if the periodic sync missed the last few seconds, we have the latest data.
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const updatePayload: any = {
                status: 'completed',
                endTime: new Date().toISOString(),
                score: resultData.score,
                timeTaken: resultData.timeTaken,
                resultData: resultData
            };

            if (finalAnswers) updatePayload.answers = finalAnswers;
            if (finalStatus) updatePayload.questionStatus = finalStatus;

            await updateDoc(attemptRef, updatePayload);

            return true;
        } catch (error) {
            console.error("Error submitting test:", error);
            return false;
        }
    },

    async getTestAttempt(attemptId: string): Promise<TestAttempt | null> {
        try {
            const docRef = doc(db, "testAttempts", attemptId);
            const docSnap = await getDoc(docRef);

            if (docSnap.exists()) {
                return { id: docSnap.id, ...docSnap.data() } as TestAttempt;
            }
            return null;
        } catch (error) {
            console.error("Error fetching test attempt:", error);
            return null;
        }
    },

    async getLastTestAttempt(userId: string, testId: string): Promise<TestAttempt | null> {
        try {
            const attemptsRef = collection(db, "testAttempts");
            // Index required: userId ASC, testId ASC, startTime DESC
            // If index missing, might fail. 
            // Workaround: Filter by user and test, then sort in memory if needed, or rely on simple query?
            // "where" clauses can be combined. sorting by startTime requires index.

            const q = query(
                attemptsRef,
                where("userId", "==", userId),
                where("testId", "==", testId),
                where("status", "==", "completed"),
                orderBy("startTime", "desc"),
                limit(1)
            );

            const snapshot = await getDocs(q);
            if (!snapshot.empty) {
                const doc = snapshot.docs[0];
                return { id: doc.id, ...doc.data() } as TestAttempt;
            }
            return null;
        } catch (error) {
            console.error("Error fetching last test attempt:", error);
            return null;
        }
    },

    async getUserAttempts(userId: string, status?: 'completed' | 'in_progress'): Promise<TestAttempt[]> {
        try {
            const attemptsRef = collection(db, "testAttempts");
            let q;

            if (status) {
                q = query(
                    attemptsRef,
                    where("userId", "==", userId),
                    where("status", "==", status),
                    orderBy("startTime", "desc")
                );
            } else {
                q = query(
                    attemptsRef,
                    where("userId", "==", userId),
                    orderBy("startTime", "desc")
                );
            }

            const snapshot = await getDocs(q);
            return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as TestAttempt));
        } catch (error) {
            console.error("Error fetching user attempts:", error);
            return [];
        }
    },

    async getActiveAttempt(userId: string): Promise<TestAttempt | null> {
        try {
            const attemptsRef = collection(db, "testAttempts");
            const q = query(
                attemptsRef,
                where("userId", "==", userId),
                where("status", "==", "in_progress"),
                limit(1)
            );

            const snapshot = await getDocs(q);
            if (!snapshot.empty) {
                const doc = snapshot.docs[0];
                return { id: doc.id, ...doc.data() } as TestAttempt;
            }
            return null;
        } catch (error) {
            console.error("Error fetching active attempt:", error);
            return null;
        }
    },

    // --- Users ---
    async getUsers(): Promise<User[]> {
        try {
            const usersRef = collection(db, "users");
            const q = query(usersRef, orderBy("createdAt", "desc"));
            const querySnapshot = await getDocs(q);

            const users: User[] = querySnapshot.docs.map((doc) => {
                const data = doc.data() as UserData;

                // Map Firestore UserData to Admin User type
                return {
                    id: data.uid,
                    name: data.name || "Unknown",
                    email: data.email,
                    role: (data.role as 'student' | 'admin' | 'developer') || 'student', // Cast primarily for UI
                    joinedAt: data.createdAt ? new Date(data.createdAt.toMillis()).toLocaleDateString() : 'N/A',
                    testsTaken: data.performanceSummary?.totalTestsAttempted || 0,
                    avgScore: data.performanceSummary?.overallAverageScore || 0,
                    isActive: true, // Logic could be added based on lastLoginAt
                    paymentStatus: Object.keys(data.purchasedTests || {}).length > 0 ? 'paid' : 'free'
                };
            });
            return users;
        } catch (error) {
            console.error("Error fetching users:", error);
            return [];
        }
    },

    async updateUserRole(uid: string, newRole: 'student' | 'admin' | 'developer'): Promise<boolean> {
        try {
            const userRef = doc(db, "users", uid);
            await updateDoc(userRef, { role: newRole });
            return true;
